const P=["book-tcmf-6","smartedu-tcmf","shutcm-tcmf-syllabus"],u="2026-08-08",r=e=>({...e,courseId:"tcm-fundamentals",sourceIds:[...P],verification:"verified",verifiedAt:u}),d="tcmf-essence",R=[...P],$=e=>({...e,unitId:d,sourceIds:R,verifiedAt:u}),V=[$({id:"essence-01-philosophy",title:"古代哲学精气观的认识边界",order:1,depth:"foundation",estimatedMinutes:18,overview:"古代哲学精气观用“精气”解释天地万物的生成、运动和统一，为中医学认识生命提供了思想工具；它与人体之精、人体之气相互影响但层次不同，也不能直接等同于现代物质、能量或粒子概念。",paragraphs:["哲学精气观首先讨论的是世界本原和万物变化。古人以精气的聚散、运动和相互作用说明事物的生成、形态与消亡，并强调看似不同的事物具有共同基础、处于持续变化之中。这一认识为中医形成整体观和恒动观提供了背景：人体不是孤立静止的部件集合，生命活动与自然环境也处在联系中。学习这一层要抓“普遍的物质性认识、运动变化、聚散成形”三个方向，而不是急于把“气”翻译成呼吸气体、电流或某种实验室单一指标。","哲学概念进入医学后会被具体化。医学更关心人体之精的来源贮藏、人体之气的生成运动及其与脏腑经络的联系，因此同一个“精”或“气”字在不同语境中观察对象并不完全相同。哲学之精气可以作为解释世界与生命的一般范畴，人体之精气则属于中医生命理论中的具体概念。二者有思想传承和结构联系，却不能把哲学命题直接当成人体生理结论。答题时要先看题干在讨论天地万物还是人体功能，再决定概念层级。","认识边界还包括传统模型与现代科学的关系。传统精气理论可以帮助理解教材内部的生成、运动、联系和转化，但不能凭名称相似就说精等于基因、生殖细胞，或气等于氧气、神经冲动、能量。现代研究可讨论某些相关现象，却需要明确操作定义、测量方法和证据，不能以单一对应替代理论分析。最稳妥的表达是：精气观是一套历史形成的概念模型，对中医理论结构有基础作用；学习时既理解其内部逻辑，也保留跨学科比较的证据边界。"],examples:[{title:"先判断语境",explanation:"“精气聚而成形”多处于哲学层面；“肾藏精、精能化气”进入人体生命理论。相同文字不代表两个命题的观察对象完全相同。"}],relationships:[{from:"哲学精气观",relation:"提供",to:"整体与运动的思想工具"},{from:"一般精气范畴",relation:"进入医学后具体化为",to:"人体之精与人体之气"},{from:"传统概念模型",relation:"不能直接等同",to:"现代单一可测实体"}],pitfalls:["把哲学之精与人体之精视为完全相同的概念。","把气直接等同于空气、氧气或能量。","用一个现代名词取代传统理论中的全部关系。"],selfChecks:["哲学精气观与人体精气理论的联系和区别是什么？","为什么“传统概念可研究”不等于“可直接翻译为现代单一实体”？"]}),$({id:"essence-02-human-essence",title:"人体之精的基本概念",order:2,depth:"foundation",estimatedMinutes:19,overview:"人体之精是构成人体和维持生命活动的重要物质基础，既可作广义总称，也可在特定语境中指较具体的精微物质。读题时必须根据来源、贮藏、功能与语境辨别其含义。",paragraphs:["广义的人体之精可概括禀受于父母并得到后天水谷精微充养的生命物质基础，贯穿生长、发育、生殖、脏腑功能和生命维持。教材用“精”强调物质的精微、宝贵和基础性，并不意味着它是一种成分单一、位置固定的现代解剖物质。人体各类精微物质在理论上有来源、化生和贮藏联系，因此有时“精”是总称，有时又依据功能或部位进一步命名。理解层级比死记一句定义更重要。","狭义语境常突出与生殖相关的精，但“人体之精”不能被缩小为生殖之精。肾精既与生长发育和生殖有关，也参与维持脏腑功能、化生气血等更广范围；脏腑之精则可指由水谷精微化生、输布并供脏腑利用和贮藏的精微物质。题干若谈构成人体、维持生命或先后天相互充养，通常使用广义；若明确生殖成熟、繁衍等线索，才更接近狭义侧重。不要只见“精”字便自动选生殖。","人体之精具有相对稠厚、内守和作为化生基础的理论特点，但这只是与气、津液等概念比较时的侧重。精可以化气，气也参与精的生成和固摄，说明物质基础与功能活动不是截然分开的实体。回答名词解释时可按“是什么—从哪里来—有什么作用—边界是什么”组织：先写重要物质基础，再写先天与后天来源，接着写生长发育生殖和脏腑活动，最后避免将其等同于单一生殖物质或现代指标。"],examples:[{title:"广义与狭义判断",explanation:"题干写“构成人体、维持一生”时取广义；题干明确“生殖繁衍”时可讨论狭义，但仍要说明狭义属于人体之精的特定语境。"}],relationships:[{from:"先天禀受与后天充养",relation:"共同构成",to:"人体之精"},{from:"人体之精",relation:"奠定",to:"生长发育与脏腑活动基础"},{from:"广义人体之精",relation:"在特定语境包含",to:"生殖之精"}],pitfalls:["把人体之精只理解为生殖之精。","把“物质基础”误解为已经找到单一现代化学成分。","忽略同一“精”字在广义与狭义语境中的层次。"],selfChecks:["人体之精的广义与狭义怎样区分？","请按定义、来源、作用和边界四步口述人体之精。"]}),$({id:"essence-03-congenital-acquired",title:"先天之精与后天之精",order:3,depth:"understanding",estimatedMinutes:20,overview:"先天之精禀受于父母，是生命形成与个体禀赋的基础；后天之精由饮食水谷经脾胃等功能化生。二者来源有别，却相互依存、相互充养，不是出生前后彼此隔绝的两份物质。",paragraphs:["先天之精强调生命开始前后已获得的禀赋基础，与生长发育、生殖能力和体质基础相关。它在生命形成时具有先导意义，但“先天”不等于一切表现都被固定决定，也不等于只在出生前存在。出生后先天之精仍参与生命活动，并需要后天之精不断补充和养护。教材中的“禀受于父母”是一种传统理论表述，不能未经论证就等同于遗传物质；现代遗传、表观遗传和发育环境有各自严谨概念。","后天之精来自饮食水谷，经受纳、运化、输布等功能转为可供全身利用的精微物质。这里不仅是“吃进去”这一步，还包括消化吸收、化生与输布的整体理论过程。饮食充足并不自动保证后天之精充盛，脾胃功能、饮食结构、生活状态和消耗也会影响化生利用。后天之精一方面维持日常脏腑形体活动，另一方面持续充养先天之精，使先天基础能够在生命过程中发挥作用。","二者关系可用“先天促后天、后天养先天”记忆。先天禀赋为后天化生提供基础和动力条件，后天精微又补充、滋养先天之精；二者汇合成为人体之精的重要来源。考试常用“根本”与“来源”混淆：先天有根本和禀赋意义，后天是出生后持续获得充养的主要途径，不能据此断言后天可以无限补足任何先天差异，也不能说先天一经消耗就完全无法得到后天支持。正确答案通常强调相互依存而各有侧重。"],examples:[{title:"双向箭头记忆",explanation:"先天之精→为后天化生提供基础；后天之精→持续充养先天。画成双向联系，但在箭头旁分别写清作用，避免只背“相互资生”。"}],relationships:[{from:"父母禀受",relation:"形成",to:"先天之精"},{from:"水谷化生",relation:"形成",to:"后天之精"},{from:"先天之精与后天之精",relation:"相互充养汇合为",to:"人体之精"}],pitfalls:["把先天之精直接等同于基因或生殖细胞。","认为先天与后天之精出生后彼此隔绝。","只记来源差异，不会说明二者相互充养。"],selfChecks:["先天之精与后天之精的来源和作用侧重分别是什么？","怎样解释“先天促后天、后天养先天”？"]}),$({id:"essence-04-generation-storage",title:"精的生成、贮藏与功能",order:4,depth:"exam",estimatedMinutes:22,overview:"精的理论主线是“先后天生成—输布汇聚—肾主封藏—支持生长发育生殖及脏腑活动”。贮藏不是静止封存，功能也不限于生殖，而是生成、使用、补充和固护的动态统一。",paragraphs:["人体之精的生成来源于先天禀受和后天水谷化生。后天精微经脾胃化生后输布全身，供脏腑形体使用，也可汇聚充养肾精；各脏腑正常活动又为精的继续化生和利用创造条件。生成因此不是某一脏单独完成的瞬间事件，而是受纳、运化、输布、贮藏和消耗相互衔接的过程。复习时应把“来源”和“过程环节”分开：先天、后天回答来自哪里，脾胃化生、输布与肾藏精回答怎样形成和保存。","肾藏精强调肾对精的封藏、贮存和调节作用，使精不致无故流失，并按生命阶段发挥功能。藏不是仓库式静止不动，而是“藏中有用、用中有藏”的动态状态。肾精又可分先天与后天来源侧重，并在生命过程中表现为促进生长发育、生殖成熟，参与气血化生，濡养脏腑形体和维持生命活动。题目若只说“肾精等于生殖之精”，范围过窄；若把所有精都说成只存在于肾中，也忽略脏腑之精和输布利用。","精的功能可整理为四组：繁衍生命，促进生长发育，化生气血并参与濡养，维持脏腑功能和抵御不利影响。不同教材表达可能略有组合，但答题应围绕物质基础及其化生作用展开。判断精的失常也要看年龄阶段、来源、消耗和相关功能，不能由单一疲劳或外观表现自我诊断。基础题最常考“肾藏精”“精能化气”“先后天相互充养”三条联系，写答案时应明确箭头方向和概念层级。"],examples:[{title:"把“藏”理解为动态调节",explanation:"水库比喻只能帮助理解储备，不能忘记精持续得到补充、按需要发挥作用并受到固护；真正得分点是“贮藏与调节”，不是静止容器。"}],relationships:[{from:"先天禀受与后天化生",relation:"生成充养",to:"人体之精"},{from:"肾",relation:"贮藏调节",to:"精"},{from:"精",relation:"支持",to:"生长发育生殖与脏腑活动"}],pitfalls:["把肾藏精理解为精静止存放在一个解剖容器中。","把精的全部功能缩小为生殖。","混淆“精的来源”和“精的贮藏环节”。"],selfChecks:["请用一条流程说明精的生成、输布、贮藏和使用。","精的主要功能可归纳成哪四组？"]}),$({id:"essence-05-qi-concept",title:"气的概念与生成来源",order:5,depth:"foundation",estimatedMinutes:20,overview:"人体之气是构成人体和维持生命活动的精微物质，也是推动、调控各类生命过程的功能表现。气的生成以先天之精、水谷精气和自然界清气为来源，并依赖相关脏腑功能协同。",paragraphs:["人体之气的定义包含物质与功能两面。说它是精微物质，强调生命活动有物质基础；说它具有推动调控作用，强调气通过运动和气化表现生命功能。二者不能拆成“物质气”和“功能气”两种毫不相干的东西。教材中的气有时作总称，有时进一步分为元气、宗气、营气、卫气或脏腑之气，必须根据来源、分布和功能判断具体含义。气也不能直接等同于呼吸之气，呼吸取得的清气只是生成来源之一。","气的来源通常概括为肾中精气、脾胃化生的水谷精气以及肺吸入的自然界清气。肾中精气与先天禀赋和肾精化生有关，水谷精气体现后天饮食化生，清气体现呼吸取得。三者并非自行混合就完成生成，还需肺、脾胃、肾等功能协调：脾胃为生化之源，肺主气并参与宗气形成和气的宣发肃降，肾精化气并有纳气等联系。考试若问“主要物质来源”，答三类；若问“相关脏腑”，再答肺脾肾及其作用。","生成之后，气还需要不断运行、补充和消耗。饮食、呼吸、先天基础、劳逸与脏腑状态都会影响气的充足和功能，但不能把日常口语中的“没气”直接当成教材气虚证。学习概念时可使用“来源—生成脏腑—运动—功能”四格：先回答气从何来，再说明由谁参与化生，接着进入升降出入，最后连接推动、温煦、防御、固摄和气化等作用。这样能避免把本章气的生成与后面气的分类和功能混成一张无层次的表。"],examples:[{title:"物质来源与相关脏腑不是同一问法",explanation:"自然界清气、水谷精气、肾中精气回答“材料从哪里来”；肺、脾胃、肾回答“哪些功能环节参与生成和调节”。"}],relationships:[{from:"肾中精气",relation:"参与生成",to:"人体之气"},{from:"水谷精气与自然界清气",relation:"汇合化生",to:"人体之气"},{from:"肺脾肾协同",relation:"保障",to:"气的生成与运行"}],pitfalls:["把人体之气只理解为呼吸空气。","把气的物质性与功能性割裂为两个实体。","混淆气的三类来源与肺脾肾三个功能环节。"],selfChecks:["人体之气的定义为什么要同时写物质与功能两面？","请分别回答气的物质来源和参与生成的主要脏腑。"]}),$({id:"essence-06-movement",title:"气的升降出入",order:6,depth:"understanding",estimatedMinutes:21,overview:"升、降、出、入是气运动的基本形式：升降概括上下方向，出入概括内外方向。四者在不同脏腑和过程中的具体表现各异，共同维持生命活动的连续与协调。",paragraphs:["气的运动称为气机，升降出入是最基本的方向。升指由下向上或提升，降指由上向下或下降，出指由内向外，入指由外向内。方向词必须与具体对象和过程相连，不能认为凡“升”一定好、凡“降”一定坏。例如脾气主升、胃气主降，各守其位才有利于饮食物的受纳运化；肺气既有宣发向外向上，也有肃降向内向下，二者相互协调。判断正常与否的标准不是方向名称，而是是否符合该功能系统的生理趋势。","升降与出入既可分别讨论，也常在同一过程交织。呼吸有清气入、浊气出，肺的宣降又调节气与津液布散；饮食物进入、精微上输、糟粕下行和排出也包含多方向运动。全身之气周流不息，需要各脏腑气机既有自身规律又相互衔接。某一方向太过、不及或逆乱，可能影响整体，但“气逆”“气陷”等具体概念要结合后续气血津液和病机章节学习，本节先掌握正常方向模型。","做排序或匹配题时，先确定空间轴，再找主体。看到“上下”先在升降中选，看到“内外”先在出入中选；随后核对题干是在描述正常趋势还是失常方向。不要只凭动词字面判断，如“吸入”明显属入，但“胃气下降”属于降而不是出。四种运动的协调体现恒动观：生命稳定由不断而有序的运动维持；若升降出入完全停止，生命活动也难以维系。复述时要写“基本形式＋相互协调＋联系具体脏腑过程”三个层次。"],examples:[{title:"先画坐标轴",explanation:"纸上画上下与内外两条轴：脾升胃降放在上下轴，呼吸清气入与浊气出放在内外轴，再说明肺宣降可能同时涉及两轴。"}],relationships:[{from:"气机",relation:"基本形式",to:"升降出入"},{from:"各脏腑气机",relation:"相互衔接形成",to:"全身气的协调运动"},{from:"升降出入协调",relation:"维持",to:"正常生命活动"}],pitfalls:["认为升一定正常、降一定异常。","把上下方向的降与内外方向的出混为一谈。","脱离具体脏腑和过程背诵四个方向。"],selfChecks:["升降与出入分别对应哪一条空间轴？","为什么判断气的运动是否正常必须结合主体和生理趋势？"]}),$({id:"essence-07-qi-dynamics-transformation",title:"气机、气化与生命活动",order:7,depth:"exam",estimatedMinutes:22,overview:"气机侧重气本身的运动状态，气化侧重气的运动推动物质、能量与功能发生转化的过程。二者密切联系：气机通畅是气化正常的重要条件，气化又体现生命活动的生成与变化。",paragraphs:["气机回答“气怎样运动”，包括升降出入以及运动是否通畅协调；气化回答“在气的运动作用下发生了什么转化”。饮食转化为精微与糟粕、精化气、气化生血、津液生成输布排泄以及汗尿形成等，都可从气化角度理解。只要题干强调位置和方向，首先考虑气机；强调物质之间转化、生成、利用或排泄，才更直接指向气化。气化不是现代化学反应的同义词，而是中医用来概括生命过程中多类转化的理论范畴。","气机与气化的联系可用“运动为条件，转化为表现”概括。气的升降出入有序，使精微能够输布、废物能够排出、脏腑功能得以协调；气化过程正常又不断生成气血津液等生命物质，支持新的气机活动。二者互为条件但不能互换。考试干扰项常把“推动某物移动”与“把某物转化为另一物”混在一起：前者更偏运行推动，后者更偏气化。若同一材料同时写运动和转化，应根据问题问的直接环节作答。","进一步看，气的推动、温煦、防御、固摄和气化等作用也不是完全割裂。推动使运动发生，温煦提供生命活动的温热条件，固摄防止精血津液无故流失，气化完成生成转化；在一个复杂过程中可能有多项共同参与。课程复习要学会“主作用优先”：找题干最直接的动词和结果，再讨论协同。真实生理过程可由现代医学从多层机制研究，本节传统概念只用于理解中医理论内部的功能分类，不能据单一日常表现自行判断气机或气化失常。"],examples:[{title:"移动还是转化",explanation:"“将水谷精微输送到全身”偏推动与气机；“水谷化为精微与糟粕”偏气化。若题干两者皆有，问题问哪一步就回答哪一步。"}],relationships:[{from:"气的升降出入",relation:"构成",to:"气机"},{from:"气的运动与功能",relation:"推动",to:"物质功能转化即气化"},{from:"正常气化",relation:"生成支持",to:"新的生命活动"}],pitfalls:["把气机与气化当作同义词。","看到“变化”二字就一律选择气化，不看是否只是位置方向变化。","把气化直接等同于现代化学反应或能量代谢。"],selfChecks:["气机与气化的观察焦点分别是什么？","请各举一个偏气机和偏气化的教材式例子，并写出判断动词。"]}),$({id:"essence-08-jing-qi-shen",title:"精气神关系及应用边界",order:8,depth:"exam",estimatedMinutes:22,overview:"精、气、神分别侧重物质基础、运动功能和生命活动整体表现，三者相互依存、相互化生。学习重点是关系而非把它们分成三个封闭实体，更不能据此替代对心理、神经或躯体问题的专业评估。",paragraphs:["精为重要物质基础，气是由精化生并推动调控生命活动的精微物质与功能表现，神广义上是生命活动的总体表现，狭义可指意识、思维、情志等精神活动。三者各有侧重，但不在三个互不相干的“容器”里。精充可为气的生成提供基础，气行气化使精得到生成、输布和固护，精气充盛又为神的活动提供物质与功能条件；神的状态也能通过情志、行为和调节影响气机及精的消耗与养护。","教材常用精能化气、气能生精摄精、精气生神和神能御精驭气等关系说明三者互用。记忆时先抓方向：精到气是化生，气到精包括生成和固摄，精气到神是物质功能基础支持整体表现，神对精气则偏统御和调节。方向并非简单线性链，因为生命活动中三者不断循环影响。题目若说“精气神完全独立”显然错误；若说三者完全没有区别，也同样错误。关系题要同时写“有分工”和“相互依存”。","神不能被简单等同于灵魂，也不能把中医“神”的全部含义等同于某一个现代心理或神经指标。面色、目光、言语、反应等在中医望神中可作为整体状态线索，但不应由此给个人贴心理或疾病标签。学习应用时可用精—气—神框架整理教材关系，现实中出现意识改变、严重情绪困扰或功能受损，应按现代医疗和心理健康规范寻求帮助。答案的边界句可写：精气神理论概括传统生命整体关系，具体问题仍需完整资料与相应学科方法。"],examples:[{title:"关系网而非三格抽屉",explanation:"画三角形：精↔气、精气→神、神→调节精气；每条边写明化生、固摄、支持或调节，比按三列孤立背诵更接近教材逻辑。"}],relationships:[{from:"精",relation:"化生并提供基础",to:"气"},{from:"精与气充盛协调",relation:"支持",to:"神的活动"},{from:"神的统御调节",relation:"影响",to:"精气活动"}],pitfalls:["把精、气、神理解为三个完全孤立的实体。","把神简单等同于灵魂或单一现代神经指标。","用精气神框架对个人意识或情绪问题自行诊断。"],selfChecks:["请用有方向的关系说明精、气、神如何相互作用。","精气神各有侧重又不可分割，这句话怎样展开成得分答案？"]})],x=e=>({...e,unitId:d,sourceIds:R,verifiedAt:u}),G=[x({id:"essence-c01-philosophy-human",title:"哲学之精与人体之精",items:["哲学之精","人体之精"],dimensions:[{label:"概念层级",values:{哲学之精:"解释万物本原与生成的一般范畴",人体之精:"解释人体构成与生命维持的医学概念"}},{label:"观察对象",values:{哲学之精:"天地万物",人体之精:"人体生命活动"}},{label:"主要作用",values:{哲学之精:"提供整体运动的思想工具",人体之精:"作为生长发育生殖等物质基础"}},{label:"常见陷阱",values:{哲学之精:"直接套用人体功能",人体之精:"误当单一现代物质"}}],decisionRule:"先看题干讨论万物生成还是人体生命；前者偏哲学层，后者偏医学层。",commonTrap:"因文字相同便认为二者定义、对象和功能完全相同。",example:"“精气聚散形成万物”偏哲学，“肾藏精”属于人体生命理论。"}),x({id:"essence-c02-essence-qi",title:"精与气",items:["精","气"],dimensions:[{label:"主要侧重",values:{精:"较稠厚、内守的物质基础",气:"精微物质及推动调控功能"}},{label:"运动特点",values:{精:"偏贮藏并可化生",气:"升降出入、运行不息"}},{label:"关系",values:{精:"能化气并为气之基础",气:"能生精、摄精并推动精的利用"}},{label:"常见陷阱",values:{精:"只等同生殖之精",气:"只等同呼吸气体"}}],decisionRule:"题干强调基础、贮藏、化生来源偏精；强调运动推动调控偏气。",commonTrap:"把物质基础与功能活动割裂，忽略精气相互化生。",example:"“升降出入”直接说气的运动，“肾藏”更直接说精的贮藏。"}),x({id:"essence-c03-essence-fluid",title:"精与津液",items:["精","津液"],dimensions:[{label:"范围侧重",values:{精:"构成与维持生命的重要精微物质总称或特定精质",津液:"正常水液的总称"}},{label:"性状功能",values:{精:"偏基础、贮藏、化生",津液:"偏滋润、濡养、充养血脉"}},{label:"来源联系",values:{精:"先天与后天来源",津液:"主要由饮食水谷化生"}},{label:"常见陷阱",values:{精:"凡精皆液体",津液:"凡水液皆属于精"}}],decisionRule:"题干强调正常水液生成输布和滋润选津液；强调先后天基础和肾藏精选精。",commonTrap:"因二者都属物质基础且可相互影响，就把概念完全合并。",example:"汗、涕、唾等属津液应用范围，不能直接称为生殖之精。"}),x({id:"essence-c04-congenital-acquired",title:"先天之精与后天之精",items:["先天之精","后天之精"],dimensions:[{label:"来源",values:{先天之精:"禀受于父母",后天之精:"由饮食水谷化生"}},{label:"作用侧重",values:{先天之精:"奠定禀赋和生命基础",后天之精:"持续供养脏腑并充养先天"}},{label:"时间特点",values:{先天之精:"出生后仍发挥作用",后天之精:"出生后不断化生补充"}},{label:"常见陷阱",values:{先天之精:"等同遗传物质且绝不改变",后天之精:"只要多吃就一定充盛"}}],decisionRule:"父母禀受选先天，水谷化生选后天；问二者关系则答相互依存充养。",commonTrap:"把二者分成出生前后完全隔绝的两份物质。",example:"后天水谷精微持续充养肾精，体现后天养先天。"}),x({id:"essence-c05-kidney-reproductive",title:"肾精与生殖之精",items:["肾精","生殖之精"],dimensions:[{label:"范围",values:{肾精:"肾所藏之精的广泛概念",生殖之精:"与生殖繁衍直接相关的特定侧重"}},{label:"功能",values:{肾精:"生长发育、生殖、化生与脏腑维持",生殖之精:"突出成熟与生殖"}},{label:"关系",values:{肾精:"包含并支持生殖功能",生殖之精:"不能代表肾精全部"}},{label:"常见陷阱",values:{肾精:"只理解为生殖细胞",生殖之精:"扩大为全部人体之精"}}],decisionRule:"题干兼有生长发育、脏腑濡养等广泛功能选肾精；只突出繁衍时才偏生殖之精。",commonTrap:"把肾精、生殖之精和现代生殖细胞三者画等号。",example:"儿童生长发育与肾精关系不能只用生殖之精解释。"}),x({id:"essence-c06-qi-qiji",title:"气与气机",items:["气","气机"],dimensions:[{label:"定义",values:{气:"人体精微物质及推动调控功能的概念",气机:"气的运动状态和规律"}},{label:"观察对象",values:{气:"来源、分类、功能与运动",气机:"升降出入是否协调"}},{label:"范围",values:{气:"较广",气机:"属于气理论中的运动方面"}},{label:"常见陷阱",values:{气:"只当空气",气机:"与气完全同义"}}],decisionRule:"问“什么是气”答总体概念；问运动方向、通畅与逆乱答气机。",commonTrap:"看见“气”字便忽略题干实际在问运动状态。",example:"脾升胃降协调描述的是气机，不是气的三类生成来源。"}),x({id:"essence-c07-qiji-qihua",title:"气机与气化",items:["气机","气化"],dimensions:[{label:"核心",values:{气机:"气的运动",气化:"气推动的生成与转化"}},{label:"题干动词",values:{气机:"升降出入、运行、逆陷",气化:"化生、转化、生成、排泄"}},{label:"结果",values:{气机:"位置方向与运动状态改变",气化:"物质或功能形态改变"}},{label:"常见陷阱",values:{气机:"把一切运动都叫气化",气化:"等同现代化学反应"}}],decisionRule:"先问只是“移动”，还是“转成另一种生命物质或功能状态”。",commonTrap:"题干同时有运动与转化时不看问题所问的直接环节。",example:"津液输布偏气机推动，饮食化为精微偏气化。"}),x({id:"essence-c08-rise-fall-in-out",title:"升降与出入",items:["升降","出入"],dimensions:[{label:"空间轴",values:{升降:"上下轴",出入:"内外轴"}},{label:"基本方向",values:{升降:"向上或向下",出入:"向外或向内"}},{label:"常见主体",values:{升降:"脾胃、肺等气机趋势",出入:"呼吸、腠理开合等过程"}},{label:"常见陷阱",values:{升降:"认为升永远好",出入:"把降与出混同"}}],decisionRule:"先画上下、内外两条轴，再把题干动词放入对应方向。",commonTrap:"只凭“离开原处”就把下降误判为出。",example:"胃气下降属于降，浊气呼出属于出。"}),x({id:"essence-c09-transform-each-other",title:"精化气与气生精",items:["精化气","气生精"],dimensions:[{label:"方向",values:{精化气:"精→气",气生精:"气→精"}},{label:"侧重",values:{精化气:"物质基础化生功能活动",气生精:"气化推动精微生成"}},{label:"共同点",values:{精化气:"体现精气相互化生",气生精:"体现精气相互化生"}},{label:"常见陷阱",values:{精化气:"箭头写反",气生精:"忽略气还有摄精作用"}}],decisionRule:"概念名称第一个字是起点，末字是结果，先写箭头再作答。",commonTrap:"只背“精气互化”却在方向题中选反。",example:"题干“肾精化生元气”方向是精到气。"}),x({id:"essence-c10-jing-qi-shen",title:"精气神三者关系与三个孤立实体",items:["精气神关系","三个孤立实体"],dimensions:[{label:"结构",values:{精气神关系:"有分工又相互依存化生",三个孤立实体:"彼此隔绝"}},{label:"观察焦点",values:{精气神关系:"物质基础、运动功能、整体表现",三个孤立实体:"只列三个名称"}},{label:"动态性",values:{精气神关系:"双向影响并随生命活动变化",三个孤立实体:"没有作用方向"}},{label:"常见陷阱",values:{精气神关系:"因联系而取消区别",三个孤立实体:"只背三列定义"}}],decisionRule:"完整答案必须同时写各自侧重与至少两条有方向的联系。",commonTrap:"把“不可分”误解为“三者没有差别”。",example:"精能化气、精气生神、神能调节精气，构成关系网而非三格抽屉。"})],H=[{id:"essence-m01-definition",unitId:d,priority:"must-recite",prompt:"人体之精的基本定义是什么？",answer:"人体之精是构成人体和维持生命活动的重要物质基础，来源包括先天禀受和后天水谷化生。",relatedSectionId:"essence-02-human-essence"},{id:"essence-m02-congenital",unitId:d,priority:"must-recite",prompt:"先天之精与后天之精的来源分别是什么？",answer:"先天之精禀受于父母；后天之精由饮食水谷经脾胃等功能化生。",relatedSectionId:"essence-03-congenital-acquired"},{id:"essence-m03-mutual-nourish",unitId:d,priority:"must-recite",prompt:"先后天之精的关系怎样记？",answer:"先天为后天化生提供基础，后天持续充养先天，二者相互依存、相互充养。",mnemonic:"先天促后天，后天养先天",relatedSectionId:"essence-03-congenital-acquired"},{id:"essence-m04-functions",unitId:d,priority:"must-recite",prompt:"精的主要功能可归纳为哪四组？",answer:"繁衍生命；促进生长发育；参与化生气血和濡养；维持脏腑功能与生命活动。",relatedSectionId:"essence-04-generation-storage"},{id:"essence-m05-qi-sources",unitId:d,priority:"must-recite",prompt:"人体之气的三类主要来源是什么？",answer:"肾中精气、脾胃化生的水谷精气、肺吸入的自然界清气。",mnemonic:"肾精—水谷—清气",relatedSectionId:"essence-05-qi-concept"},{id:"essence-m06-movements",unitId:d,priority:"must-recite",prompt:"气的运动基本形式是什么？",answer:"升、降、出、入；升降对应上下方向，出入对应内外方向。",relatedSectionId:"essence-06-movement"},{id:"essence-m07-boundary",unitId:d,priority:"must-understand",prompt:"哲学精气观与人体精气理论怎样区分？",answer:"前者是解释天地万物的一般范畴，后者是解释人体构成与生命活动的具体医学概念。",relatedSectionId:"essence-01-philosophy"},{id:"essence-m08-broad-narrow",unitId:d,priority:"must-understand",prompt:"为什么人体之精不能等同于生殖之精？",answer:"人体之精广泛支持构成、发育、生殖和脏腑活动，生殖之精只是特定语境中的侧重。",relatedSectionId:"essence-02-human-essence"},{id:"essence-m09-storage",unitId:d,priority:"must-understand",prompt:"“肾藏精”的“藏”为何不是静止仓库？",answer:"它强调贮藏、固护和调节，精仍持续得到补充并按生命阶段发挥作用。",relatedSectionId:"essence-04-generation-storage"},{id:"essence-m10-qi-definition",unitId:d,priority:"must-understand",prompt:"人体之气的定义为什么有两面？",answer:"气既是构成人体的精微物质，又通过运动体现推动和调控生命活动的功能。",relatedSectionId:"essence-05-qi-concept"},{id:"essence-m11-organs",unitId:d,priority:"must-understand",prompt:"气的生成为什么要联系肺、脾胃、肾？",answer:"脾胃化生水谷精气，肺吸清气并主气，肾精化气，三者协同完成生成和调节。",relatedSectionId:"essence-05-qi-concept"},{id:"essence-m12-qiji-qihua",unitId:d,priority:"must-understand",prompt:"气机与气化怎样快速区分？",answer:"气机看升降出入与运动状态；气化看气推动的生成、转化和利用排泄过程。",mnemonic:"机看动，化看变",relatedSectionId:"essence-07-qi-dynamics-transformation"},{id:"essence-m13-relations",unitId:d,priority:"must-understand",prompt:"精气神关系的主干是什么？",answer:"精为基础并能化气，气能生精摄精，精气支持神，神又调节精气活动。",relatedSectionId:"essence-08-jing-qi-shen"},{id:"essence-m14-philosophy-limit",unitId:d,priority:"recognize",prompt:"看到“万物生成、聚散成形”应先定位到哪一层？",answer:"先定位到古代哲学精气观，再判断题干是否进一步进入人体生命理论。",relatedSectionId:"essence-01-philosophy"},{id:"essence-m15-modern-limit",unitId:d,priority:"recognize",prompt:"精和气能否分别直接翻译为基因与能量？",answer:"不能。跨学科比较需要操作定义和证据，单一现代名词不能覆盖传统概念的全部关系。",relatedSectionId:"essence-01-philosophy"},{id:"essence-m16-clinical-limit",unitId:d,priority:"recognize",prompt:"精气神理论的个人应用边界是什么？",answer:"可用于理解教材关系，不能由单一日常表现自行诊断；现实问题需完整专业评估。",relatedSectionId:"essence-08-jing-qi-shen"}],q=e=>({...e,unitId:d,sourceIds:R,verifiedAt:u}),J=[q({id:"essence-w01",type:"term-definition",prompt:"名词解释：人体之精",answerOutline:["写构成人体和维持生命的重要物质基础","写先天与后天来源","写广义与特定语境"],scoringPoints:["物质基础","来源","生命功能","不等同生殖之精"]}),q({id:"essence-w02",type:"term-definition",prompt:"名词解释：气机",answerOutline:["气机是气的运动","基本形式为升降出入","正常状态强调协调通畅"],scoringPoints:["运动","四种形式","协调","不同于气化"]}),q({id:"essence-w03",type:"short-answer",prompt:"简述精的生成、贮藏与主要功能。",answerOutline:["先天禀受和后天水谷化生","精微输布汇聚并由肾贮藏调节","列生长发育生殖、化生濡养、脏腑维持"],scoringPoints:["来源","肾藏精","至少三组功能","动态贮藏"]}),q({id:"essence-w04",type:"short-answer",prompt:"简述人体之气的生成来源及相关脏腑。",answerOutline:["肾中精气","水谷精气","自然界清气","说明肺脾肾各自作用"],scoringPoints:["三类来源","肺","脾胃","肾"]}),q({id:"essence-w05",type:"comparison",prompt:"比较先天之精与后天之精。",answerOutline:["比较来源","比较作用侧重","说明出生后均参与生命活动","说明相互充养"],scoringPoints:["父母禀受","水谷化生","先天促后天","后天养先天"]}),q({id:"essence-w06",type:"comparison",prompt:"比较气机与气化。",answerOutline:["共同属于气的生命活动","气机侧重运动方向状态","气化侧重生成转化","说明运动为转化提供条件"],scoringPoints:["升降出入","生成转化","联系","不能等同"]}),q({id:"essence-w07",type:"analysis",prompt:"分析“精、气、神是三个彼此独立实体”为什么错误。",answerOutline:["先写三者各自侧重","精能化气与气能生精摄精","精气支持神","神调节精气"],scoringPoints:["分工","至少三条有方向联系","相互依存","概念边界"]}),q({id:"essence-w08",type:"analysis",prompt:"说明学习精气理论时如何处理传统概念与现代科学的关系。",answerOutline:["理解传统理论内部对象和关系","区分哲学与医学层次","跨学科比较需操作定义与证据","不做机械一一对应"],scoringPoints:["内部逻辑","层次","证据边界","不替代专业评估"]})],L=[r({id:"q-tcm-essence-13",unitId:d,conceptId:"tcm-essence-origin",type:"single-choice",prompt:"关于人体之精的理解，哪一项最准确？",options:["只指生殖细胞","是构成人体和维持生命的重要物质基础，具有先天与后天来源","等同于全部津液","出生后只剩后天之精"],answer:1,explanation:"人体之精是广义生命物质基础，先后天来源相互充养，不能缩小为单一生殖物质。",misconceptionFeedback:{0:"生殖之精只是特定语境，不能代表人体之精全部。",2:"精与津液有联系但范围和功能侧重不同。",3:"先天之精出生后仍发挥作用并得到后天充养。"}}),r({id:"q-tcm-essence-14",unitId:d,conceptId:"tcm-essence-motion",type:"single-choice",prompt:"题干强调“水谷由饮食物转化为精微与糟粕”，最直接体现什么？",options:["气机的升降","气化","精的封藏","天人相应"],answer:1,explanation:"题干核心是物质形态与功能状态的转化，属于气化；若只强调上下内外移动才更偏气机。",misconceptionFeedback:{0:"升降只说明方向，不能覆盖水谷转化为不同产物。",2:"封藏侧重贮存固护，与题干转化过程不同。",3:"题干没有讨论自然环境与人体适应。"}}),r({id:"q-tcm-essence-15",unitId:d,conceptId:"tcm-essence-origin",type:"true-false",prompt:"先天之精只存在于出生以前，出生后的人体完全依靠后天之精。",answer:!1,explanation:"先天之精在出生后仍作为禀赋和生命基础发挥作用，并得到后天之精持续充养。",misconceptionFeedback:{true:"把“先天”误解为时间截止点，忽略先天之精出生后的持续作用。"}}),r({id:"q-tcm-essence-16",unitId:d,conceptId:"tcm-essence-qi-spirit",type:"matching",prompt:"将精、气、神与最主要的学习侧重点配对。",pairs:[{left:"精",right:"生命的重要物质基础"},{left:"气",right:"运动、推动与调控"},{left:"神",right:"生命活动的整体表现"}],answer:["精=>生命的重要物质基础","气=>运动、推动与调控","神=>生命活动的整体表现"],explanation:"三者有各自侧重，同时通过化生、支持和调节相互联系。",misconceptionFeedback:{"":"先按“基础—运动功能—整体表现”定位，再记三者不是孤立实体。"}}),r({id:"q-tcm-essence-17",unitId:d,conceptId:"tcm-essence-motion",type:"ordering",prompt:"按“先确定空间轴，再判断方向”的方法排列气运动判断步骤。",items:["找出运动主体和过程","判断题干是上下轴还是内外轴","确定升、降、出或入","核对该方向是否符合主体的生理趋势"],answer:["找出运动主体和过程","判断题干是上下轴还是内外轴","确定升、降、出或入","核对该方向是否符合主体的生理趋势"],explanation:"先有主体和过程，再用空间轴定位方向，最后结合生理趋势判断是否协调。",misconceptionFeedback:{"":"若先把“升”判为好、“降”判为坏，就会脱离主体与生理规律。"}}),r({id:"q-tcm-essence-18",unitId:d,conceptId:"tcm-essence-generation-storage",type:"scenario",prompt:"复习卡写着“父母禀赋为基础，水谷精微在出生后持续补充并反过来充养这一基础”。它最直接说明哪组关系？",options:["先天之精与后天之精相互充养","升与降彼此对立","精与津液完全相同","神独立控制精气"],answer:0,explanation:"题干同时出现父母禀受和水谷化生，并强调后天持续充养先天，正是先后天之精关系。",misconceptionFeedback:{1:"题干讨论精的来源与充养，不是气的运动方向。",2:"水谷可化生多类精微物质，不能推出精与津液完全相同。",3:"精气神相互作用，但“神独立控制”否定了物质基础和双向联系。"}})],N={chapter:{unitId:d,title:"精气学说",introduction:"本章从哲学精气观与人体精气概念的边界开始，依次掌握人体之精、先后天之精、精的生成贮藏功能、气的来源与升降出入，再用气机—气化和精—气—神两张关系网完成整合。",sections:V,confusions:G,memoryItems:H,writtenPrompts:J,summary:["哲学精气观是一般认识范畴，人体精气是具体医学概念，二者有联系但不等同。","人体之精是广义生命物质基础，不能缩小为生殖之精。","先天之精禀受父母，后天之精源于水谷；先天促后天，后天养先天。","肾藏精是动态的贮藏、固护和调节，不是静止仓库。","气来源于肾中精气、水谷精气与自然界清气，并依赖肺脾肾协同。","升降看上下，出入看内外；方向是否正常必须结合具体主体。","气机看运动，气化看生成转化；二者密切联系而不可互换。","精为基础、气主运动功能、神为整体表现，三者分工又相互依存。"]},questions:L},p="tcmf-five-phases",A=[...P],k=e=>({...e,unitId:p,sourceIds:A,verifiedAt:u}),Y=[k({id:"five-01-model",title:"五行不是五种静态材料",order:1,depth:"foundation",estimatedMinutes:19,overview:"五行以木、火、土、金、水五个名称概括五类功能属性及其相互关系，重点在运动趋势、作用特点与系统联系，而不是把世界机械拆成五种固定材料。",paragraphs:["“行”含有运行、变化和类属的意思。木火土金水最初与自然经验有关，进入五行学说后则成为五类特性的标志：木强调生长、升发和条达，火强调温热、升腾和光明，土强调生化、承载和受纳，金强调肃降、收敛与变革，水强调滋润、下行和闭藏。判断某事物归属哪一行，依据是题干突出哪种功能趋势，而不是看它的名称、颜色或材料中是否真的含有木头、火焰、泥土、金属和水。","五行学说包含两项基本任务：一是用取象比类把自然、人体和疾病中的相关现象整理为五个功能系统；二是用相生、相克、制化、乘侮和母子相及说明系统之间的资生、制约与异常变化。前者回答“属于哪一类”，后者回答“各类怎样相互作用”。若只背五行归类表，就会把五行学成静态标签；若只背生克圆环，又不知道圆环中的每个节点为何这样归类。真正理解需要把特性、归类和关系三层连接起来。","五行是一种传统关系模型，不是现代化学元素周期表，也不能直接等同于五个器官或五种疾病。肝归木，指藏象理论中肝系统某些功能与木的升发条达特性相类，不表示解剖肝脏由木构成；季节、方位、色味等归类也用于表达同类联系，不能由单一对应项推出个人诊断。做题第一步先确认题目在问实物、功能特性、归类还是关系方向，再选择相应规则，避免被“木”“火”等字面形象带走。"],examples:[{title:"字面名称不等于五行属性",explanation:"木制桌子作为材料是木，但题目若问某功能“向上升发、向外舒展”，即使没有木字，也应从木的功能特性分析。"}],relationships:[{from:"自然经验中的木火土金水",relation:"抽象为",to:"五类功能特性"},{from:"功能特性",relation:"用于",to:"取象比类与归类"},{from:"五类系统",relation:"通过生克制化联系为",to:"动态整体"}],pitfalls:["把五行当成五种静止材料。","只凭名称或颜色归类，不看功能趋势。","把五行系统机械等同于现代器官和实验指标。"],selfChecks:["为什么五行的“行”比五种物质的“种”更重要？","请说明五行学说的“归类”和“关系”两项任务。"]}),k({id:"five-02-properties",title:"木火土金水的功能特性",order:2,depth:"foundation",estimatedMinutes:21,overview:"五行特性是所有归类和关系题的根基。学习时应从经典概括词出发，扩展成功能方向、过程动词和反例，而不是只背五个四字标签。",paragraphs:["木曰曲直。曲直兼含屈伸、生长和向上向外舒展，后世常概括为生长、升发、条达、舒畅。题干出现萌发、生长、伸展、疏通和保持舒畅时，常从木性考虑。火曰炎上，突出温热、升腾、明亮和向上；不能把所有温度升高都机械归火，还要看题目是否在五行分类语境。木与火都可向上，但木偏生长展开，火偏温热升腾，这是高频易混点。","土爰稼穑。稼穑包含播种收获，引申为生化、承载、受纳，强调居中协调和把输入转为可利用资源。金曰从革，从是顺从，革是变革，常概括为清洁、肃降、收敛和变革。土与金都可能出现“转化”含义，但土更偏生化承载，金更偏收敛肃降与更新变革。答题时要找最直接的功能动词，不要因为“生产”带有金属工业联想就误选金。","水曰润下，突出滋润、下行、寒凉、闭藏。水与金都可有向下趋势，但水偏滋润下行与闭藏，金偏肃降收敛；水与土都与水谷或水液相关，却分别代表不同功能特性。五行特性不是互不接触的五个抽屉，同一复杂事物可从不同侧面呈现多种特征；具体归类要服从题目所选角度。在给定教材表中答案有相对确定性，不能以“多侧面”为由随意改变。复习可为每一行各写“核心动词、常见场景、易混对象”三栏。"],examples:[{title:"用动词而非名词判断",explanation:"“萌发舒展”更接近木，“温热升腾”更接近火，“承载化生”更接近土，“肃降收敛”更接近金，“滋润下行”更接近水。"}],relationships:[{from:"木",relation:"核心趋势",to:"生长升发条达"},{from:"火与土",relation:"分别侧重",to:"温热升腾与生化承载"},{from:"金与水",relation:"分别侧重",to:"肃降收敛与滋润下行闭藏"}],pitfalls:["只背“曲直炎上稼穑从革润下”却不会翻成功能动词。","把木的升发和火的升腾完全混同。","认为一个对象在任何讨论角度下只能有一种五行特征。"],selfChecks:["请为五行各写两个核心功能动词。","木与火、金与水分别怎样区分？"]}),k({id:"five-03-analogy",title:"取象比类与归类步骤",order:3,depth:"understanding",estimatedMinutes:21,overview:"取象比类是根据被观察对象的功能、形态、方向和变化特征，与五行典型特性比较后归入相应类别。它要求抓主导特征和共同关系，不是凭表面相似自由联想。",paragraphs:["“取象”不是只看外形，而是提取能够代表对象运动和功能的特征；“比类”是把这些特征与已有类别比较，找出主要相似关系。较可靠的步骤是：确定观察对象和题目角度，提取核心功能动词，与五行特性逐一比较，选择主导类别，最后用同类对应和关系规则核对。例如春季万物萌发生长，与木的升发生长相类，故春归木；这不是因为春天真的含有木，而是功能趋势相似。","归类必须受角度限制。同一个对象若讨论不同侧面，可能出现不同类比，但教材中的标准表是为特定理论目的建立的稳定对应。考试通常已经限定角度，学生应先识别题干所用的教材体系，而不是随意发明新归类。表面相似常造成错误：红色物体不因颜色就必然属火，向下运动也不一定属水，必须看题目是在考标准对应、功能特性还是一般方位。只有当证据层级一致，比较才有效。","取象比类的优势是能把分散现象整理成网络，帮助发现同类联系；局限是类比本身不能证明现代因果，也不能替代具体机制和证据。学习时要区分“归为同类”与“互为原因”：肝、目、筋、怒、春在传统五行表中同属木，说明理论上的同类联系，不代表任何一个项目变化都必然造成其他项目变化。答题可以写“因其具有某特性，故类属于某行”，同时保留模型边界。"],examples:[{title:"四步归类示范",explanation:"题干写“某过程具有生长、升发、舒展趋势”：先圈出三个动词，再与五行特性比较，木的匹配度最高，最后用木曰曲直核对。"}],relationships:[{from:"观察对象",relation:"提取",to:"核心功能之象"},{from:"核心功能之象",relation:"比较",to:"五行特性"},{from:"主导相似关系",relation:"形成",to:"五行归类"}],pitfalls:["把取象理解为只看外形和颜色。","用一个表面相似点覆盖题干的主要功能。","把同类对应误说成已经证明直接因果。"],selfChecks:["取象比类的四个判断步骤是什么？","为什么同属一行不等于彼此存在固定单向因果？"]}),k({id:"five-04-classification-table",title:"五行归类表的理解方法",order:4,depth:"exam",estimatedMinutes:23,overview:"五行归类表要横向理解同一行的系统联系，纵向比较同一类别的差异，并以五行特性解释对应，而不是按几十个孤立格子逐项硬背。",paragraphs:["常见自然归类可整理为：木应春、东、风、青、酸；火应夏、南、暑或热、赤、苦；土应长夏或季夏、中、湿、黄、甘；金应秋、西、燥、白、辛；水应冬、北、寒、黑、咸。不同教材表格项目和名称可能略有差异，应以学校指定版本为准。记忆关键是看季节过程：春生、夏长、长夏化、秋收、冬藏，与木生发、火炎热、土生化、金收敛、水闭藏形成结构对应。","人体归类常以五脏为中心：肝胆、目、筋、怒、泪等归木；心小肠、舌、脉、喜、汗等归火；脾胃、口、肉、思、涎等归土；肺大肠、鼻、皮、悲忧、涕等归金；肾膀胱、耳及二阴、骨髓、恐、唾等归水。表格项目要理解所属层级：脏与腑是表里联系，官窍与形体是功能外联，情志与液体是传统对应。不能把一列中的所有词解释成完全相同的实体。","高效复习用“横向成串、纵向辨差、空表回填”。横向任选一行，从季节、方位、脏腑、官窍、形体、情志和液体依次回忆；纵向只比较同一类别，如五季或五官，避免跨层混淆；最后使用空表遮盖答案，先依据特性推理再核对。错题要记录错在特性没懂、行序混乱还是表格位置混淆。归类表是后续生克解释的节点地图，但单一对应项不能直接用于个人辨证，必须结合多项资料与具体理论。"],examples:[{title:"用季节过程串联五行",explanation:"春生→木，夏长与炎热→火，长夏生化→土，秋收→金，冬藏→水；先记过程，再扩展同一行的方位、脏腑和官窍。"}],relationships:[{from:"同一行各项目",relation:"构成",to:"横向同类系统"},{from:"五季五脏五官等同类项目",relation:"纵向比较",to:"五行差异"},{from:"五行归类节点",relation:"进入关系分析形成",to:"生克网络"}],pitfalls:["把归类表背成互不关联的几十个格子。","混淆横向同类联系与纵向同类别比较。","由一个颜色、情志或季节对应直接作个人诊断。"],selfChecks:["请任选一行，从自然与人体两方面横向复述。","为什么空表回填前要先写五行特性和季节过程？"]}),k({id:"five-05-generation",title:"相生关系与母子定位",order:5,depth:"exam",estimatedMinutes:23,overview:"相生表示一行对另一行的资生、助长或促进。固定方向是木生火、火生土、土生金、金生水、水生木；对任一行而言，生我者为母，我生者为子。",paragraphs:["相生必须带方向。完整次序为木生火、火生土、土生金、金生水、水生木，形成首尾相接的环。可借自然意象帮助初记，但考试得分依赖箭头而不是故事：写“木火相生”不如写“木→火”，因为前者可能掩盖谁资生谁。相生表示正常情况下的资助和促进，不意味着越多越好，也不是唯一关系；同一行还会受到相克调节，生与克共同维持协调。","母子定位完全由箭头决定。对某一目标行来说，直接生它的是母，它直接生的是子。以火为例，木生火，所以木为火之母；火生土，所以土为火之子。换成金，土生金，土为金之母；金生水，水为金之子。做题可把目标行圈在中间，向前沿相生环找母，向后找子。不要背“木永远是母、火永远是子”，母子是相对于特定目标而言的关系称谓。","母子关系为解释正常资生、异常传变和部分治则提供方向基础。母病及子沿相生方向由母影响子，子病及母逆相生方向由子影响母；虚则补其母、实则泻其子则是基于母子关系的理论原则，具体应用仍需辨证。首先掌握正常相生与相对定位，再学习异常，不要一上来把生、病传和治法三条箭头混为一谈。答题时写清起点、终点与关系名称，能显著减少方向错误。"],examples:[{title:"目标行定位法",explanation:"问“肺属金，金之母与子为何？”先写土→金→水，所以土为金之母，水为金之子；不要从器官名称直接猜。"}],relationships:[{from:"木",relation:"生",to:"火"},{from:"火土金水",relation:"依次相生并回到",to:"木"},{from:"生我者与我生者",relation:"分别称为",to:"母与子"}],pitfalls:["只背相生环却不写箭头方向。","把某一行永久记成母或子，忽略关系的相对性。","认为相生一定越多越好，忽略制约和适度。"],selfChecks:["请闭眼写出完整相生次序。","以水为目标，谁是母、谁是子？请写出推理箭头。"]}),k({id:"five-06-control",title:"相克关系与所胜所不胜",order:6,depth:"exam",estimatedMinutes:23,overview:"相克表示一行对另一行的制约、抑制和调节。固定方向是木克土、土克水、水克火、火克金、金克木；我克者为所胜，克我者为所不胜。",paragraphs:["相克同样必须带方向。完整次序为木克土、土克水、水克火、火克金、金克木。它不是单纯破坏，而是在正常范围内限制偏亢，使各行保持有序。自然意象可辅助记忆，如木能疏土、土能制水、水能制火、火能熔金、金能制木，但意象只作记忆桥梁，不能替代教材规则或扩展为现代因果。相克太过才可能演变为相乘，相克关系受到反向异常影响时可表现为相侮。","所胜与所不胜以“我”为参照。我克者是我能够制约的一方，称所胜；克我者是能够制约我的一方，称所不胜。以木为我，木克土，所以土是木之所胜；金克木，所以金是木之所不胜。以水为我，水克火，火为水之所胜；土克水，土为水之所不胜。最稳的方法是写两条句式：“我→克→谁”“谁→克→我”，绝不能用字面上“谁更强”判断。","相生的母子与相克的所胜所不胜属于两套坐标。一个目标行同时有母、子、所胜、所不胜四个邻接关系，例如木之母为水、子为火、所胜为土、所不胜为金。做综合题时先画相生箭头，再画相克箭头，避免把“生我者”误写成“克我者”。相克的正常意义是调节，不等于病理伤害；只有题干明确太过、不及、反向侵犯或病理传变时，才进入乘侮分析。"],examples:[{title:"四邻定位",explanation:"以土为中心：火生土，火为母；土生金，金为子；土克水，水为所胜；木克土，木为所不胜。四条关系分两组写。"}],relationships:[{from:"木土水火金",relation:"依次形成相克环并回到",to:"木"},{from:"我克者",relation:"称为",to:"所胜"},{from:"克我者",relation:"称为",to:"所不胜"}],pitfalls:["把相克一律理解为有害破坏。","凭“强弱”字面猜所胜所不胜。","把母子关系与所胜所不胜混在一条箭头上。"],selfChecks:["请写出完整相克次序。","以金为中心，分别写出所胜与所不胜，并说明箭头。"]}),k({id:"five-07-regulation",title:"生克制化与动态协调",order:7,depth:"understanding",estimatedMinutes:22,overview:"制化指相生与相克相互配合，使资生不过度、制约不太过，五行系统在持续运动中维持相对协调。它不是相克的同义词，而是生中有制、制中有生的整体调节。",paragraphs:["只有相生而没有相克，资生可能失去限制；只有相克而没有相生，制约又可能缺乏恢复和支持。制化强调生与克共同存在：一行得到母行资生，同时受所不胜制约，并对其子与所胜发挥作用。以木为例，水生木提供资助，金克木形成制约，木又生火、克土。四种邻接关系把木放在网络中，而不是单独圆点。系统协调来自多条关系的共同作用。","“制则生化”可理解为适度制约有助于正常生化，而不是克制本身越强越好。正常相克维持边界，正常相生提供动力，两者通过反馈使偏盛得到限制、偏弱得到支持。制化与动态平衡相似，都强调变化中的相对协调，但五行制化专门说明五类系统的生克网络；阴阳平衡则用相反相成的双方关系概括更广范围。考试问“相生相克共同维持协调”时，应答制化，而非只答相克。","理解制化可以防止把五行圆环看成两条互不相关的线。画图时为一个目标行同时标母、子、所胜、所不胜，再问资生与制约怎样避免任何一方无限扩张。若网络某环节太过或不及，原有制化关系可能失常，出现相乘、相侮或母子相及。这里是方向性模型，不等于一个脏腑必然按圆环造成另一个脏腑疾病；具体分析还需病因、证候、病势和完整资料。"],examples:[{title:"以木为中心看制化",explanation:"水生木、金克木、木生火、木克土。资生与制约同时存在，木的状态由网络调节，不能只看“水生木”一条线。"}],relationships:[{from:"相生",relation:"提供",to:"资助与促进"},{from:"相克",relation:"提供",to:"限制与调节"},{from:"生克相互配合",relation:"形成",to:"制化与动态协调"}],pitfalls:["把制化等同于相克。","认为生永远有益、克永远有害。","用生克网络直接断言现实中的固定器官因果。"],selfChecks:["为什么只有相生或只有相克都不能完整解释五行协调？","制化与相克、阴阳平衡分别有何区别？"]}),k({id:"five-08-pathological-relations",title:"相乘相侮及母子相及",order:8,depth:"exam",estimatedMinutes:26,overview:"相乘、相侮是相克异常，母病及子、子病及母是相生关系上的异常传变。判断时先确认正常箭头，再比较病理方向：相乘沿相克方向加重，相侮沿相克反方向，母病及子沿相生，子病及母逆相生。",paragraphs:["相乘是相克太过，方向与正常相克相同，但强度超过正常调节。例如木克土是正常关系，木过强或土过弱导致木对土制约太过，称木乘土。相侮是反向克制，方向与正常相克相反。例如正常金克木，若木过强或金过弱，木反过来影响金，称木侮金。乘与侮都可由一方太强或另一方太弱引起，不能只凭“强者欺负弱者”的故事判断，必须先写出正常相克箭头。","相乘与相侮可同时出现。某一行过强，既可能沿正常相克方向乘其所胜，也可能反向侮其所不胜。例如木过强可乘土，同时侮金。以目标行为中心看，乘多发生在“我克者”方向，侮则可能指向“克我者”的反方向。题目若只说影响加重而没有方向，信息不足；考试通常会给出两行关系，先判断正常是谁克谁，再看病理箭头是否同向。口诀只能在规则之后使用：“同克为乘，反克为侮”。","母病及子与子病及母属于相生链异常。母病及子沿相生方向，如水生木，水为母、木为子，水的问题影响木；子病及母逆相生方向，由子反过来影响母。它们与相乘相侮的区别在于所依托的正常关系不同：前者看相生母子，后者看相克正反。母子传变也只是传统病机分析方向，不能只凭五行表确定现实个案。四类题统一采用“先正常、后异常；先方向、后名称”的流程。"],examples:[{title:"四种方向写法",explanation:"木→克土，病理同向加重为木乘土；金→克木，若木反向影响金为木侮金；水→生木，水影响木为母病及子，木影响水为子病及母。"}],relationships:[{from:"正常相克同方向太过",relation:"称为",to:"相乘"},{from:"正常相克反方向侵犯",relation:"称为",to:"相侮"},{from:"相生顺向与逆向传变",relation:"分别称为",to:"母病及子与子病及母"}],pitfalls:["不先写正常相克箭头就直接判断乘侮。","认为相乘只由克者过强造成，忽略被克者过弱。","把母子相及与乘侮混用，未区分相生和相克基础。"],selfChecks:["如何用正常相克箭头区分相乘与相侮？","水与木之间，怎样分别表示母病及子和子病及母？"]}),k({id:"five-09-application",title:"生理病理诊断防治中的应用边界",order:9,depth:"exam",estimatedMinutes:24,overview:"五行学说用于组织脏腑系统联系、解释部分病理传变、综合诊察线索并概括治则方向。它提供关系框架而非自动诊断器，任何应用都要结合藏象、病因病机、四诊资料和具体证候。",paragraphs:["生理方面，五行归类把五脏与六腑、官窍、形体、情志和自然环境联系起来，生克制化说明功能系统之间既相互资助又相互制约。病理方面，可用母子相及和乘侮描述某些功能失调的传变方向。例如一脏失调可能影响其所生、所克或克己者，但这不是每个个案都必然按固定圆环发展。题目要求说明“可能的理论关系”时可使用五行，要求确立具体证候时还必须结合寒热虚实、气血津液与病程。","诊察方面，色、味、脉、官窍、情志和季节等五行对应可作为综合线索，但单一线索特异性不足。正确做法是多项资料同向支持，并与病位病性相互验证；错误做法是见青色就断肝病、见怒就断木亢。五行归类帮助提出和组织假设，不替代现代检查或完整四诊。尤其真实健康问题中，明显症状应按专业规范评估，不应由网页知识表自行诊断。","防治方面，教材常见“虚则补其母，实则泻其子”，以及抑强扶弱、调整相乘相侮等方向。虚则补其母是利用母能生子的关系支持不足一方，实则泻其子是借子分泄母之有余；这是传统治则层面的概括，不能不辨证便直接套入个人选穴、处方或用药。考试先确定五行归属和虚实，再定位母子，最后回答原则层级。五行应用的合格结尾应写明：关系模型必须服从当前证候和完整资料。"],examples:[{title:"治则题的安全推理层级",explanation:"若教材题明确“某行虚”并问五行治则，先找其母再答“虚则补其母”的方向；不要越级给真实个人推荐药物或针刺方案。"}],relationships:[{from:"五行归类与生克",relation:"组织",to:"生理功能联系"},{from:"乘侮与母子相及",relation:"概括",to:"部分病理传变方向"},{from:"证候与虚实判断",relation:"约束",to:"五行防治原则应用"}],pitfalls:["用一个颜色、情志或季节线索直接诊断。","认为所有疾病必然按生克圆环固定传变。","不辨证便把五行治则变成个人处方或选穴建议。"],selfChecks:["五行在生理、病理、诊察和防治四方面分别承担什么作用？","为什么虚则补其母、实则泻其子仍必须服从辨证？"]})],I=e=>({...e,unitId:p,sourceIds:A,verifiedAt:u}),Z=[I({id:"five-c01-model-materials",title:"五行与五种实物",items:["五行","五种实物"],dimensions:[{label:"本质",values:{五行:"五类功能属性及关系模型",五种实物:"具体材料或物体"}},{label:"观察重点",values:{五行:"运动趋势和作用特点",五种实物:"组成、形态和用途"}},{label:"是否固定",values:{五行:"归类依题目角度和教材规则",五种实物:"对象身份不靠类比改变"}},{label:"考试陷阱",values:{五行:"把名称当材料",五种实物:"因含某材料便推出理论归属"}}],decisionRule:"题目问升降、生化、收敛等功能关系时看五行；问实际材料时看实物。",commonTrap:"认为肝属木就表示肝脏由木构成。",example:"“木曰曲直”在五行中指生长升发特性，不是木材定义。"}),I({id:"five-c02-analogy-superficial",title:"取象比类与表面相似",items:["取象比类","表面相似"],dimensions:[{label:"依据",values:{取象比类:"主导功能、方向和变化规律",表面相似:"单一颜色、名称或外形"}},{label:"步骤",values:{取象比类:"定角度、取特征、比五行、再核对",表面相似:"看到一点就下结论"}},{label:"结果",values:{取象比类:"形成有规则的类别联系",表面相似:"容易产生任意联想"}},{label:"考试陷阱",values:{取象比类:"忽略题干角度",表面相似:"红色物品一律属火"}}],decisionRule:"能否写出主导功能动词和教材归类依据，是区分二者的关键。",commonTrap:"把“象”只理解为外观图像。",example:"春归木依据萌发生长趋势，不只是春天看到树木。"}),I({id:"five-c03-generation-control",title:"相生与相克",items:["相生","相克"],dimensions:[{label:"作用",values:{相生:"资生、促进、助长",相克:"制约、抑制、调节"}},{label:"方向例",values:{相生:"木生火",相克:"木克土"}},{label:"正常意义",values:{相生:"提供支持",相克:"限制偏亢"}},{label:"考试陷阱",values:{相生:"认为越多越好",相克:"认为一定有害"}}],decisionRule:"题干强调资助促进选生，强调适度限制调节选克，并写清起终点。",commonTrap:"只说“两行有关系”而不辨作用方式和方向。",example:"水生木是资生，金克木是制约，二者可同时调节木。"}),I({id:"five-c04-control-regulation",title:"相克与制化",items:["相克","制化"],dimensions:[{label:"范围",values:{相克:"两行之间的制约关系",制化:"相生与相克共同形成的系统协调"}},{label:"观察对象",values:{相克:"谁克谁",制化:"多条生克反馈"}},{label:"作用",values:{相克:"限制偏亢",制化:"使生而不过、克而不伤"}},{label:"考试陷阱",values:{相克:"扩大为整个调节网络",制化:"误当相克别名"}}],decisionRule:"只问制约箭头答相克，问生克配合维持整体协调答制化。",commonTrap:"看到“制”字就只选相克。",example:"水生木、金克木等多条关系共同调节木，体现制化。"}),I({id:"five-c05-mother-child",title:"母与子",items:["母","子"],dimensions:[{label:"定义",values:{母:"生我者",子:"我生者"}},{label:"箭头位置",values:{母:"目标行上游",子:"目标行下游"}},{label:"相对性",values:{母:"相对于目标行命名",子:"相对于目标行命名"}},{label:"考试陷阱",values:{母:"把某行永久当母",子:"不写目标行直接猜"}}],decisionRule:"把目标写中间，沿相生环向前找母、向后找子。",commonTrap:"认为木永远是母、火永远是子。",example:"对金而言，土生金故土为母，金生水故水为子。"}),I({id:"five-c06-victory",title:"所胜与所不胜",items:["所胜","所不胜"],dimensions:[{label:"定义",values:{所胜:"我克者",所不胜:"克我者"}},{label:"箭头",values:{所胜:"我→克→对方",所不胜:"对方→克→我"}},{label:"关系基础",values:{所胜:"正常相克",所不胜:"正常相克"}},{label:"考试陷阱",values:{所胜:"按字面强弱猜",所不胜:"与母混淆"}}],decisionRule:"把“我”代入两句固定句式，不凭强弱感受判断。",commonTrap:"把克我者写成我的所胜。",example:"对木而言，土是所胜，金是所不胜。"}),I({id:"five-c07-control-overacting",title:"相克与相乘",items:["相克","相乘"],dimensions:[{label:"方向",values:{相克:"正常相克方向",相乘:"与相克方向相同"}},{label:"强度",values:{相克:"适度调节",相乘:"制约太过"}},{label:"性质",values:{相克:"正常关系",相乘:"异常关系"}},{label:"考试陷阱",values:{相克:"见克就判病理",相乘:"不看太过或不及条件"}}],decisionRule:"方向同为克，关键看是否“太过”：正常为克，过度为乘。",commonTrap:"认为相乘方向与相克不同。",example:"木克土是正常相克，木过强或土过弱导致木乘土。"}),I({id:"five-c08-overacting-insulting",title:"相乘与相侮",items:["相乘","相侮"],dimensions:[{label:"相对正常克向",values:{相乘:"同向",相侮:"反向"}},{label:"机制",values:{相乘:"克制太过",相侮:"被克者反向侵犯克者"}},{label:"共同性质",values:{相乘:"相克异常",相侮:"相克异常"}},{label:"考试陷阱",values:{相乘:"误记为强者任意影响",相侮:"不知道先写正常克向"}}],decisionRule:"先写正常谁克谁；病理箭头同向为乘，反向为侮。",commonTrap:"只背“欺负、反欺负”的故事而忘记正常相克关系。",example:"金克木为正常，木反向影响金为木侮金。"}),I({id:"five-c09-mother-child-disease",title:"母病及子与子病及母",items:["母病及子","子病及母"],dimensions:[{label:"方向",values:{母病及子:"沿相生方向",子病及母:"逆相生方向"}},{label:"起点",values:{母病及子:"母先病",子病及母:"子先病"}},{label:"关系基础",values:{母病及子:"母子相生",子病及母:"母子相生"}},{label:"考试陷阱",values:{母病及子:"与相乘混淆",子病及母:"方向写成相生顺向"}}],decisionRule:"先定母子，再看谁先出现问题；母到子顺生，子到母逆生。",commonTrap:"看到传变就一律使用乘侮。",example:"水生木，水先病影响木为母病及子，木先病影响水为子病及母。"}),I({id:"five-c10-treatment",title:"虚则补其母与实则泻其子",items:["虚则补其母","实则泻其子"],dimensions:[{label:"前提",values:{虚则补其母:"目标行偏虚且符合辨证",实则泻其子:"目标行偏实且符合辨证"}},{label:"定位",values:{虚则补其母:"找生我的一行",实则泻其子:"找我生的一行"}},{label:"理论方向",values:{虚则补其母:"借母资生子",实则泻其子:"借子分泄母之有余"}},{label:"考试陷阱",values:{虚则补其母:"把母子找反",实则泻其子:"未辨虚实直接套用"}}],decisionRule:"先判断虚实，再以目标行为中心沿相生环前找母、后找子。",commonTrap:"只背口诀，不确认当前题目是否属于五行母子治则层面。",example:"教材题明确木虚时，其母为水，理论方向为补水以生木。"}),I({id:"five-c11-five-yinyang",title:"五行归类与阴阳归类",items:["五行归类","阴阳归类"],dimensions:[{label:"类别数",values:{五行归类:"五类功能系统",阴阳归类:"相反相成两方面"}},{label:"核心依据",values:{五行归类:"木火土金水特性",阴阳归类:"相关对象的相反属性"}},{label:"关系重点",values:{五行归类:"生克制化乘侮",阴阳归类:"制约互根消长转化"}},{label:"考试陷阱",values:{五行归类:"用阴阳上下表直接代替",阴阳归类:"认为所有问题必须五分"}}],decisionRule:"题干问五类特性及生克选五行，问相反双方及消长转化选阴阳。",commonTrap:"因两者都能归类，就混用判断规则。",example:"肝脾肺等五类联系用五行组织，寒热相反属性更直接用阴阳。"}),I({id:"five-c12-model-causality",title:"关系模型与固定因果结论",items:["关系模型","固定因果结论"],dimensions:[{label:"功能",values:{关系模型:"组织可能的资生制约和传变方向",固定因果结论:"声称一条箭头必然导致具体结果"}},{label:"证据要求",values:{关系模型:"需结合证候与完整资料",固定因果结论:"常忽略其他条件"}},{label:"适用范围",values:{关系模型:"传统理论学习和方向分析",固定因果结论:"错误扩大到所有个案"}},{label:"考试陷阱",values:{关系模型:"忘记边界句",固定因果结论:"由单一对应直接诊断"}}],decisionRule:"表述中有“结合、可能、在某证候下”更符合模型；“必然、仅凭一个线索”通常越界。",commonTrap:"把五行箭头当成现实世界唯一且自动发生的因果链。",example:"木乘土可作为病机关系方向，但不能据一项表现认定个人必有某脏疾病。"})],ee=[{id:"five-m01-definition",unitId:p,priority:"must-recite",prompt:"五行的基本含义是什么？",answer:"五行是木、火、土、金、水五类功能属性及其运动关系的概括，不是五种静态实物。",relatedSectionId:"five-01-model"},{id:"five-m02-properties",unitId:p,priority:"must-recite",prompt:"五行经典特性怎样完整表述？",answer:"木曰曲直，火曰炎上，土爰稼穑，金曰从革，水曰润下。",mnemonic:"曲—炎—稼—革—润",relatedSectionId:"five-02-properties"},{id:"five-m03-generation",unitId:p,priority:"must-recite",prompt:"五行相生次序是什么？",answer:"木生火、火生土、土生金、金生水、水生木。",relatedSectionId:"five-05-generation"},{id:"five-m04-control",unitId:p,priority:"must-recite",prompt:"五行相克次序是什么？",answer:"木克土、土克水、水克火、火克金、金克木。",relatedSectionId:"five-06-control"},{id:"five-m05-mother-child",unitId:p,priority:"must-recite",prompt:"母子关系的固定句式是什么？",answer:"生我者为母，我生者为子。",relatedSectionId:"five-05-generation"},{id:"five-m06-victory",unitId:p,priority:"must-recite",prompt:"所胜所不胜的固定句式是什么？",answer:"我克者为所胜，克我者为所不胜。",relatedSectionId:"five-06-control"},{id:"five-m07-overacting",unitId:p,priority:"must-recite",prompt:"相乘的定义与方向是什么？",answer:"相乘是相克太过，病理作用方向与正常相克方向相同。",relatedSectionId:"five-08-pathological-relations"},{id:"five-m08-insulting",unitId:p,priority:"must-recite",prompt:"相侮的定义与方向是什么？",answer:"相侮是反向克制，病理作用方向与正常相克方向相反。",relatedSectionId:"five-08-pathological-relations"},{id:"five-m09-transmission",unitId:p,priority:"must-recite",prompt:"母病及子与子病及母的方向是什么？",answer:"母病及子沿相生方向，子病及母逆相生方向。",relatedSectionId:"five-08-pathological-relations"},{id:"five-m10-treatment",unitId:p,priority:"must-recite",prompt:"五行母子治则口诀是什么？",answer:"虚则补其母，实则泻其子；应用前必须先辨虚实和证候。",relatedSectionId:"five-09-application"},{id:"five-m11-analogy",unitId:p,priority:"must-understand",prompt:"取象比类的四步是什么？",answer:"确定观察角度，提取核心功能特征，与五行特性比较，选择主导类别并核对。",relatedSectionId:"five-03-analogy"},{id:"five-m12-wood-fire",unitId:p,priority:"must-understand",prompt:"木的升发与火的炎上怎样区分？",answer:"木偏生长、舒展、条达，火偏温热、升腾、明亮。",relatedSectionId:"five-02-properties"},{id:"five-m13-metal-water",unitId:p,priority:"must-understand",prompt:"金的肃降与水的润下怎样区分？",answer:"金偏肃降、收敛、清洁与变革，水偏滋润、下行、寒凉与闭藏。",relatedSectionId:"five-02-properties"},{id:"five-m14-table",unitId:p,priority:"must-understand",prompt:"五行归类表怎样高效记忆？",answer:"横向把同一行串成系统，纵向比较五季五脏等同类项目，再用空表回填。",relatedSectionId:"five-04-classification-table"},{id:"five-m15-regulation",unitId:p,priority:"must-understand",prompt:"制化为什么不是相克的同义词？",answer:"制化是相生提供资助、相克提供限制，二者共同维持动态协调。",relatedSectionId:"five-07-regulation"},{id:"five-m16-four-neighbors",unitId:p,priority:"must-understand",prompt:"以一个目标行为中心要定位哪四个关系？",answer:"母、子、所胜、所不胜；前两者来自相生，后两者来自相克。",relatedSectionId:"five-07-regulation"},{id:"five-m17-multiply-insult",unitId:p,priority:"must-understand",prompt:"判断乘侮的统一流程是什么？",answer:"先写正常相克方向，再看病理箭头；同向太过为乘，反向侵犯为侮。",mnemonic:"先正常，后异常；同乘反侮",relatedSectionId:"five-08-pathological-relations"},{id:"five-m18-application",unitId:p,priority:"must-understand",prompt:"五行应用为什么必须结合辨证？",answer:"五行只提供归类与关系方向，具体病位病性和治则仍需完整四诊资料与证候判断。",relatedSectionId:"five-09-application"},{id:"five-m19-natural-table",unitId:p,priority:"recognize",prompt:"五季的五行次序怎样概括？",answer:"春木、夏火、长夏土、秋金、冬水；具体表项以学校指定教材为准。",relatedSectionId:"five-04-classification-table"},{id:"five-m20-body-table",unitId:p,priority:"recognize",prompt:"五脏的五行归属是什么？",answer:"肝木、心火、脾土、肺金、肾水。",relatedSectionId:"five-04-classification-table"},{id:"five-m21-simultaneous",unitId:p,priority:"recognize",prompt:"相乘和相侮能否同时出现？",answer:"可以。一行过强时可能乘其所胜，同时反侮其所不胜，但仍要依正常克向判断。",relatedSectionId:"five-08-pathological-relations"},{id:"five-m22-boundary",unitId:p,priority:"recognize",prompt:"五行关系的应用边界是什么？",answer:"可用于传统理论的归类和方向分析，不能由单一对应项作个人诊断或直接给出治疗方案。",relatedSectionId:"five-09-application"}],z=e=>({...e,unitId:p,sourceIds:A,verifiedAt:u}),te=[z({id:"five-w01",type:"term-definition",prompt:"名词解释：五行",answerOutline:["写木火土金水五类","写功能属性与运动关系","说明不是五种静态材料"],scoringPoints:["五类","功能特性","运动关系","模型边界"]}),z({id:"five-w02",type:"term-definition",prompt:"名词解释：五行制化",answerOutline:["写相生与相克同时存在","相生提供资助","相克提供制约","共同维持动态协调"],scoringPoints:["生","克","相互配合","动态平衡"]}),z({id:"five-w03",type:"short-answer",prompt:"简述五行的功能特性。",answerOutline:["按木火土金水顺序写经典概括","为每一行补充功能动词","指出归类看主导特性"],scoringPoints:["曲直","炎上","稼穑","从革","润下"]}),z({id:"five-w04",type:"short-answer",prompt:"简述取象比类的基本步骤与边界。",answerOutline:["确定观察角度","提取功能之象","与五行特性比较归类","同类联系不等于固定因果"],scoringPoints:["角度","主导特征","比较核对","边界"]}),z({id:"five-w05",type:"short-answer",prompt:"简述五行生克制化的基本内容。",answerOutline:["写相生完整次序","写相克完整次序","说明生为资助、克为调节","说明二者共同制化"],scoringPoints:["生向正确","克向正确","正常意义","制化"]}),z({id:"five-w06",type:"comparison",prompt:"比较相克、相乘与相侮。",answerOutline:["相克是正常制约","相乘是同克向太过","相侮是反克向侵犯","说明乘侮的强弱条件"],scoringPoints:["正常与异常","同向","反向","先写正常克向"]}),z({id:"five-w07",type:"comparison",prompt:"比较母病及子与子病及母。",answerOutline:["先写母子定位","母病及子沿相生","子病及母逆相生","与乘侮区别"],scoringPoints:["生我与我生","起点","方向","关系基础"]}),z({id:"five-w08",type:"comparison",prompt:"比较五行归类与阴阳归类。",answerOutline:["五行分五类功能系统","阴阳分相关对象相反方面","分别写主要关系规律","说明二者可配合但不能混用规则"],scoringPoints:["类别结构","归类依据","关系内容","边界"]}),z({id:"five-w09",type:"analysis",prompt:"以木为中心，分析其母、子、所胜、所不胜以及过强时可能出现的乘侮方向。",answerOutline:["水生木，水为母","木生火，火为子","木克土，土为所胜","金克木，金为所不胜","木过强可乘土并侮金"],scoringPoints:["四邻定位","生克箭头","木乘土","木侮金"]}),z({id:"five-w10",type:"analysis",prompt:"说明五行学说在诊察和防治应用中为什么不能机械套用。",answerOutline:["单一归类线索不足","关系方向不等于固定因果","必须结合病因病机和证候","治则不能越级变成个人方案"],scoringPoints:["多资料","辨证","模型边界","不作个人诊疗"]})],ie=[r({id:"q-tcm-five-13",unitId:p,conceptId:"tcm-properties",type:"single-choice",prompt:"题干强调“生长、升发、舒展、条达”的功能趋势，最符合哪一行的特性？",options:["木","火","土","金"],answer:0,explanation:"木曰曲直，主要概括生长、升发、舒展与条达；火更偏温热升腾。",misconceptionFeedback:{1:"火的核心是温热、升腾和明亮，不能只因都有向上趋势就选火。",2:"土偏生化、承载与受纳。",3:"金偏肃降、收敛与变革。"}}),r({id:"q-tcm-five-14",unitId:p,conceptId:"tcm-five-family-relations",type:"single-choice",prompt:"以金为目标行，其母、子、所胜、所不胜依次是？",options:["土、水、木、火","水、土、火、木","火、木、水、土","木、火、土、水"],answer:0,explanation:"土生金，土为母；金生水，水为子；金克木，木为所胜；火克金，火为所不胜。",misconceptionFeedback:{1:"把母子顺序写反，并混淆相克方向。",2:"火是金的所不胜，不是母；木是金的所胜，不是子。",3:"该组合没有依相生和相克箭头定位。"}}),r({id:"q-tcm-five-15",unitId:p,conceptId:"tcm-generation-control",type:"true-false",prompt:"相克在五行中只表示病理损害，健康状态下不应出现相克。",answer:!1,explanation:"正常相克是适度制约和调节，与相生共同形成制化；克制太过才可能成为相乘。",misconceptionFeedback:{true:"把正常调节与病理太过混为一谈。"}}),r({id:"q-tcm-five-16",unitId:p,conceptId:"tcm-five-family-relations",type:"matching",prompt:"将目标行与其“母—子”组合配对。",pairs:[{left:"木",right:"水—火"},{left:"火",right:"木—土"},{left:"土",right:"火—金"},{left:"金",right:"土—水"},{left:"水",right:"金—木"}],answer:["木=>水—火","火=>木—土","土=>火—金","金=>土—水","水=>金—木"],explanation:"沿相生环，目标行前一位为母、后一位为子。",misconceptionFeedback:{"":"先写木→火→土→金→水→木，再以每个目标向前找母、向后找子。"}}),r({id:"q-tcm-five-17",unitId:p,conceptId:"tcm-five-family-relations",type:"matching",prompt:"将关系名称与判断规则配对。",pairs:[{left:"所胜",right:"我克者"},{left:"所不胜",right:"克我者"},{left:"相乘",right:"沿正常相克方向太过"},{left:"相侮",right:"沿正常相克反方向"}],answer:["所胜=>我克者","所不胜=>克我者","相乘=>沿正常相克方向太过","相侮=>沿正常相克反方向"],explanation:"所胜所不胜用于正常克向定位，乘侮在此基础上比较同向太过与反向侵犯。",misconceptionFeedback:{"":"先固定“我克者—克我者”，再用“同向为乘、反向为侮”完成配对。"}}),r({id:"q-tcm-five-18",unitId:p,conceptId:"tcm-generation-control",type:"ordering",prompt:"将五行相克关系按从木开始的顺序排列。",items:["木克土","土克水","水克火","火克金","金克木"],answer:["木克土","土克水","水克火","火克金","金克木"],explanation:"相克环从木开始依次为木克土、土克水、水克火、火克金、金克木。",misconceptionFeedback:{"":"不要与相生环混用；先写“木土水火金”五个克向节点再核对。"}}),r({id:"q-tcm-five-19",unitId:p,conceptId:"tcm-overacting-insulting",type:"scenario",prompt:"正常关系为金克木。题干描述木过强，反过来影响金。最合适的关系名称是？",options:["木乘金","木侮金","金乘木","母病及子"],answer:1,explanation:"正常是金→克木，题干病理方向为木→金，沿相克反方向，因此是木侮金。",misconceptionFeedback:{0:"相乘必须沿正常相克方向；木并不正常克金。",2:"金乘木应是金沿正常克木方向制约太过，与题干方向相反。",3:"母病及子依托相生关系，不是相克反向。"}}),r({id:"q-tcm-five-20",unitId:p,conceptId:"tcm-five-family-relations",type:"scenario",prompt:"水生木。某理论题明确为水行先虚，继而影响木行不足。按五行传变应称为？",options:["子病及母","母病及子","木侮水","水乘木"],answer:1,explanation:"水为木之母，水先出现问题并沿相生方向影响木，属于母病及子。",misconceptionFeedback:{0:"子病及母应由木先出现问题，再逆相生方向影响水。",2:"水克火、土克水，水木之间不是正常相克关系。",3:"相乘依托正常相克，水与木在此是相生母子。"}})],ne={chapter:{unitId:p,title:"五行学说",introduction:"本章从五行功能特性和取象比类起步，学会横纵理解归类表；随后用明确箭头掌握相生、相克、制化、乘侮和母子相及，最后把诊察与治则放回辨证和证据边界。",sections:Y,confusions:Z,memoryItems:ee,writtenPrompts:te,summary:["五行是五类功能属性与关系模型，不是五种静态材料。","归类先定角度、提取功能之象，再与五行特性比较并核对。","相生为木火土金水再回木；生我者为母，我生者为子。","相克为木土水火金再回木；我克者为所胜，克我者为所不胜。","制化是相生资助与相克制约共同维持动态协调。","相乘同正常克向而太过，相侮沿正常克向的反方向。","母病及子沿相生方向，子病及母逆相生方向。","五行应用必须结合病因病机、四诊和证候，不能由单一归类作个人诊疗。"]},questions:ie},f="tcmf-system",B=[...P],T=e=>({...e,unitId:f,sourceIds:B,verifiedAt:u}),oe=[T({id:"system-01-formation",title:"理论体系的形成条件与发展线索",order:1,depth:"foundation",estimatedMinutes:18,overview:"中医学理论体系不是由某一位医家在某一时刻一次完成的，而是在古代哲学与自然知识的影响下，由长期医疗实践、经典整理、学术争鸣和历代验证逐步形成并持续发展的知识系统。",paragraphs:["理解“形成条件”要把思想工具、实践材料和知识整理三个层面分开。古人对天文、物候、历法、农事及生命现象的观察，为整体、变化、类比等认识方式提供了背景；长期诊疗实践积累了对症状组合、疾病过程、药物针灸反应的经验；文字与典籍的整理又把分散经验提升为可以传承、讨论和修正的概念体系。三者相互作用，才逐渐形成阴阳、五行、藏象、经络、病因病机、诊法治则等彼此联系的理论模块。把体系归因于单一哲学推演，会忽略实践基础；把它说成零散经验汇编，又会忽略概念之间已有的结构和推理规则。","学习发展线索时，不必把大量朝代人物堆成孤立年表，而要抓住“奠基—充实—分化—再整理”的逻辑。早期经典完成基本框架，后世医家面对不同疾病谱、地域气候和实践问题，对病因、证候、方药、温病、脏腑及诊治方法不断补充，并形成各有侧重的学术认识。所谓发展，不是每一代都推翻前代，也不是古代文字永远不变，而是在共同框架内解释新材料、校正旧认识、明确适用范围。现代学习仍应区分传统理论内部的概念逻辑、历史语境与现代科学研究问题，避免用一个现代名词直接替换一个中医概念。","考试常从“形成的决定性基础”和“理论发展的特点”设问。较稳妥的答题顺序是：先写长期医疗实践提供材料，再写古代哲学和自然知识提供认识工具，接着写经典整理使经验系统化，最后写历代临床与学术争鸣推动丰富发展。这里的“实践”不是只指药物经验，也包括诊察、针灸、养生和疾病过程观察；“哲学影响”也不等于理论全部由哲学演绎而来。用多因素、长期性、系统化和开放发展四个关键词，能避免单因论与静止观。"],examples:[{title:"怎样读一条学术发展材料",explanation:"若材料说某医家在既有框架上突出一种病因或治法，应理解为针对实践问题的深化，而不是据此判断整个中医学从该医家才开始。"}],relationships:[{from:"长期医疗实践",relation:"提供",to:"经验材料"},{from:"哲学与自然知识",relation:"提供",to:"认识工具"},{from:"经典整理与历代争鸣",relation:"促成",to:"体系化与发展"}],pitfalls:["把中医学理论体系说成某一人物一次创造。","只强调哲学来源而否定医疗实践的基础作用。","把历史概念与现代科学术语简单一一对应。"],selfChecks:["请用四个层次概括中医学理论体系的形成与发展。","为什么“长期经验积累”与“理论体系”不是同一个概念？"]}),T({id:"system-02-structure",title:"中医学理论体系的基本结构",order:2,depth:"foundation",estimatedMinutes:18,overview:"中医基础理论不是十个互不相干的章节，而是从世界观与方法、生命结构与功能、致病与变化、诊察与防治逐层展开的关系网；后面的辨证论治会调动前面多个模块共同解释资料。",paragraphs:["可把理论体系理解为四层结构。第一层是整体、恒动以及阴阳五行等一般认识工具，回答“怎样看联系和变化”；第二层是藏象、精气血津液神、经络和体质，回答“人体生命活动怎样组织”；第三层是病因、发病与病机，回答“失调从何而来、怎样演变”；第四层是诊法、辨证和防治原则，回答“怎样从资料形成方向性判断”。这些层次彼此依赖：没有人体功能网络，病机便失去载体；没有病机分析，治则就会变成背诵口号；没有四诊资料，辨证也没有证据入口。","理论之间既有分工，也会在同一问题中交叉。例如讨论水液代谢，可同时涉及脾的运化、肺的宣发肃降、肾的主水、三焦通道、气化作用以及津液输布；讨论一种外感过程，又可能联系六淫性质、正邪盛衰、体质差异、阴阳偏盛偏衰和治则方向。交叉并不意味着概念可以互换。每个概念都有特定观察对象和解释任务，学习时要先给概念定位，再画联系。最有效的笔记不是把所有箭头连在一起，而是写清每条箭头表示生成、推动、制约、输布还是阶段变化。","面对章节题，可以使用“层级定位法”。先问题目属于认识方法、正常生命、致病因素、病理变化还是诊治原则；再找同层核心概念；最后向上追溯总纲、向下联系应用。比如“同病异治”属于诊治原则，直接依据是证候不同；向上联系恒动观和个体差异，向下才表现为治法不同。若一开始跳到药物名称，就越过了证候与治则两个关键层级。体系结构帮助你知道某个答案为什么位于这一步，也帮助排除层次正确但并非直接答案的干扰项。"],examples:[{title:"从水液代谢画一张小网络",explanation:"先以“津液生成—输布—排泄”为主线，再分别接入脾、肺、肾、三焦和气化；每条线写明作用动词，避免把相关概念堆成名单。"}],relationships:[{from:"一般认识方法",relation:"统摄",to:"生命与疾病理论"},{from:"生命结构功能",relation:"提供载体",to:"病因病机分析"},{from:"四诊与辨证",relation:"连接",to:"治则治法"}],pitfalls:["把章节顺序误当成互不联系的知识孤岛。","看见概念相关就认为二者可以互换。","做题时从一个症状直接跳到具体治法，省略证候与病机层。"],selfChecks:["请把中医基础理论分成四个层次并各举一例。","为什么同一问题可以调用多种理论，却仍要保持概念边界？"]}),T({id:"system-03-body-holism",title:"人体自身是统一整体",order:3,depth:"understanding",estimatedMinutes:20,overview:"人体整体性强调脏腑、经络、形体、官窍以及精气血津液神之间在结构、功能和病理上相互联系。整体观察不是取消局部，而是把局部放回联系网络中确定其意义。",paragraphs:["人体统一首先表现为结构联系。以五脏为中心的功能系统通过经络内联脏腑、外络肢节，并与五体、官窍、情志、津液等建立对应联系。这里的“系统”不是现代解剖器官的简单扩大版，而是中医理论用于归纳多类功能表现的模型。某一局部有自己的位置与特点，同时又参与全身气血运行、津液输布和神志活动。学习藏象时若只背“某脏主某功能”，会漏掉功能之间的协同；若只说一切都相关，又会失去每个系统的主次和边界。","统一还表现为功能协同与病理影响。饮食精微的化生、气血的生成运行、水液代谢、呼吸与活动等，都依赖多个环节配合；一个环节异常可能沿既有联系影响其他环节，局部表现也可能反映更广的功能失调。因此整体分析要同时问三件事：局部发生了什么，它与哪些功能网络相连，当前资料中哪条联系最有解释力。不是所有远处表现都必然由同一原因造成，更不能只凭“整体相关”进行无限联想。整体观念提供的是搜集与组织证据的方向，不是跳过证据的许可。","整体与局部是层层嵌套的。临床和考试都需要准确描述局部表现，因为整体判断正是由具体资料建立；随后才把局部与脏腑、经络、气血津液及病程联系起来。一个合格答案常包含“局部事实—功能联系—整体解释”三步。例如题干给出目、筋、情志与月经等多类线索，若它们共同指向同一功能系统，整体联系的证据就更强；若只有一个孤立表现，结论应保持谨慎。传统理论用于课程学习时应清楚其概念模型属性，不能替代现代医学对急症和器质性疾病的检查。"],examples:[{title:"局部与整体的答题方式",explanation:"不要只写“眼睛属肝”。应写成：目为局部观察点，在藏象联系中与肝系统有关；还需结合其他资料判断这条联系是否是当前题目的主线。"}],relationships:[{from:"脏腑功能系统",relation:"通过经络联系",to:"形体官窍"},{from:"气血津液",relation:"运行濡养",to:"全身各部"},{from:"局部资料",relation:"综合后反映",to:"整体功能状态"}],pitfalls:["把整体观念误解为可以忽略局部定位和具体资料。","把传统功能系统机械等同于同名现代解剖器官。","用“全身都相关”替代主次分明的分析。"],selfChecks:["人体自身统一可从哪三个方面说明？","请解释为什么整体观察必须以准确的局部资料为起点。"]}),T({id:"system-04-nature",title:"人与自然环境的统一",order:4,depth:"understanding",estimatedMinutes:18,overview:"人与自然统一强调生命活动会受到季节、昼夜、地域和气候等条件影响，并通过调节维持适应；“天人相应”是整体观念的自然环境维度，不等于自然变化会机械决定个人疾病。",paragraphs:["自然环境具有节律和差异。四季寒暑、昼夜明暗、地域高下与燥湿变化，会影响人的作息、衣食、活动及某些生理表现；人体也会通过腠理开合、气血活动、睡眠觉醒和行为选择作出调整。中医理论把这类相互联系概括为天人相应，核心不是神秘对应，而是把人放在具体时间与环境中观察。题目若强调同一人在不同季节出现有规律变化，首先应想到环境节律与人体适应；若只列出一个自然现象，却没有人与之发生联系的资料，就不能仅凭名称完成判断。","顺应自然不等于被动服从。人体具有相对稳定和主动调节能力，环境影响还会受到体质、生活方式、暴露程度和既有状态调节。同样的气候条件对不同人影响可能不同，同一个人在不同阶段反应也可能改变。因此“天人相应”说明的是开放系统中的影响与适应，而不是气温下降就必然发生某病。做题要区分背景因素、诱发条件和直接证据：季节可以改变某类问题出现的概率或表现，但完整判断仍需结合当时资料。","在学习应用上，可把自然因素按“时间—空间—强度—适应”四格整理。时间包括季节与昼夜，空间包括地域与居住环境，强度指变化是否异常或超过适应范围，适应则看个体调节是否协调。养生原则中的因时、因地安排来自这种思路，但课程知识不能被简化为面向个人的诊断或处方。对现代健康问题还需结合天气预警、公共卫生建议和医学证据。考试中的最佳表达是：自然环境影响人体，人体能够适应并反作用于生活环境，二者处于持续联系而非单向决定。"],examples:[{title:"季节线索怎样使用",explanation:"“冬季”只能作为环境背景；当题干同时写出随寒冷变化的生理调整，才更直接体现人与自然相应，不能由季节单独推出个人证候。"}],relationships:[{from:"季节昼夜地域",relation:"影响",to:"生命活动节律"},{from:"人体调节",relation:"形成",to:"对环境的适应"},{from:"体质与生活方式",relation:"调节",to:"环境影响程度"}],pitfalls:["把天人相应说成自然因素单向决定疾病。","只见季节词就跳过其他资料作证候判断。","把一般顺应原则直接变成个人治疗建议。"],selfChecks:["天人相应为什么既包含环境影响，也包含人体适应？","请说明季节线索在辨题中为什么通常只是一个条件而非完整结论。"]}),T({id:"system-05-society",title:"人与社会环境的联系",order:5,depth:"understanding",estimatedMinutes:18,overview:"整体观念还把人置于家庭、学习、劳动、经济与文化环境中。社会关系可通过情志、行为、饮食作息和医疗可及性影响健康，但社会因素与具体病机之间不能用简单的一步因果替代。",paragraphs:["人的生命活动并不发生在真空中。家庭支持、学习和工作节奏、人际关系、饮食资源、居住条件以及社会角色，会改变情绪体验、睡眠、活动和就医行为。中医理论传统上重视情志、劳逸与生活环境，把它们纳入发病和调护的观察范围。理解这一层，可以避免把健康问题只归结为体内一个孤立部位，也提醒学习者在资料收集中注意时间线：社会事件何时出现，行为和情志如何变化，身体表现是否随后改变。只有建立时间和内容联系，社会背景才可能成为有意义的解释线索。","社会环境联系不等于把一切问题心理化，也不等于认为情绪可以随意控制。情志是正常生命活动的一部分，只有过强、过久、突然或个体调节失常时，才可能成为内伤因素；身体疾病也可以反过来影响情绪和社会功能。分析时应避免责备个体，更不能把结构性困难说成“想开一点”即可解决。课程中的整体观要求同时承认生物、心理与社会层面的相互影响，并保持各自证据边界。涉及持续痛苦、安全风险或明显功能受损时，现实处理应寻求专业支持，而非只靠理论自我判断。","答题时可按“环境事件—情志与行为中介—功能影响—个体差异”组织。比如高强度学习本身是背景，它可能通过睡眠减少、饮食紊乱、久坐和持续紧张影响状态；体质、支持系统和恢复条件又决定影响程度。这样的链条比“压力导致所有症状”更严谨。人与社会统一是整体观念不可缺少的一面，也说明同一自然或病理因素在不同生活条件下可能呈现不同结果。它与因人制宜有联系，却不能代替具体辨证和现代医学评估。"],examples:[{title:"社会资料的链式分析",explanation:"看到“考试周”不要直接下结论，可继续找睡眠、饮食、情志、活动和症状时间线，写出中间环节后再判断其关联。"}],relationships:[{from:"社会环境",relation:"通过情志与行为影响",to:"生命活动"},{from:"身体状态",relation:"反过来影响",to:"社会功能"},{from:"支持与资源",relation:"缓冲或放大",to:"环境影响"}],pitfalls:["把所有身体问题都简单归因于情绪或压力。","忽略身体状态也会反向影响情志和社会活动。","用整体观念责备个体没有主动调整。"],selfChecks:["社会环境影响健康通常经过哪些中间环节？","为什么重视社会情志因素不等于把疾病心理化？"]}),T({id:"system-06-dynamic",title:"恒动观与动态认识",order:6,depth:"understanding",estimatedMinutes:19,overview:"恒动观强调生命、疾病和环境始终处于运动变化之中。动态认识要比较时间点、识别趋势与转折，并在变化中寻找相对稳定的结构，而不是给某个表现贴上永久标签。",paragraphs:["生命活动以升降出入、生长衰老、昼夜节律、生成输布和代谢排泄等多种变化表现出来。所谓“恒动”，不是说一切变化毫无规律，而是说稳定本身依靠持续调节来维持。与阴阳动态平衡相似，某些指标或表现可在一定范围内波动，只要总体协调和调节能力仍在，就不能把变化本身都视为失常。学习时要同时掌握状态和过程：状态回答当前怎样，过程回答从何而来、正在往哪里去、哪些条件可能改变方向。","疾病过程也具有阶段性。同一病名在早期、中期、恢复期可有不同主要矛盾；同一个症状在不同组合和时间线上意义也不同。辨证关注当前阶段的病因、病位、病性和病势，因此需要重复收集资料并比较前后。恒动观是同病异治和异病同治的认识基础之一：同一疾病因阶段或个体变化可出现不同证，不同疾病在某阶段也可能形成相同证。若把第一次判断当作永久结论，就会违背动态认识；若每次见到小变化便完全推翻原有结构，也同样缺少对相对稳定性的把握。","动态题可使用“基线—变化—趋势—条件”四步。先确认原有状态，再标出哪些资料新增、减轻或加重，接着判断是暂时波动、持续趋势还是性质转折，最后找促成变化的条件。病势是动态信息，不等同于病性；时间变化也不能独立证明某一病机。正确做法是把时间线与症状群、体质和环境资料合并。恒动观最终训练的是可修正的判断：结论有证据、有时点、有范围，遇到新资料能够更新，而不是依赖静态标签。"],examples:[{title:"同一资料为什么要复查",explanation:"初次观察只提供一个截面；再次比较可看出加重、减轻、转移或性质改变。动态认识依据趋势修正判断，而不是机械重复原结论。"}],relationships:[{from:"持续运动变化",relation:"形成",to:"生命过程"},{from:"阶段与条件改变",relation:"可能改变",to:"当前证候"},{from:"前后资料比较",relation:"支持",to:"病势与趋势判断"}],pitfalls:["把一次观察结果当成永久不变的标签。","把恒动误解为没有规律、无法形成判断。","只看时间先后，不结合症状组合和变化条件。"],selfChecks:["恒动观为什么不否认相对稳定性？","请用“基线—变化—趋势—条件”分析一个普通学习状态变化的例子。"]}),T({id:"system-07-pattern-treatment",title:"辨证论治及同病异治、异病同治",order:7,depth:"exam",estimatedMinutes:24,overview:"辨证论治是把四诊资料组织成对当前证候和病机的判断，再据此确立治则治法的过程。核心链条是“四诊资料→病因病位病性病势→证候→治则治法”，课程训练重在理解推理层级，而非进行个人诊断。",paragraphs:["先区分病、证、症。症是患者感受或检查观察到的具体表现，是资料单元；病是具有相对特定病因病机和演变规律的全过程概括；证是疾病某一阶段病因、病位、病性、病势等要素的综合反映。一个症不能自动等于一个证，一个证也不等于病名。辨病帮助把握全过程的基本矛盾和一般规律，辨证则聚焦当前阶段的主要失调。二者可以互相参照：病提供纵向框架，证提供当下横截面，不能用其中一个完全取代另一个。","辨证的一般链条从四诊资料开始。望闻问切取得的表现需要经过真实性、相关性和时间性的整理，再分析可能的病因、病位、病性与病势，形成证候判断；论治则依据证候和病机确立治则，再落实为治法，之后才可能涉及方药、针灸等具体方案。理、法、方、药是层层相承的表达：理说明为什么，法说明向什么方向处理，方与药是具体实施载体。学生做基础题时要看清题目问的是哪一层，问治则时不能用药名代替，问证候时也不能只复述一个症状。","同病异治指相同疾病因阶段、体质或证候不同而采用不同治法；异病同治指不同疾病在某阶段出现相同或相近证候、核心病机时采用相同或相近治法。两者表面方向相反，依据却相同，都是“证同治亦同，证异治亦异”。这里的“同治”是原则和治法方向相近，不保证具体处方完全相同；“异治”也不是为了求不同而不同。案例题先标出病名是否相同，再比较证候与病机，最后判断治法方向。真实健康问题必须由合格专业人员完整评估，本章示例只用于理解课程概念。"],examples:[{title:"四步链条练习",explanation:"先把题干原话列为资料，再归纳寒热虚实、部位和趋势，形成证候，最后回答治则治法层级。不要从单一症状直接跳到方药。"}],relationships:[{from:"四诊资料",relation:"分析为",to:"病因病位病性病势"},{from:"综合病机要素",relation:"概括为",to:"证候"},{from:"证候与病机",relation:"指导",to:"治则治法"}],pitfalls:["把一个症状直接当成一个证候。","把辨病与辨证理解为只能二选一。","把同病异治理解为同一病名必须随意换治法，或把异病同治理解为处方完全相同。"],selfChecks:["请完整写出从四诊资料到治则治法的推理链。","病、证、症分别观察什么？同病异治与异病同治为何依据相同？"]})],C=e=>({...e,unitId:f,sourceIds:B,verifiedAt:u}),ae=[C({id:"system-c01-holism-nature",title:"整体观念与天人相应",items:["整体观念","天人相应"],dimensions:[{label:"定义范围",values:{整体观念:"人体内部及人与自然、社会均相互联系",天人相应:"人与自然环境相互影响并保持适应"}},{label:"观察对象",values:{整体观念:"内部整体加外部环境",天人相应:"重点观察自然环境维度"}},{label:"作用",values:{整体观念:"提供总的联系框架",天人相应:"说明季节地域等与人体的联系"}},{label:"时间尺度",values:{整体观念:"可观察当前结构与长期联系",天人相应:"常突出节律和环境变化"}},{label:"考试陷阱",values:{整体观念:"误说只指人体内部",天人相应:"误说自然单向决定疾病"}}],decisionRule:"题干总论人体内外联系选整体观念，特指季节、昼夜、地域与适应选天人相应。",commonTrap:"把天人相应当成与整体观念并列且毫无包含关系的另一套理论。",example:"“脏腑相互影响”体现人体整体；“生理节律随昼夜调整”更直接体现天人相应。"}),C({id:"system-c02-whole-local",title:"整体认识与忽视局部",items:["整体认识","忽视局部"],dimensions:[{label:"定义",values:{整体认识:"以准确局部资料为起点分析联系",忽视局部:"跳过部位与具体表现只谈全身"}},{label:"观察对象",values:{整体认识:"局部事实及其网络位置",忽视局部:"模糊的整体标签"}},{label:"时间尺度",values:{整体认识:"结合当前和前后变化",忽视局部:"常缺少时间线"}},{label:"作用",values:{整体认识:"确定主次联系",忽视局部:"造成无限联想"}},{label:"考试陷阱",values:{整体认识:"误以为越多联系越好",忽视局部:"用“一切相关”替代证据"}}],decisionRule:"能否先说清局部事实，再说明有证据的联系，是区分二者的关键。",commonTrap:"认为重视整体就不必精确描述局部。",example:"先描述目部表现，再结合其他资料分析相关功能系统，才是整体认识。"}),C({id:"system-c03-dynamic-static",title:"恒动观与静态标签",items:["恒动观","静态标签"],dimensions:[{label:"定义",values:{恒动观:"在变化中观察状态、趋势和条件",静态标签:"把一次判断永久固定"}},{label:"观察对象",values:{恒动观:"前后资料和病势",静态标签:"单一时点"}},{label:"时间尺度",values:{恒动观:"强调阶段与过程",静态标签:"忽略时间变化"}},{label:"作用",values:{恒动观:"允许依据新资料修正",静态标签:"阻碍更新判断"}},{label:"考试陷阱",values:{恒动观:"误说变化等于无规律",静态标签:"把初次证候当终身属性"}}],decisionRule:"题干出现阶段、加减、转折和复查时，优先从恒动观分析。",commonTrap:"把动态认识误解为每次小波动都要完全推翻原判断。",example:"同一病名前后主要表现不同，需要根据当前资料重新辨证。"}),C({id:"system-c04-disease-pattern-symptom",title:"病、证、症",items:["病","证","症"],dimensions:[{label:"定义",values:{病:"对相对完整疾病过程的概括",证:"当前阶段病机要素的综合反映",症:"主观感受或客观表现"}},{label:"观察对象",values:{病:"全过程基本矛盾",证:"阶段性病因病位病性病势",症:"单项资料"}},{label:"时间尺度",values:{病:"纵向过程",证:"当前阶段",症:"具体时点也可连续观察"}},{label:"作用",values:{病:"提供疾病框架",证:"直接指导辨证论治",症:"构成判断原始资料"}},{label:"考试陷阱",values:{病:"把病名当证名",证:"把证当单一症状",症:"见一个症就直接定证"}}],decisionRule:"问全过程选病，问当前综合病机选证，问具体表现选症。",commonTrap:"把“症状相同”直接等同于“证候相同”。",example:"头痛是症；某一阶段的风寒证是证；疾病的完整诊断名称属于病的层次。"}),C({id:"system-c05-disease-pattern-identification",title:"辨病与辨证",items:["辨病","辨证"],dimensions:[{label:"定义",values:{辨病:"识别疾病类别和全过程规律",辨证:"概括当前阶段的证候与病机"}},{label:"观察对象",values:{辨病:"基本矛盾和演变框架",辨证:"病因病位病性病势"}},{label:"时间尺度",values:{辨病:"偏纵向",辨证:"偏阶段横截面并随时更新"}},{label:"作用",values:{辨病:"限定总体认识范围",辨证:"确定当前治法方向"}},{label:"考试陷阱",values:{辨病:"只按病名套治法",辨证:"完全忽略疾病规律"}}],decisionRule:"辨病抓“什么病及其全过程”，辨证抓“现在是什么证及其病机”。",commonTrap:"把二者设成互相排斥，只允许保留一个。",example:"先识别同一疾病，再根据不同阶段证候采用不同治法，体现辨病与辨证结合。"}),C({id:"system-c06-pattern-treatment",title:"辨证与论治",items:["辨证","论治"],dimensions:[{label:"定义",values:{辨证:"从资料形成证候与病机判断",论治:"依据证候病机确立治则治法"}},{label:"观察对象",values:{辨证:"四诊资料及病机要素",论治:"治疗方向和方法层次"}},{label:"时间尺度",values:{辨证:"对应当前阶段",论治:"随当前证候调整"}},{label:"作用",values:{辨证:"提供依据",论治:"形成行动方向"}},{label:"考试陷阱",values:{辨证:"直接写药物",论治:"没有证候依据只背治法"}}],decisionRule:"“判断是什么证”属于辨证，“根据该证怎么办”属于论治。",commonTrap:"把辨证论治压缩成看症状选药。",example:"先由四诊资料判断当前证候，再据证确立治法，前后分别是辨证与论治。"}),C({id:"system-c07-same-different",title:"同病异治与异病同治",items:["同病异治","异病同治"],dimensions:[{label:"定义",values:{同病异治:"同一疾病因证不同而治法不同",异病同治:"不同疾病因证同而治法相近"}},{label:"观察对象",values:{同病异治:"病同、证异",异病同治:"病异、证同"}},{label:"时间尺度",values:{同病异治:"常见不同阶段或个体",异病同治:"比较不同疾病的当前阶段"}},{label:"作用",values:{同病异治:"防止按病名一法到底",异病同治:"抓共同核心病机"}},{label:"考试陷阱",values:{同病异治:"以为刻意求异",异病同治:"以为处方细节完全一致"}}],decisionRule:"先比病名是否相同，再比证候是否相同：病同证异选前者，病异证同选后者。",commonTrap:"只看治法相同或不同，不先核对病与证两个层次。",example:"两种疾病当前都属同一证而采用相近治法，属于异病同治。"}),C({id:"system-c08-reason-method-formula",title:"理法方药与辨证论治",items:["辨证论治","理法方药"],dimensions:[{label:"定义",values:{辨证论治:"从资料到证候再到治疗方向的完整过程",理法方药:"理论、治法、方剂、药物的层层落实"}},{label:"观察对象",values:{辨证论治:"证据与病机推理",理法方药:"治疗表达层次"}},{label:"时间尺度",values:{辨证论治:"随证候阶段更新",理法方药:"随辨证结果调整"}},{label:"作用",values:{辨证论治:"决定为何与向何处处理",理法方药:"把方向落实为具体方案"}},{label:"考试陷阱",values:{辨证论治:"跳过分析直接给方",理法方药:"把药名当治则"}}],decisionRule:"题目问推理全过程答辨证论治；问理论如何逐级落实到具体用药答理法方药。",commonTrap:"把二者当成完全同义，或从症直接跳到方药。",example:"“根据病机确立治法，再依法组方遣药”突出理法方药层次。"})],se=[{id:"system-m01-holism",unitId:f,priority:"must-recite",prompt:"整体观念包含哪三个范围？",answer:"人体自身是统一整体，人与自然环境相统一，人与社会环境相联系。",mnemonic:"人内—自然—社会",relatedSectionId:"system-03-body-holism"},{id:"system-m02-pattern",unitId:f,priority:"must-recite",prompt:"证的定义要点是什么？",answer:"证是疾病某一阶段病因、病位、病性、病势等病机要素的综合反映。",mnemonic:"阶段＋四要素",relatedSectionId:"system-07-pattern-treatment"},{id:"system-m03-chain",unitId:f,priority:"must-recite",prompt:"辨证论治的核心链条是什么？",answer:"四诊资料→分析病因、病位、病性、病势→形成证候→确立治则治法。",relatedSectionId:"system-07-pattern-treatment"},{id:"system-m04-same-different",unitId:f,priority:"must-recite",prompt:"同病异治与异病同治分别指什么？",answer:"同病异治是病同而证异、治法不同；异病同治是病异而证同、治法相近。",mnemonic:"先看病，再看证",relatedSectionId:"system-07-pattern-treatment"},{id:"system-m05-formation",unitId:f,priority:"must-recite",prompt:"理论体系形成与发展的四个关键词是什么？",answer:"长期医疗实践、思想与自然知识背景、经典体系化、历代学术与临床发展。",relatedSectionId:"system-01-formation"},{id:"system-m06-levels",unitId:f,priority:"must-understand",prompt:"中医基础理论可怎样分成四层？",answer:"一般认识方法；生命结构功能；病因发病病机；诊察辨证与防治原则。",relatedSectionId:"system-02-structure"},{id:"system-m07-local-whole",unitId:f,priority:"must-understand",prompt:"整体认识为什么不能忽视局部？",answer:"整体判断以具体局部资料为证据入口，再分析局部在功能网络中的联系与主次。",relatedSectionId:"system-03-body-holism"},{id:"system-m08-nature",unitId:f,priority:"must-understand",prompt:"天人相应怎样避免机械决定论？",answer:"自然环境影响人体，人体具有适应调节；影响还受体质、生活方式、强度和时间调节。",relatedSectionId:"system-04-nature"},{id:"system-m09-dynamic",unitId:f,priority:"must-understand",prompt:"动态分析的四步是什么？",answer:"确认基线，标出变化，判断趋势或转折，寻找促成变化的条件。",mnemonic:"基—变—势—因",relatedSectionId:"system-06-dynamic"},{id:"system-m10-disease-pattern-symptom",unitId:f,priority:"must-understand",prompt:"病、证、症怎样快速区分？",answer:"病看全过程，证看当前阶段综合病机，症看具体主观或客观表现。",relatedSectionId:"system-07-pattern-treatment"},{id:"system-m11-society",unitId:f,priority:"recognize",prompt:"社会环境影响健康的常见中间环节有哪些？",answer:"可通过情志、睡眠、饮食、活动、劳逸、支持资源和就医行为等环节发生影响。",relatedSectionId:"system-05-society"},{id:"system-m12-boundary",unitId:f,priority:"recognize",prompt:"本章理论的应用边界是什么？",answer:"用于组织课程中的联系与推理，不能替代完整专业评估，也不能从单一线索形成个人诊疗方案。",relatedSectionId:"system-07-pattern-treatment"}],O=e=>({...e,unitId:f,sourceIds:B,verifiedAt:u}),re=[O({id:"system-w01",type:"term-definition",prompt:"名词解释：整体观念",answerOutline:["指出事物和人体是相互联系的整体","写人体自身统一","写人与自然、社会环境的联系"],scoringPoints:["内部整体","自然环境","社会环境","不是忽视局部"]}),O({id:"system-w02",type:"term-definition",prompt:"名词解释：辨证论治",answerOutline:["由四诊取得资料","分析病机要素并形成证候","依据证候确立治则治法"],scoringPoints:["资料","病因病位病性病势","证候","论治"]}),O({id:"system-w03",type:"short-answer",prompt:"简述中医学理论体系形成与发展的主要条件。",answerOutline:["长期医疗实践是基础","古代哲学与自然知识提供认识工具","经典整理促进体系化","历代学术和临床实践不断丰富"],scoringPoints:["多因素","长期性","体系化","发展性"]}),O({id:"system-w04",type:"short-answer",prompt:"简述整体观念的主要内容及学习意义。",answerOutline:["人体自身统一","人与自然统一","人与社会联系","局部资料要放入整体网络理解"],scoringPoints:["三个范围","局部与整体结合","不作机械决定"]}),O({id:"system-w05",type:"comparison",prompt:"比较病、证、症，并说明三者联系。",answerOutline:["病是全过程概括","证是当前阶段综合病机","症是具体表现","症为辨病辨证提供资料，病证共同组织症"],scoringPoints:["观察对象","时间尺度","作用层级","不能相互替代"]}),O({id:"system-w06",type:"analysis",prompt:"分析同病异治与异病同治为何都体现辨证论治。",answerOutline:["先比较病名是否相同","再比较当前证候与病机","证异则治异、证同则治同","说明判断随阶段和个体资料变化"],scoringPoints:["病证两层","共同依据是证候病机","治法方向而非机械同方","体现动态与个体差异"]})],le=[r({id:"q-tcm-system-13",unitId:f,conceptId:"tcm-system-theory-formation",type:"single-choice",prompt:"对中医学理论体系形成过程的概括，哪一项最完整？",options:["由某位医家依据哲学一次推演完成","长期实践提供材料，思想工具与经典整理促进体系化，历代持续发展","只是把零散药物经验汇集在一起","完全由现代实验结果建立"],answer:1,explanation:"中医学理论体系形成具有多因素、长期性、体系化和持续发展的特点，实践、认识工具、典籍整理与历代学术共同参与。",misconceptionFeedback:{0:"单一人物和单一哲学来源都无法解释体系的长期形成。",2:"经验是基础，但理论体系还包含概念结构与推理规则。",3:"其历史形成早于现代实验医学，现代研究也不能替代历史形成过程。"}}),r({id:"q-tcm-system-14",unitId:f,conceptId:"tcm-pattern-treatment",type:"matching",prompt:"将病、证、症与最直接的观察层次配对。",pairs:[{left:"病",right:"相对完整的疾病过程"},{left:"证",right:"当前阶段的综合病机"},{left:"症",right:"具体主观或客观表现"}],answer:["病=>相对完整的疾病过程","证=>当前阶段的综合病机","症=>具体主观或客观表现"],explanation:"病偏纵向全过程，证聚焦当前阶段病机，症是构成判断的具体资料。",misconceptionFeedback:{"":"先按“全过程—阶段综合—单项资料”三个时间与层级定位，再完成配对。"}}),r({id:"q-tcm-system-15",unitId:f,conceptId:"tcm-system-thinking-methods",type:"scenario",prompt:"同一课程案例在一周后出现新的主要表现。学习者保留原病名框架，但重新整理四诊资料并修正证候判断。这最能体现什么？",options:["恒动观下的辨病与辨证结合","只按病名固定治法","忽视局部的整体观","五行归类的表面类比"],answer:0,explanation:"保留疾病纵向框架体现辨病，依据新资料修正阶段判断体现辨证和恒动观。",misconceptionFeedback:{1:"题干明确根据新资料修正判断，并非固定不变。",2:"重新整理具体资料恰恰没有忽视局部。",3:"题干讨论病程与证候更新，不涉及五行归类。"}})],pe={chapter:{unitId:f,title:"理论体系与整体观念",introduction:"本章先建立中医理论的结构地图，再从人体内部、自然环境和社会环境理解整体观念，以恒动观贯穿病程变化，最后把病、证、症和辨证论治组织成可反复使用的推理链。",sections:oe,confusions:ae,memoryItems:se,writtenPrompts:re,summary:["理论体系由长期实践、认识工具、经典整理和历代发展共同形成。","整体观念包括人体自身统一、人与自然统一、人与社会联系。","整体观察以准确局部资料为入口，不等于忽视局部或无限联想。","恒动观在相对稳定中观察阶段、趋势、转折与条件。","病看全过程，证看当前阶段综合病机，症看具体表现。","辨证论治遵循“四诊资料—病机要素—证候—治则治法”链条。","同病异治与异病同治的共同依据都是当前证候和核心病机。"]},questions:le},m="tcmf-yinyang",j=[...P],S=e=>({...e,unitId:m,sourceIds:j,verifiedAt:u}),me=[S({id:"yy-01-frame",title:"阴阳是什么：先找比较对象与前提",order:1,depth:"foundation",estimatedMinutes:18,overview:"阴阳不是两种固定物质，也不是见到热就永远属阳、见到冷就永远属阴。它是一种关系范畴，用来概括相关事物或同一事物内部相反而又相互联系的两个方面。",paragraphs:["学习阴阳的第一步，不是急着背属性表，而是确定正在比较什么。只有彼此相关、处在同一讨论层级、具有相反倾向的两个方面，才适合用阴阳加以概括。例如昼与夜属于同一日周期，动与静属于同一活动状态，外与内属于同一空间关系。若把“白天”和“肝脏”直接放在一起判断阴阳，两者没有共同的比较前提，问题本身就不成立。阴阳判断因此始终包含一个隐含句式：相对于什么而言，谁更趋向于哪一类属性。","第二步是明确比较依据。一般而言，向上、向外、运动、温热、明亮、兴奋、功能等倾向常归于阳；向下、向内、静止、寒凉、晦暗、抑制、物质等倾向常归于阴。这些词不是互不相干的死表，而是帮助我们识别方向和功能倾向的线索。同一个对象可因比较依据不同而呈现不同属性：胸相对于腹位置较上，可属阳；但胸腹作为躯干，相对于背部又可属阴。属性变化来自比较关系改变，而不是对象突然变成另一种实体。","做题可固定使用四步法：确定对象，确定比较前提，判断相反属性，最后检查相对性。先把题干中的两个对象圈出，再问它们是否属于同一关系；随后找出题干强调的是方位、温度、运动、功能还是形质；最后检查换一个层级后结论是否可能改变。这个顺序能避免只凭单个关键词作答。阴阳学说在中医基础理论中承担的是组织关系与变化规律的工具角色，不能把它机械等同于现代物理量、解剖结构或某一项实验指标。"],examples:[{title:"方位判断示例",explanation:"上与下相比，上属阳、下属阴；但头部内部再分表里时，外表可属阳、内部可属阴。先写明“相对于谁”，结论才完整。"}],relationships:[{from:"确定比较对象",relation:"再确定",to:"共同前提"},{from:"共同前提",relation:"据此判断",to:"阴阳属性"},{from:"比较层级改变",relation:"可能改变",to:"属性结论"}],pitfalls:["把阴阳当成两个可独立存在的物质。","只背“热属阳、寒属阴”，却不写比较前提。","把没有关联、层级不同的两个对象强行配成阴阳。"],selfChecks:["为什么阴阳判断必须先确定比较对象和共同前提？","请用胸、腹、背三个方位说明阴阳属性的相对性。"]}),S({id:"yy-02-attributes",title:"阴阳属性的相关性、普遍性与相对性",order:2,depth:"foundation",estimatedMinutes:18,overview:"阴阳属性可以广泛用于概括相反相成的关系，但这种广泛性受到“必须相关”的限制，并且会随时间、层级、条件和比较对象变化。",paragraphs:["所谓相关性，是指被划分为阴阳的两个方面必须属于同一事物、同一过程或同一关系系统。它们不是随机拼接，而是围绕同一个问题相互对待。例如机体的形与神、气与血、脏与腑都可在特定层面形成阴阳关系，因为双方参与同一生命活动；一个季节与一个穴位却不能仅因都能找到寒热词语就直接构成阴阳。相关性是阴阳分类的入口条件，缺少这一条件，后面的属性判断再熟练也没有意义。","所谓普遍性，是指自然、人体和疾病变化中大量关系都可从阴阳角度加以整理。普遍并不等于万能，更不等于所有差异都只能分成两类。阴阳擅长揭示相反方向、相互依存和动态变化，具体知识仍需藏象、气血、经络、病因病机等理论进一步说明。考试中若题干问“阴阳可概括一切相关事物的相反属性”，重点在其广泛适用；若说“任何两个事物都能任意分阴阳”，则忽略了相关性和比较前提。","所谓相对性至少包含三层。第一，阴阳属性在一定条件下可相互转化；第二，同一事物可继续无限分阴分阳，如昼为阳，昼中上午与下午又可再分；第三，改变比较对象或层级时，属性结论可能不同。相对性不取消相对稳定性：在题目已经给定比较前提时，不能为了强调相对而随意翻转答案。最稳妥的表达是“阴阳属性在特定关系中有相对确定性，在条件和层级改变时又具有相对性”。"],examples:[{title:"昼夜再分示例",explanation:"昼相对于夜属阳；昼之上午阳气渐长，可称阳中之阳，下午阳气渐衰，可称阳中之阴。再分不是推翻原结论，而是在更细层级继续比较。"}],relationships:[{from:"相关性",relation:"限制",to:"可比较范围"},{from:"普遍性",relation:"说明",to:"广泛适用"},{from:"相对性",relation:"允许",to:"分层与条件变化"}],pitfalls:["把“普遍性”误解为任何两个对象都能比较。","把“相对性”误解为答案可以随意改变。","用阴阳二分替代全部具体学科知识。"],selfChecks:["阴阳属性相对性包含哪三层意思？","为什么“属性相对”不等于“没有确定答案”？"]}),S({id:"yy-03-opposition",title:"对立制约：相反而相互约束",order:3,depth:"understanding",estimatedMinutes:20,overview:"阴阳双方属性相反，并在同一系统中相互抑制、相互约束。制约适度有助于维持协调，任何一方过强或过弱都可能使这种约束失衡。",paragraphs:["对立说明阴阳双方具有相反倾向，如寒与热、动与静、升与降、兴奋与抑制。只有“相反”还不够，对立制约还强调双方处在同一过程中并能彼此限制。白昼的温暖与夜间的寒凉、机体活动与休息，都在一定节律中相互替换和约束，使总体状态不致无限偏向一端。理解时应把“对立”看作属性方向，把“制约”看作双方发生作用后的结果。","制约不是一方消灭另一方，而是在一定范围内限制过度。健康状态下，温热活动不会无限增强，寒凉静息也不会永久占据优势；双方力量的相互牵制使变化保持在可调节范围。病理分析中可用“制约不足”或“一方偏盛”理解失衡，但要分清原因：阳偏盛可以过度制约阴而出现实热倾向，阴偏衰则因阴不足、不能制约阳而出现虚热倾向。两者都可见热象，形成机制和虚实属性却不同。","判断题干是否考对立制约，可寻找“相反、制约、抑制、斗争、避免过度”等线索。若题干强调双方互为存在条件，则更接近互根互用；若强调数量此增彼减，则进入消长；若强调在条件下性质改变，则是转化。同一道题可能同时涉及多个关系，答题时应根据设问选最直接的一层。例如“寒可制热”直接说明对立制约；若继续描述寒热力量比例随时间改变，才进一步涉及消长。"],examples:[{title:"寒热制约示例",explanation:"题干说“以寒制热，使偏盛之热恢复协调”，首先考查相反属性之间的制约；不能仅因结果发生变化就选“相互转化”。"}],relationships:[{from:"属性相反",relation:"形成",to:"对立"},{from:"双方相互限制",relation:"表现为",to:"制约"},{from:"制约适度",relation:"有助于",to:"动态协调"}],pitfalls:["把制约理解为彻底消灭对方。","看到寒热就忽略虚实和形成机制。","把所有相反关系都直接判成相互转化。"],selfChecks:["对立与制约分别强调什么？","阳偏盛之热和阴偏衰之热在制约关系上有何不同？"]}),S({id:"yy-04-interdependence",title:"互根互用：相互依存与资生",order:4,depth:"understanding",estimatedMinutes:20,overview:"互根说明阴阳双方互为存在前提，互用说明双方能够相互资生、相互支持功能。它回答的不是“谁压制谁”，而是“为什么任何一方都不能脱离另一方独立存在”。",paragraphs:["互根强调存在关系。阴以阳为存在条件，阳也以阴为存在条件；没有与之相对的一方，另一方也失去被规定的意义。例如没有静就无法界定动，没有内就无法界定外。放到人体理论中，功能活动需要一定物质基础，物质的生成和更新又依赖功能活动推动。这里的“物质—功能”是中医理论中常用的相对概括，不能简单等同于某一个现代解剖结构和某一项生化反应。","互用强调资生和促进。阴精可以作为阳气活动的物质基础，阳气活动又能推动阴精的化生与布散。双方不仅在逻辑上相互定义，也在生命活动中相互为用。因此，一方长期严重受损，可能累及另一方，形成阴阳互损。互损属于病理演变，互根互用则是说明这种演变为何可能发生的基础关系。答题时若题干出现“依存、根本、物质基础、功能动力、资生促进”，通常优先考虑互根互用。","互根互用与对立制约并不矛盾。阴阳双方既相反又相成：相反使它们能够相互限制，相成使它们共同完成同一过程。只讲对立会把阴阳理解成永远冲突的两端，只讲互根又会忽略方向差异。完整表达常写为“阴阳双方对立而又统一，在相互制约中保持协调，在相互依存和相互为用中维持生命活动”。考试比较题应把判断关键词、作用方式和典型结果分点写出。"],examples:[{title:"物质与功能示例",explanation:"题干说“功能活动以物质为基础，物质代谢又依赖功能推动”，直接指向互根互用；若说一方限制另一方过度，则转为对立制约。"}],relationships:[{from:"互根",relation:"强调",to:"相互依存"},{from:"互用",relation:"强调",to:"相互资生"},{from:"一方严重受损",relation:"可能导致",to:"阴阳互损"}],pitfalls:["把互根互用写成双方性质完全相同。","用“互相影响”代替依存与资生的具体含义。","把生理互用与病理互损混成同一个概念。"],selfChecks:["互根与互用分别回答什么问题？","为什么对立制约和互根互用可以同时存在？"]}),S({id:"yy-05-interaction",title:"交感互藏：发生联系与内含对方",order:5,depth:"understanding",estimatedMinutes:18,overview:"交感说明阴阳双方在运动中相互感应、相互作用，是变化发生的重要条件；互藏说明阴中有阳、阳中有阴，每一方内部都包含对方的因素。",paragraphs:["阴阳交感强调双方不是彼此封闭，而能在运动中接触、感应并发生作用。若只有抽象的两个标签，却没有任何相互作用，就难以说明新变化怎样产生。交感使相反双方建立联系，进而出现消长、转化和新的协调状态。理解时可抓住“相互感应、相互作用、变化发生”三个环节。交感不是特指情绪或感觉，也不是只要两者并列就已经发生；题干必须体现双方在同一过程中发生联系。","阴阳互藏强调每一方内部包含对方成分，体现事物结构并非纯粹单一。例如阳中可以再分阴阳，阴中也可再分阴阳；功能活动中含有物质消耗与积累，静息过程中也存在维持生命的活动。互藏为双方相互依存和相互转化提供内在条件：因为一方内部并非绝对排斥对方，变化才有可以展开的基础。互藏不能被理解为阴阳没有区别，恰恰是在保持总体属性的同时承认内部层次。","交感、互藏、互根三者容易被一句“相互联系”混掉。交感重在双方发生作用的动态过程，互藏重在一方内部含有对方因素，互根重在双方互为存在条件。题目若问“阴中有阳、阳中有阴”，选互藏；若问“二气相感而产生变化”，选交感；若问“孤阴不生、独阳不长”所体现的依存关系，选互根互用。把关键词放回定义后再判断，比只背经典短句更可靠。"],examples:[{title:"分层判断示例",explanation:"“昼为阳而午后属阳中之阴”体现互藏与再分；“阴阳相感而发生新的变化”强调交感。两句都谈联系，但问题焦点不同。"}],relationships:[{from:"阴阳交感",relation:"使双方",to:"发生作用"},{from:"阴阳互藏",relation:"说明一方内部",to:"含有对方因素"},{from:"交感与互藏",relation:"共同支持",to:"变化发生"}],pitfalls:["把交感理解成一般的主观感受。","把互藏理解成阴阳之间没有差别。","用“相互联系”四字代替三个概念的判断依据。"],selfChecks:["交感、互藏、互根的判断焦点各是什么？","为什么互藏不等于取消阴阳差异？"]}),S({id:"yy-06-waxing",title:"消长与平衡：量变中的动态协调",order:6,depth:"understanding",estimatedMinutes:22,overview:"阴阳消长描述双方数量或力量比例的增减变化。平衡不是双方永远各占一半，而是消长在一定范围内保持总体协调。",paragraphs:["消长中的“消”是减少、衰减，“长”是增加、增长。阴阳双方处在不断运动中，因此比例会随时间和条件变化。判断消长时，题干重点仍是量的增减，事物的基本属性尚未改变。昼夜长短随季节改变、活动与休息按节律交替，都可帮助理解这种动态。消长不必然是疾病，生理状态同样存在有规律的消长；只有变化超过协调范围、形成持续偏胜偏衰时，才进入失调分析。","常见教材框架将消长概括为四种形式。对立制约较突出时，可见此长彼消和此消彼长，一方增加伴另一方减少；互根互用较突出时，可见此长彼长和此消彼消，一方增长带动另一方增长，或一方衰减累及另一方衰减。四种形式不是四个互相排斥的世界，而是帮助识别题干中双方变化方向。做排序或配对题时，先分别标注阴与阳是上升还是下降，再根据箭头组合命名。","阴阳平衡是动态平衡。它允许短时波动和节律变化，关键是双方能通过制约、互用和自我调节回到相对协调。平衡也不等于数值相等：不同生命阶段、季节和活动状态可以有不同的适宜比例。若把平衡理解为固定不动，就无法解释正常节律；若把一切变化都视为失衡，又会混淆生理消长与病理偏盛偏衰。答题宜写“消长有度、总体协调、动态维持”三个层次。"],examples:[{title:"箭头法判断",explanation:"阳增加、阴减少记作“阳↑阴↓”，属于此长彼消；阳减少并使阴也减少记作“阳↓阴↓”，属于此消彼消。先画箭头再命名，能减少文字干扰。"}],relationships:[{from:"阴阳运动",relation:"表现为",to:"数量消长"},{from:"消长有度",relation:"维持",to:"动态平衡"},{from:"消长超过范围",relation:"可能形成",to:"偏盛偏衰"}],pitfalls:["把消长等同于性质转化。","认为平衡必须双方数量完全相等。","把所有正常节律变化都判为病理失衡。"],selfChecks:["阴阳消长四种基本形式如何用箭头表示？","为什么阴阳平衡是动态的而不是绝对静止？"]}),S({id:"yy-07-transformation",title:"相互转化：条件成熟后的质变",order:7,depth:"understanding",estimatedMinutes:20,overview:"阴阳转化指事物的总体属性在一定条件下向相反方面改变。它强调质变和条件，不能把任何数量波动都称为转化。",paragraphs:["转化与消长的核心区别在变化层级。消长是在原有属性范围内数量比例发生变化，转化则是事物总体性质向对立方面改变。量变可以为质变积累条件，但并非每一次量变都会必然发生转化。因此，看到“由寒转热、由热转寒、由阴转阳、由阳转阴”等表述时，还要确认题干是否真的说明性质改变，而不是只说明寒热程度增减。答题中写出“质变”和“一定条件”通常是转化定义的关键得分点。","转化需要条件。条件可包括变化积累达到一定程度、内外因素共同作用、原有平衡被打破并形成新的主导方面。没有条件的任意翻转不属于阴阳转化。经典表述常用“重阴必阳、重阳必阴”帮助记忆变化达到一定程度后可能向反面转化，但“必”应放在理论语境和条件中理解，不能据此预测每一个现实个案都会按照单一路径变化。基础学习的任务是识别模型中的方向与条件，而不是越过诊察作具体判断。","转化与互根、互藏也有联系。互根说明双方互为存在条件，互藏说明一方内部含有对方因素，这些关系为转化提供结构基础；消长则可构成转化前的数量积累。关系链可以写成“互根互藏提供可能—消长积累形成条件—总体属性发生转化”。这条链不是说四个概念完全相同，而是说明它们从不同层次解释同一个动态过程。比较题应先逐一定义，再写联系，最后写判断标准。"],examples:[{title:"量变与质变示例",explanation:"温度逐步升高但仍处在原有状态，重点是消长；达到条件后物态发生改变，才可借来理解转化。这个类比只说明量变与质变，不把中医阴阳等同于物理物态。"}],relationships:[{from:"阴阳消长",relation:"可能积累",to:"转化条件"},{from:"一定条件成熟",relation:"促成",to:"性质转化"},{from:"互根互藏",relation:"提供",to:"转化可能"}],pitfalls:["只要出现变化就选择转化。","忽略“一定条件”，把转化理解为随意翻转。","用单一阴阳模型预测具体疾病必然结局。"],selfChecks:["消长与转化的根本区别是什么？","如何说明互根、互藏、消长与转化之间的联系？"]}),S({id:"yy-08-harmony",title:"阴阳自和与平衡机制",order:8,depth:"exam",estimatedMinutes:18,overview:"阴阳自和强调系统在一定条件下通过自身相互作用恢复和维持协调。它不是不受外界影响，也不是任何失衡都能自动恢复。",paragraphs:["“自和”可理解为阴阳双方在对立制约、互根互用、消长转化等作用中具有趋向协调的能力。人体生命活动不是被动保持一个固定数值，而是在饮食、活动、休息和环境变化中不断调整。调节有效时，短暂波动可回到相对稳定范围，这体现动态平衡和自我协调。自和因此与前述关系相连：制约防止一方过度，互用维持共同活动，消长完成比例调整。","自和具有条件和限度。邪气强盛、正气不足、持续不良因素或损伤超过调节能力时，系统可能不能自行恢复，需要进一步辨证和处理。基础理论页面只说明这一原则，不据此告诉个人“等待自愈”或替代就医。考试若把“阴阳自和”写成“阴阳永远不会失衡”是错误的；若写成“阴阳双方在一定范围和条件下具有自我调节、趋向协调的能力”，则更准确。","平衡、自和与消长三者可用过程来区分。消长描述双方比例如何变化，自和描述通过相互作用趋向协调的能力，平衡描述某一阶段总体相对协调的状态。三者不是孤立名词：消长可以成为自和的调节方式，自和有助于恢复平衡，平衡中仍持续存在新的消长。作答时依次写“变化方式—调节能力—协调状态”，层次会比只写“保持平衡”完整。"],examples:[{title:"节律调整示例",explanation:"活动后需要休息，休息后精力逐步恢复，可用消长和自和理解总体调节；但这一理论描述不能代替对异常疲劳原因的医学评估。"}],relationships:[{from:"阴阳消长",relation:"可成为",to:"自和方式"},{from:"阴阳自和",relation:"趋向恢复",to:"动态平衡"},{from:"调节能力受损",relation:"可能导致",to:"持续失衡"}],pitfalls:["把自和理解为任何疾病都能自行痊愈。","把动态平衡写成无波动的固定状态。","把过程、能力和状态三个层次混为一谈。"],selfChecks:["消长、自和、平衡分别描述哪个层次？","为什么阴阳自和必须说明条件和限度？"]}),S({id:"yy-09-application",title:"生理、病理、诊断与防治中的应用边界",order:9,depth:"exam",estimatedMinutes:24,overview:"阴阳学说可用于组织人体结构功能、概括生理关系、分析寒热虚实等病机方向，并指导防治原则；应用时必须结合具体课程知识和四诊资料。",paragraphs:["在组织人体知识时，可按部位、功能和形质作相对划分，如上与下、外与内、功能与物质等。划分的目的，是建立相反相成的关系框架，而不是给每个结构贴永久标签。在生理方面，阴精与阳气、物质与功能、活动与休息之间可用制约互用和消长平衡说明协调。答题应明确“从哪个角度归类”，并提醒藏象概念不能与现代解剖器官逐一机械对应。","在病理方面，常见基础框架包括阴阳偏盛、阴阳偏衰、阴阳互损、格拒和亡失。偏盛属于一方有余的实性失衡，偏衰属于一方不足的虚性失衡。阴盛则寒与阳虚则寒都可见寒象，前者重点是一方偏盛的实寒方向，后者重点是阳不足的虚寒方向；阳盛则热与阴虚则热同理。这里只训练概念辨析，现实中的症状不能凭一个寒热词语自行归类，更不能据此自行用药。","在诊断和防治原则中，阴阳可作为总纲帮助归纳表里、寒热、虚实和总体趋势，并提出调整阴阳、损其有余、补其不足等方向。方向性原则仍需在后续中医诊断学、中药学、方剂学和临床课程中结合完整资料展开。基础题的正确路径是“先辨失衡类型—再说明寒热虚实—最后写原则方向”；错误路径是看见一个表现就直接给出具体处方。养生层面强调顺应节律、动静结合和维持协调，同样不替代个体医疗建议。"],examples:[{title:"同见寒象的辨析",explanation:"题干明确“寒邪偏盛、阴盛制阳”时偏向阴盛则寒；明确“阳气不足、温煦无力”时偏向阳虚则寒。先找虚实机制，不能只看“寒”字。"}],relationships:[{from:"阴阳归类",relation:"组织",to:"结构与功能知识"},{from:"阴阳失调",relation:"概括",to:"病机方向"},{from:"失衡类型",relation:"指导",to:"原则性调整方向"}],pitfalls:["把藏象脏腑与现代器官逐一等同。","只凭单一症状自行判断阴阳证候。","从基础理论原则直接跳到个人处方和治疗。"],selfChecks:["阴盛则寒与阳虚则寒应从哪两个维度比较？","阴阳学说在诊断和防治中的应用为什么只能先给出方向？"]})],b=e=>({...e,unitId:m,sourceIds:j,verifiedAt:u}),ce=[b({id:"yy-c01-attribute-substance",title:"阴阳属性与具体物质",items:["阴阳属性","具体物质"],dimensions:[{label:"本质",values:{阴阳属性:"关系中的相反倾向",具体物质:"有具体组成和边界的对象"}},{label:"是否固定",values:{阴阳属性:"随比较前提具有相对性",具体物质:"对象身份不因比较而任意改变"}},{label:"答题重点",values:{阴阳属性:"写清比较对象和依据",具体物质:"说明对象本身的性质"}}],decisionRule:"若题干要求“相对于谁”才能成立，考查的是阴阳属性而非两种实体。",commonTrap:"把阴和阳想成可单独取出的两种物质。",example:"胸相对腹属阳，说明的是方位关系，不是胸部由“阳物质”构成。"}),b({id:"yy-c02-relative-arbitrary",title:"阴阳相对性与随意变换",items:["相对性","随意变换"],dimensions:[{label:"前提",values:{相对性:"比较条件或层级发生变化",随意变换:"没有说明任何条件"}},{label:"原结论",values:{相对性:"在原前提下仍成立",随意变换:"任意推翻原结论"}},{label:"是否规范",values:{相对性:"符合关系判断",随意变换:"不符合阴阳判定规则"}}],decisionRule:"先问比较前提是否真的改变；未改变时不能以“相对”为由翻转答案。",commonTrap:"用“阴阳是相对的”逃避明确题境中的判断。",example:"昼相对夜仍属阳；只有改为比较昼中上午与下午，才进入新的层级。"}),b({id:"yy-c03-opposition-root",title:"对立制约与互根互用",items:["对立制约","互根互用"],dimensions:[{label:"核心关系",values:{对立制约:"属性相反并相互限制",互根互用:"相互依存并相互资生"}},{label:"题干动词",values:{对立制约:"制约、抑制、防止过度",互根互用:"依存、基础、资生、促进"}},{label:"典型结果",values:{对立制约:"限制偏亢",互根互用:"共同维持活动"}}],decisionRule:"题干强调“限制”选制约，强调“离不开和相互支持”选互根互用。",commonTrap:"看见双方有联系就不分作用方式。",example:"寒可制热属制约；功能依赖物质、物质更新依赖功能属互根互用。"}),b({id:"yy-c04-root-interaction",title:"互根互用与交感互藏",items:["互根互用","交感","互藏"],dimensions:[{label:"观察焦点",values:{互根互用:"双方依存和资生",交感:"双方在运动中发生作用",互藏:"一方内部含有对方因素"}},{label:"关键词",values:{互根互用:"根、用、基础",交感:"感应、作用、产生变化",互藏:"阴中有阳、阳中有阴"}},{label:"结构层次",values:{互根互用:"双方之间",交感:"双方作用过程",互藏:"一方内部"}}],decisionRule:"先判断题干谈“依存”“作用过程”还是“内部包含”。",commonTrap:"全部简化为“相互联系”。",example:"“阳中有阴”答互藏；“二气相感”答交感；“孤阴不生”答互根互用。"}),b({id:"yy-c05-wax-transform",title:"阴阳消长与阴阳转化",items:["消长","转化"],dimensions:[{label:"变化层级",values:{消长:"数量比例增减",转化:"总体属性改变"}},{label:"条件要求",values:{消长:"持续运动即可发生",转化:"必须达到一定条件"}},{label:"题干线索",values:{消长:"增加、减少、盛衰",转化:"转为、变成相反性质"}}],decisionRule:"先辨量变还是质变；只写强弱增减时不要选择转化。",commonTrap:"把任何变化都称为转化。",example:"热势减轻仍是量变；题干明确由热转寒才是性质转化。"}),b({id:"yy-c06-four-waxing",title:"阴阳消长的四种基本形式",items:["此长彼消","此消彼长","此长彼长","此消彼消"],dimensions:[{label:"第一方",values:{此长彼消:"增加",此消彼长:"减少",此长彼长:"增加",此消彼消:"减少"}},{label:"第二方",values:{此长彼消:"减少",此消彼长:"增加",此长彼长:"增加",此消彼消:"减少"}},{label:"关系侧重",values:{此长彼消:"对立制约",此消彼长:"对立制约",此长彼长:"互根互用",此消彼消:"互根互用"}}],decisionRule:"分别给双方画上下箭头，再按箭头组合命名。",commonTrap:"只看第一方变化，漏掉第二方方向。",example:"阳气增长并推动阴精生成是“阳长阴亦长”，属于此长彼长。"}),b({id:"yy-c07-balance-static",title:"动态平衡与绝对静止",items:["动态平衡","绝对静止"],dimensions:[{label:"是否变化",values:{动态平衡:"允许有度消长",绝对静止:"完全没有变化"}},{label:"判断标准",values:{动态平衡:"总体协调并可回调",绝对静止:"固定不动"}},{label:"生命适用性",values:{动态平衡:"符合节律性活动",绝对静止:"不能解释生命过程"}}],decisionRule:"题干有节律波动但总体协调，应判断为动态平衡。",commonTrap:"把平衡理解为双方永远各占一半。",example:"昼夜活动量不同但能有序交替，仍可保持总体协调。"}),b({id:"yy-c08-surplus-deficiency",title:"阴阳偏盛与阴阳偏衰",items:["偏盛","偏衰"],dimensions:[{label:"基本性质",values:{偏盛:"一方有余",偏衰:"一方不足"}},{label:"虚实",values:{偏盛:"以实性失衡为主",偏衰:"以虚性失衡为主"}},{label:"对方变化",values:{偏盛:"可制约或损伤对方",偏衰:"无力制约对方而显相对偏亢"}}],decisionRule:"先找“有余”还是“不足”，再判断寒热表现。",commonTrap:"只凭寒热结果判断，不看虚实来源。",example:"阳气不足、温煦无力属于阳偏衰，不是阴邪一定偏盛。"}),b({id:"yy-c09-cold",title:"阴盛则寒与阳虚则寒",items:["阴盛则寒","阳虚则寒"],dimensions:[{label:"起点",values:{阴盛则寒:"阴邪或阴性力量偏盛",阳虚则寒:"阳气不足"}},{label:"虚实",values:{阴盛则寒:"实寒方向",阳虚则寒:"虚寒方向"}},{label:"关键机制",values:{阴盛则寒:"阴盛制阳",阳虚则寒:"温煦无力"}}],decisionRule:"寒象之前先问：是寒性力量有余，还是温煦力量不足？",commonTrap:"见寒都选阴盛。",example:"题干写“阳气不足，失于温煦”时应判断阳虚则寒。"}),b({id:"yy-c10-heat",title:"阳盛则热与阴虚则热",items:["阳盛则热","阴虚则热"],dimensions:[{label:"起点",values:{阳盛则热:"阳热偏盛",阴虚则热:"阴液不足"}},{label:"虚实",values:{阳盛则热:"实热方向",阴虚则热:"虚热方向"}},{label:"关键机制",values:{阳盛则热:"阳盛制阴",阴虚则热:"阴不制阳"}}],decisionRule:"热象之前先问：是热性力量有余，还是制约温热的阴不足？",commonTrap:"见热都选阳盛。",example:"题干写“阴液亏少，不能制阳”时应判断阴虚则热。"}),b({id:"yy-c11-mutual-damage",title:"阴损及阳与阳损及阴",items:["阴损及阳","阳损及阴"],dimensions:[{label:"最初受损",values:{阴损及阳:"阴先虚",阳损及阴:"阳先虚"}},{label:"传变方向",values:{阴损及阳:"阴虚进一步累及阳",阳损及阴:"阳虚进一步累及阴"}},{label:"共同结果",values:{阴损及阳:"可成阴阳两虚",阳损及阴:"可成阴阳两虚"}}],decisionRule:"找时间顺序：谁先不足，概念名称就从谁开始。",commonTrap:"只看最后都属两虚，忽略起始方向。",example:"题干先有阴液亏损，日久出现阳气不足，属于阴损及阳。"}),b({id:"yy-c12-rejection-collapse",title:"阴阳格拒与阴阳亡失",items:["阴阳格拒","阴阳亡失"],dimensions:[{label:"基本状态",values:{阴阳格拒:"一方极盛把另一方格拒于外",阴阳亡失:"阴液或阳气大量亡失"}},{label:"表象特点",values:{阴阳格拒:"可出现真假相反的复杂表象",阴阳亡失:"以严重衰竭方向为主"}},{label:"学习重点",values:{阴阳格拒:"理解真寒假热、真热假寒的模型",阴阳亡失:"辨亡阴与亡阳的概念方向"}}],decisionRule:"格拒看“极盛与假象”，亡失看“根本物质或功能大量脱失”。",commonTrap:"把任何寒热错杂都称为格拒，或把一般偏衰称为亡失。",example:"基础题明确“一方极盛，将另一方排斥于外并现假象”时才指向格拒。"})],de=[{id:"yy-m01-definition",unitId:m,priority:"must-recite",prompt:"阴阳的基本含义是什么？",answer:"阴阳是对相关事物或同一事物内部相反而又相互联系的两个方面的概括。",mnemonic:"相关、相反、相联",relatedSectionId:"yy-01-frame"},{id:"yy-m02-opposition",unitId:m,priority:"must-recite",prompt:"对立制约的定义要点是什么？",answer:"阴阳双方属性相反，并在同一系统中相互斗争、相互制约，使变化保持一定限度。",relatedSectionId:"yy-03-opposition"},{id:"yy-m03-root",unitId:m,priority:"must-recite",prompt:"互根互用的定义要点是什么？",answer:"阴阳双方相互依存、互为根本，又在功能上相互资生、相互为用。",relatedSectionId:"yy-04-interdependence"},{id:"yy-m04-interaction",unitId:m,priority:"must-recite",prompt:"交感和互藏分别指什么？",answer:"交感指双方在运动中相互感应并发生作用；互藏指阴中有阳、阳中有阴，一方内部含有对方因素。",relatedSectionId:"yy-05-interaction"},{id:"yy-m05-waxing-four",unitId:m,priority:"must-recite",prompt:"阴阳消长四种基本形式是什么？",answer:"此长彼消、此消彼长、此长彼长、此消彼消。",mnemonic:"先画两支上下箭头",relatedSectionId:"yy-06-waxing"},{id:"yy-m06-transform",unitId:m,priority:"must-recite",prompt:"阴阳转化的两个得分关键词是什么？",answer:"总体属性向对立方面改变；必须在一定条件下发生。",mnemonic:"质变＋条件",relatedSectionId:"yy-07-transformation"},{id:"yy-m07-relative",unitId:m,priority:"must-recite",prompt:"阴阳属性相对性的三层含义是什么？",answer:"条件改变可转化；阴阳可再分；比较对象或层级改变时属性可改变。",relatedSectionId:"yy-02-attributes"},{id:"yy-m08-harmony",unitId:m,priority:"must-recite",prompt:"阴阳自和与阴阳平衡如何表述？",answer:"自和是在一定条件下通过双方相互作用趋向协调的能力；平衡是消长有度、总体相对协调的动态状态。",relatedSectionId:"yy-08-harmony"},{id:"yy-m09-decision",unitId:m,priority:"must-understand",prompt:"判断阴阳属性的四步法是什么？",answer:"确定对象，确定共同比较前提，判断相反属性，检查属性相对性。",relatedSectionId:"yy-01-frame"},{id:"yy-m10-relatedness",unitId:m,priority:"must-understand",prompt:"为什么阴阳的普遍性不等于任意性？",answer:"阴阳可以广泛概括相反关系，但被比较的双方必须相关、同层并具有共同前提。",relatedSectionId:"yy-02-attributes"},{id:"yy-m11-balance",unitId:m,priority:"must-understand",prompt:"为什么平衡不等于双方数量相等？",answer:"平衡看的是消长是否有度、总体能否协调，不同节律和状态可有不同适宜比例。",relatedSectionId:"yy-06-waxing"},{id:"yy-m12-surplus-deficiency",unitId:m,priority:"must-understand",prompt:"偏盛与偏衰的判断起点是什么？",answer:"先判断是一方有余还是一方不足，再结合寒热表现区分实性与虚性失衡。",relatedSectionId:"yy-09-application"},{id:"yy-m13-cold",unitId:m,priority:"must-understand",prompt:"阴盛则寒与阳虚则寒怎样快速区分？",answer:"前者为阴性力量有余、阴盛制阳；后者为阳气不足、温煦无力。",relatedSectionId:"yy-09-application"},{id:"yy-m14-heat",unitId:m,priority:"must-understand",prompt:"阳盛则热与阴虚则热怎样快速区分？",answer:"前者为阳热有余、阳盛制阴；后者为阴液不足、阴不制阳。",relatedSectionId:"yy-09-application"},{id:"yy-m15-mutual-damage",unitId:m,priority:"must-understand",prompt:"阴损及阳、阳损及阴的命名规则是什么？",answer:"按最先受损的一方命名：阴先虚后累及阳叫阴损及阳，阳先虚后累及阴叫阳损及阴。",relatedSectionId:"yy-09-application"},{id:"yy-m16-rejection",unitId:m,priority:"recognize",prompt:"看到“极盛、格拒、真假相反表象”应联想到什么？",answer:"联想到阴阳格拒的基础模型，但具体判断仍须依完整题干。",relatedSectionId:"yy-09-application"},{id:"yy-m17-collapse",unitId:m,priority:"recognize",prompt:"亡阴与亡阳属于哪类变化？",answer:"属于阴液或阳气大量亡失的严重失衡概念，不等同于一般阴虚或阳虚。",relatedSectionId:"yy-09-application"},{id:"yy-m18-boundary",unitId:m,priority:"recognize",prompt:"阴阳应用的边界是什么？",answer:"它提供关系和方向框架，不能替代具体藏象病机知识、完整诊察或个人治疗决策。",relatedSectionId:"yy-09-application"}],M=e=>({...e,unitId:m,sourceIds:j,verifiedAt:u}),ue=[M({id:"yy-w01",type:"term-definition",prompt:"名词解释：阴阳",answerOutline:["指出阴阳是关系范畴","写出相关、相反、相互联系","说明属性具有相对性"],scoringPoints:["不是两种固定物质","比较对象相关","相反相成","相对性"]}),M({id:"yy-w02",type:"term-definition",prompt:"名词解释：阴阳消长",answerOutline:["写阴阳处于运动变化","写双方数量比例增减","写消长有度维持动态平衡"],scoringPoints:["量变","四种形式可举例","不等同于转化"]}),M({id:"yy-w03",type:"short-answer",prompt:"简述阴阳学说的基本内容。",answerOutline:["先总述阴阳关系","分述对立制约、互根互用、交感互藏","分述消长、转化、自和平衡"],scoringPoints:["结构完整","每一关系含判断关键词","说明动态性"]}),M({id:"yy-w04",type:"short-answer",prompt:"简述阴阳属性的相对性。",answerOutline:["在给定前提下相对确定","条件改变可转化","阴阳可再分","比较层级改变可改变属性"],scoringPoints:["相对不等于随意","至少写出三层含义"]}),M({id:"yy-w05",type:"comparison",prompt:"比较对立制约与互根互用。",answerOutline:["先写共同点：都是阴阳双方关系","按作用方式比较","按题干关键词比较","说明二者可同时存在"],scoringPoints:["限制与依存资生的区别","制约与基础动力的典型表达","不把二者绝对割裂"]}),M({id:"yy-w06",type:"comparison",prompt:"比较阴阳消长与阴阳转化。",answerOutline:["先写两者都描述动态变化","消长是量变","转化是一定条件下质变","写消长可为转化积累条件"],scoringPoints:["量变","质变","一定条件","相互联系"]}),M({id:"yy-w07",type:"analysis",prompt:"某题同时出现“寒象”，如何区分阴盛则寒与阳虚则寒？",answerOutline:["先找有余或不足","再辨实寒与虚寒方向","阴盛制阳对应前者","温煦无力对应后者"],scoringPoints:["虚实","起始因素","机制","不凭单一寒字判断"]}),M({id:"yy-w08",type:"analysis",prompt:"说明阴阳学说在中医学习中的作用及应用边界。",answerOutline:["组织相反相成关系","概括生理协调与病理失衡方向","为诊断防治提供总纲思路","必须结合具体理论和完整资料"],scoringPoints:["关系框架","方向性","不能机械等同现代结构","不能直接形成个人处方"]})],fe=[r({id:"q-tcm-yinyang-13",unitId:m,conceptId:"tcm-yinyang-attribution",type:"single-choice",prompt:"判断一组对象能否用阴阳概括，第一步应做什么？",options:["先背诵属性表","确认双方是否相关且具有共同比较前提","先判断哪一方更重要","寻找现代解剖对应物"],answer:1,explanation:"阴阳是关系范畴，必须先确认比较对象相关、同层并具有共同前提。",misconceptionFeedback:{0:"属性表只能在比较前提成立后使用。",2:"阴阳判断不以主观重要性排序。",3:"阴阳关系不能靠寻找一个现代解剖对应物来成立。"}}),r({id:"q-tcm-yinyang-14",unitId:m,conceptId:"tcm-opposition",type:"single-choice",prompt:"“寒可制热，使过亢之热受到限制”最直接体现哪种阴阳关系？",options:["对立制约","互根互用","交感互藏","相互转化"],answer:0,explanation:"题干强调相反属性之间的限制作用，最直接体现对立制约。",misconceptionFeedback:{1:"互根互用强调依存和资生，不以限制过亢为核心。",2:"交感互藏不等于相反力量的制约。",3:"题干没有说明总体属性发生质变。"}}),r({id:"q-tcm-yinyang-15",unitId:m,conceptId:"tcm-waxing-transformation",type:"true-false",prompt:"阴阳一方数量增加、另一方数量减少，只要发生变化就属于阴阳转化。",answer:!1,explanation:"一增一减首先属于消长；只有在一定条件下总体属性向对立面改变，才属于转化。",misconceptionFeedback:{true:"把所有变化都称为转化，混淆了量变与质变。"}}),r({id:"q-tcm-yinyang-16",unitId:m,conceptId:"tcm-interdependence",type:"matching",prompt:"将阴阳关系与最直接的判断线索配对。",pairs:[{left:"对立制约",right:"相反并相互限制"},{left:"互根互用",right:"依存并相互资生"},{left:"交感",right:"运动中相互作用"},{left:"互藏",right:"一方内部含有对方因素"}],answer:["对立制约=>相反并相互限制","互根互用=>依存并相互资生","交感=>运动中相互作用","互藏=>一方内部含有对方因素"],explanation:"四组线索分别对应限制、依存资生、作用过程和内部包含。",misconceptionFeedback:{"":"先按“限制—依存—作用—内含”四个焦点逐一配对。"}}),r({id:"q-tcm-yinyang-17",unitId:m,conceptId:"tcm-yinyang-attribution",type:"ordering",prompt:"将阴阳属性判断步骤按正确顺序排列。",items:["确定比较对象","确定共同比较前提","判断相反属性","检查属性相对性"],answer:["确定比较对象","确定共同比较前提","判断相反属性","检查属性相对性"],explanation:"先确认对象和前提，才能使用属性线索，最后检查层级或条件改变是否影响结论。",misconceptionFeedback:{"":"若先判属性再找前提，容易把无关对象强行配成阴阳。"}}),r({id:"q-tcm-yinyang-18",unitId:m,conceptId:"tcm-waxing-transformation",type:"scenario",prompt:"题干描述冬至以后白昼逐渐延长、黑夜逐渐缩短，但昼夜属性本身未改变。最合适的判断是？",options:["此长彼消的消长","阴阳转化","阴阳亡失","阴阳格拒"],answer:0,explanation:"白昼增加、黑夜减少且基本属性未变，属于此长彼消的量变。",misconceptionFeedback:{1:"题干没有发生昼夜总体属性的质变。",2:"亡失指严重脱失，不是正常节律变化。",3:"格拒涉及极盛与真假相反表象，此处没有。"}}),r({id:"q-tcm-yinyang-19",unitId:m,conceptId:"tcm-yinyang-balance",type:"scenario",prompt:"某基础理论题明确写“阳气不足，温煦作用减弱而出现寒象”。应选哪一项？",options:["阴盛则寒","阳虚则寒","阳盛则热","阴虚则热"],answer:1,explanation:"起点是阳气不足，机制是温煦无力，属于阳偏衰所致的虚寒方向。",misconceptionFeedback:{0:"阴盛则寒的起点是阴性力量偏盛，而题干明确为阳不足。",2:"阳盛则热与题干寒象及阳不足均不符。",3:"阴虚则热强调阴不足、阴不制阳。"}}),r({id:"q-tcm-yinyang-20",unitId:m,conceptId:"tcm-yinyang-balance",type:"scenario",prompt:"“生命活动允许节律波动，但能通过双方相互作用回到总体协调范围”主要说明什么？",options:["平衡就是绝对静止","阴阳动态平衡与自和","任何失衡都会自行痊愈","阴阳属性可以随意改变"],answer:1,explanation:"题干同时强调有度波动、调节能力和总体协调，体现动态平衡与自和。",misconceptionFeedback:{0:"动态平衡允许持续而有度的消长。",2:"自和有条件和限度，不能推成任何失衡都会自行痊愈。",3:"属性改变必须有比较前提或条件，不是随意变化。"}})],ye={chapter:{unitId:m,title:"阴阳学说",introduction:"本章先训练“怎样判断阴阳”，再依次掌握对立制约、互根互用、交感互藏、消长、转化与自和，最后把寒热虚实等高频易混点放回统一关系网。",sections:me,confusions:ce,memoryItems:de,writtenPrompts:ue,summary:["任何阴阳判断都先写清比较对象与共同前提。","对立制约看限制，互根互用看依存资生，交感看作用过程，互藏看内部包含。","消长是量变，转化是一定条件下的质变；消长可为转化积累条件。","平衡是消长有度的动态协调，自和是趋向协调的调节能力。","寒热先辨虚实来源：阴盛与阳盛偏实，阳虚与阴虚偏虚。","阴阳是关系和方向框架，必须结合具体理论与完整资料使用。"]},questions:fe},n="tcmf-zangfu",F=[...P],ge=(e,i)=>({id:e.id,unitId:n,title:e.title,order:i+1,depth:e.depth,estimatedMinutes:e.estimatedMinutes,overview:e.overview,paragraphs:[...e.paragraphs,`学习“${e.title}”时，要依次回答五个问题：概念指什么、主导功能是什么、依赖哪些精气血津液或气机过程、怎样与其他脏腑协同、失常时教材用什么理论线索描述。先画功能箭头，再放入表里、五行和形窍志液等联系，最后才分析综合题。藏象所说的脏腑是以功能活动和外在征象为核心的传统理论系统，不能把名称机械等同于现代解剖器官，也不能由某一个症状、情志或外观线索直接推断个人疾病。网页内容用于课程学习和考试复习，不代替四诊合参、现代检查或专业诊疗。`],examples:[e.example],relationships:e.relationships,pitfalls:e.pitfalls,selfChecks:e.selfChecks,sourceIds:F,verifiedAt:u}),ve=[{id:"zangfu-01-frame",title:"藏象概念与研究对象",depth:"foundation",estimatedMinutes:24,overview:"藏象以脏腑内部功能活动及其显现于外的征象为研究核心。“藏”指藏于体内的脏腑及其功能系统，“象”既包括形态迹象，也包括生理、病理表现和与自然环境相应的关系。",paragraphs:["藏象学说不是把人体简单分成若干孤立器官，而是依据长期临床观察，把呼吸、消化吸收、血液运行、精神活动、生长发育、水液代谢和生殖等生命过程组织成若干相互协同的功能系统。学习时应把“内在功能—物质基础—外在表现”连成一条线：例如某脏的功能怎样依赖精气血津液，又怎样从面色、声音、形体、官窍、情志或二便等方面被观察。这里的外在征象只提供理论线索，必须综合判断，不能把单个表现当作唯一证据。","藏象推理重视整体性、功能性和动态性。同一个生理过程常由多个脏腑共同完成，一个脏腑也往往参与多条功能链。例如饮食物的受纳、腐熟、运化、升清、传导与排泄涉及脾胃、小肠、大肠以及肺肾三焦等；呼吸不仅归肺，也与肾的摄纳功能相联系。考试中若题干问“主要负责”，要找主导环节；若问“共同参与”或“相互影响”，则要展开协同链，不可用单脏包办全部过程。"],example:{title:"从外在征象回到功能链",explanation:"教材把肺与鼻、皮毛、声音等联系起来，意义在于组织观察线索；看到鼻部表现时仍需结合呼吸、宣肃、津液和全身资料，不能直接推出肺系证候。"},relationships:[{from:"内在脏腑功能",relation:"显现为",to:"形窍志液华等外在征象"},{from:"四诊获得的多项征象",relation:"综合支持",to:"藏象功能判断"},{from:"多个脏腑",relation:"协同完成",to:"完整生命过程"}],pitfalls:["把“象”只理解为器官外形。","见到一个外在征象就直接归属某脏。","把藏象名称与现代器官作一一机械等同。"],selfChecks:["“藏”与“象”分别强调什么？","为什么藏象推理必须同时看功能链和多项征象？"]},{id:"zangfu-02-classification",title:"五脏六腑奇恒之腑的分类逻辑",depth:"foundation",estimatedMinutes:23,overview:"藏象按主要功能特点把内脏概括为五脏、六腑与奇恒之腑：五脏偏于化生和贮藏精气，六腑偏于受盛、传化水谷并以通降为顺，奇恒之腑形态多中空似腑而功能偏于贮藏精气。",paragraphs:["五脏为心、肺、脾、肝、肾，教材常用“藏精气而不泻，故满而不能实”概括其共同特点。这里“满”偏指精气充盈，不是装满有形内容物。六腑为胆、胃、小肠、大肠、膀胱、三焦，常用“传化物而不藏，故实而不能满”概括，强调饮食物和水液在其中受纳、转化、传导与排泄，宜保持通畅。脏与腑的区别是主导功能差异，不是绝对静止的形态划分，也不表示五脏只藏不动、六腑只泻不受。","奇恒之腑包括脑、髓、骨、脉、胆、女子胞。“奇恒”意为异于通常六腑，其形多中空却有贮藏精气的功能特点。胆既列六腑，又属奇恒之腑：作为六腑，胆汁参与消化并与肝相表里；作为奇恒之腑，胆贮藏清净精汁而不直接传化水谷。分类题要先问比较标准是共同功能、形态还是具体作用，再说明“以功能为主、兼顾形态”的逻辑，避免只背名单。"],example:{title:"胆的双重归类",explanation:"胆具有腑的中空形态并参与通降，又贮藏精汁，因此同时体现六腑与奇恒之腑的特点；答题时应分别说明比较角度。"},relationships:[{from:"五脏",relation:"功能偏于",to:"化生与贮藏精气"},{from:"六腑",relation:"功能偏于",to:"受盛、传化与通降"},{from:"奇恒之腑",relation:"形似腑而功能似",to:"脏之贮藏"}],pitfalls:["把满与实理解成现代容积概念。","认为脏绝不排泄、腑绝不贮存。","忘记胆具有双重分类特点。"],selfChecks:["五脏、六腑、奇恒之腑的分类抓手各是什么？","为什么胆可以同时出现在六腑与奇恒之腑中？"]},{id:"zangfu-03-heart",title:"心：主血脉与藏神",depth:"understanding",estimatedMinutes:30,overview:"心的核心功能是主血脉与藏神。主血脉包括推动血液循行和主持脉道，依赖心气推动、心阳温煦、心血滋养与脉道通利；藏神概括意识、思维、情志和生命活动的统摄。",paragraphs:["心主血脉可拆为“主血”与“主脉”。心气推动血液在脉中运行，脉为血之府，是血液运行的通道；心血充盈、心气有力、脉道通利三者共同保证循环和节律。教材常从面色、脉象、胸部感受等联系理解其外候，但这些只是藏象线索。心主血脉与肝藏血、脾统血、肺朝百脉相互配合：心提供推动，肺助气行血，肝调节血量并贮藏，脾使血循脉中。综合题要写出主导与协同，不宜说“血的所有功能都由心完成”。","心藏神中的“神”是广义生命活动表现及狭义精神意识思维活动的概括。神以精、气、血、津液为物质基础，又能统摄脏腑功能。心在志为喜，在液为汗，在体合脉，其华在面，开窍于舌；这些联系构成观察网络而不是单线因果。汗为心之液并不表示所有出汗问题都归心，舌为心之苗也不表示舌象只反映心。答题时先写心的两大功能，再按题干选择血脉线或神志线展开。"],example:{title:"同一题干的两条心系线索",explanation:"题干若强调脉道、血行和面色，重点落在心主血脉；若强调意识、睡眠、思维与情志统摄，则重点落在心藏神，二者仍可通过心血联系。"},relationships:[{from:"心气",relation:"推动",to:"血液循脉运行"},{from:"心血",relation:"滋养",to:"心神活动"},{from:"心主血脉",relation:"协同于",to:"肺朝百脉、肝藏血、脾统血"}],pitfalls:["把心藏神只解释为情绪。","把汗、舌或面色的单一改变直接定为心病。","忽略血脉运行还需要肺肝脾等协同。"],selfChecks:["心主血脉需要哪些基本条件？","广义神与狭义神怎样区分？"]},{id:"zangfu-04-lung",title:"肺：主气司呼吸与宣发肃降",depth:"understanding",estimatedMinutes:34,overview:"肺主气、司呼吸，主宣发肃降，通调水道，朝百脉而主治节。宣发向上向外布散，肃降向下向内清肃，两者协调使呼吸、气机、津液输布和卫外功能正常。",paragraphs:["肺主气包含主呼吸之气和主一身之气。肺通过呼出浊气、吸入清气参与宗气生成，并以有节律的呼吸调节全身气机。肺朝百脉强调全身血液会聚于肺，通过呼吸清浊交换后再输布；肺主治节是对呼吸、气机、血行和水液节律调节的概括。肺主气不等于气只由肺生成：水谷精气来源于脾胃，先天之精和元气根于肾，肺吸入清气并参与宗气形成，三者共同构成气生成和运行的基础。","宣发有三层常用含义：呼出浊气，向上向外布散水谷精微和津液，宣散卫气并调节腠理。肃降包括吸入清气，向下输布津液和精微，保持呼吸道清肃并使异物下行。通调水道依赖宣肃，使水液向体表布散又向下输送，故称肺为水之上源；但水液代谢还需要脾运化、肾主水、三焦通道和膀胱气化。肺开窍于鼻，在体合皮，其华在毛，在志为忧，在液为涕，与大肠相表里。"],example:{title:"宣发与肃降不是互相取消",explanation:"宣发使津液向上向外布散，肃降使清气和津液向下向内运行，方向相反却共同维持肺气出入升降；综合题应同时写二者。"},relationships:[{from:"肺宣发",relation:"向上向外布散",to:"精微、津液与卫气"},{from:"肺肃降",relation:"向下向内输送",to:"清气、津液与精微"},{from:"肺通调水道",relation:"协同",to:"脾运化、肾主水与三焦通道"}],pitfalls:["把肺主气理解为所有气都由肺独自生成。","把宣发等同呼气、肃降等同吸气而遗漏输布功能。","把肺通调水道等同肾主水。"],selfChecks:["肺主气的两个层面是什么？","宣发与肃降分别有哪些内容，为什么必须协调？"]},{id:"zangfu-05-spleen",title:"脾：运化、升清与统血",depth:"understanding",estimatedMinutes:34,overview:"脾主运化、主升清并主统血。运化包括运化水谷和运化水液，升清把水谷精微上输心肺头目，统血使血液正常循行于脉中。脾胃共同构成后天之本和气血生化之源。",paragraphs:["运化水谷包括把饮食物转化为水谷精微并吸收转输，精微上输心肺后参与气血津液化生。运化水液指吸收、转输和利用水液，防止停聚。脾不直接等同现代脾脏，也不能把“运化”缩成单纯机械消化；它是对摄入、转化、吸收、输布等环节的传统功能概括。脾与胃一升一降：胃主受纳腐熟并以降为和，脾主运化转输并以升为健，两者纳运协调才能完成饮食精微化生。","脾主升清，“清”指水谷精微等精华物质，升清既使精微上输，也有维持内脏相对恒定位置的理论含义。脾主统血依靠脾气固摄，使血不逸出脉外；这与肝藏血的贮藏调节、心主血脉的推动运行不同。脾在体合肉、主四肢，开窍于口，其华在唇，在志为思，在液为涎，与胃相表里。做题遇到食少、精微不足、清阳不升、水湿停聚或血不循经等线索时，要先辨题目强调运化、升清还是统血。"],example:{title:"纳与运、升与降的组合",explanation:"胃先受纳腐熟，脾再化生转输；胃气宜降，脾气宜升。答题写“脾胃共同消化”不够，应明确每一环节的主导方向。"},relationships:[{from:"胃受纳腐熟",relation:"为其提供原料",to:"脾运化水谷"},{from:"脾升清",relation:"与之相反相成",to:"胃降浊"},{from:"脾气",relation:"固摄",to:"血液循脉而行"}],pitfalls:["把脾运化只等同胃肠消化。","把清理解成清除废物而写反升清。","混淆脾统血、肝藏血与心主血脉。"],selfChecks:["运化水谷与运化水液有什么联系？","脾升清、胃降浊如何相反相成？"]},{id:"zangfu-06-liver",title:"肝：疏泄与藏血",depth:"understanding",estimatedMinutes:35,overview:"肝主疏泄与藏血。疏泄强调使全身气机疏通、畅达，涉及情志、消化、胆汁排泄和生殖节律；藏血强调贮藏血液、调节血量并防止出血。",paragraphs:["肝主疏泄的核心是调畅气机。气机条达有助于脾胃升降和胆汁排泄，也为血液、津液运行提供动力条件；情志活动以气血调和为基础，故疏泄失常可与情志变化相互影响。疏泄还参与冲任、月经与生殖功能的调节。学习时不要把疏泄背成一串互不相关的功能，应抓住“气机畅达”这个总开关，再说明它怎样影响情志、消化和生殖。肝在五行属木，喜条达而恶抑郁，是功能特性的类比表达。","肝藏血包括贮藏一定血量、根据活动与休息调节血液分配，并有助于防止出血。活动时血液输布于外，休息时部分血液归藏于肝，是教材常用的动态理解。肝藏血与心主血脉相配合：心推动血行，肝贮藏和调节；与脾统血也不同，脾统血侧重固摄血液在脉内。肝在体合筋，其华在爪，开窍于目，在志为怒，在液为泪，与胆相表里。任何外在联系都需放回疏泄、藏血和整体资料中判断。"],example:{title:"用总机制统摄分支功能",explanation:"题目同时出现情志不畅、脾胃升降受影响和胆汁排泄线索时，可用“肝失疏泄—气机不畅”统摄，而不是把三条线分别死背。"},relationships:[{from:"肝疏泄",relation:"调畅",to:"全身气机"},{from:"肝藏血",relation:"贮藏并调节",to:"血量分配"},{from:"肝疏泄",relation:"促进",to:"脾胃升降与胆汁排泄"}],pitfalls:["把疏泄只理解为排泄。","把肝藏血等同心主血脉。","只凭怒、目或爪的单一表现判断肝系问题。"],selfChecks:["肝疏泄怎样以调畅气机统摄多个功能？","肝藏血与脾统血的区别是什么？"]},{id:"zangfu-07-kidney",title:"肾：藏精、主水与纳气",depth:"understanding",estimatedMinutes:38,overview:"肾藏精，主生长发育生殖与脏腑气化；肾主水，调节全身水液代谢；肾主纳气，摄纳肺所吸入的清气，使呼吸保持一定深度。肾被称为先天之本。",paragraphs:["肾精包括禀受于父母的先天之精，也包括出生后由水谷精微不断充养的后天之精。二者相互资助，化生肾气，推动生长、发育、成熟、衰老和生殖。教材以“女子七岁、男子八岁”等节律说明肾气、天癸与生殖能力的阶段变化，重点是理解生命阶段和物质基础，不应把古代年龄节点当作现代个体必须完全一致的硬性标准。肾精还能生髓，髓充养脑、骨和脊髓，因此肾与脑髓骨、齿、发、耳及二阴形成理论联系。","肾主水依靠肾气气化，把水液的升清降浊、再利用和排泄统摄起来，并通过膀胱气化影响尿液贮排；同时还需肺宣肃通调、脾运化转输和三焦水道共同参与。肾纳气与肺主呼吸不同：肺司呼吸并主气，肾摄纳清气使吸气深入而有根，故称肺为气之主、肾为气之根。肾在志为恐，在液为唾，开窍于耳及二阴，其华在发，与膀胱相表里。做题须按藏精、主水、纳气三条主线定位。"],example:{title:"肺肾共同完成呼吸",explanation:"肺负责呼吸出入和气机节律，肾负责摄纳清气；题目问“司呼吸”选肺，问“使吸气有根、保持深度”则指肾纳气。"},relationships:[{from:"先天之精与后天之精",relation:"相互充养形成",to:"肾精"},{from:"肾精",relation:"化生",to:"肾气与天癸"},{from:"肺吸入清气",relation:"由肾摄纳",to:"呼吸有根"}],pitfalls:["把先天之精与后天之精完全割裂。","把肾主水等同膀胱排尿。","把肺主气与肾纳气写成同一功能。"],selfChecks:["肾精、肾气、天癸之间怎样联系？","肾主水与肺脾膀胱三焦如何协同？"]},{id:"zangfu-08-six-fu",title:"胆胃小肠大肠膀胱三焦",depth:"understanding",estimatedMinutes:40,overview:"六腑以通为用、以降为顺，围绕饮食物和水液的受纳、腐熟、受盛、泌别、传导、贮排与通行构成动态通道。每一腑有主导环节，又必须在脏腑协同中理解。",paragraphs:["胃主受纳腐熟水谷，是水谷之海，以降为和，为脾运化提供原料；小肠主受盛化物并泌别清浊，承接胃中初步消化的食糜，进一步化物，把精微和部分水液吸收利用，把糟粕下送大肠；大肠主传化糟粕，吸收部分水液并形成、传送和排出大便。胆贮藏和排泄胆汁，胆汁有助于饮食物消化；胆又主决断，是传统藏象对判断与勇怯关系的概括。以上功能以通降为共同方向，但不能把食物过程理解为六腑之间毫无反馈的单向管道。","膀胱贮存和排泄尿液，其开合依赖肾气气化，又与肺脾三焦的水液输布相关。三焦是六腑之一，具有主持诸气、疏通水道的功能；上焦、中焦、下焦又可作为划分躯干部位和概括相关脏腑功能的框架。教材常以“上焦如雾、中焦如沤、下焦如渎”比喻不同部位水谷精微与水液运行特点。理解三焦要区分“一个六腑名称”“上中下三个部位层次”“气化水道功能”三种语境，不能只寻找单一现代解剖实体。"],example:{title:"饮食物的腑间流程",explanation:"胃受纳腐熟，小肠受盛化物、泌别清浊，大肠传化糟粕；脾的运化转输贯穿其间，因此流程题既要写腑的通降，也要写脾的协同。"},relationships:[{from:"胃",relation:"受纳腐熟后下传",to:"小肠"},{from:"小肠",relation:"泌别清浊并下传糟粕",to:"大肠"},{from:"肾气化",relation:"调节",to:"膀胱开合与尿液贮排"}],pitfalls:["把六腑理解成单纯解剖空腔。","混淆小肠泌别清浊与大肠传化糟粕。","把三焦只理解为三个互不相干的器官。"],selfChecks:["按顺序说明胃、小肠、大肠的主导功能。","三焦的部位概念和功能概念怎样区分？"]},{id:"zangfu-09-extraordinary",title:"脑髓骨脉胆女子胞",depth:"understanding",estimatedMinutes:30,overview:"奇恒之腑包括脑、髓、骨、脉、胆、女子胞，形态多中空，功能重在贮藏精气。其功能分属并联系五脏，其中以肾精、心神、肝血和冲任等关系最为常见。",paragraphs:["脑为髓海，由髓汇聚而成，髓由肾精化生，因此脑的充养与肾精有关；同时精神意识思维主要归于心藏神，故教材可同时讲“脑为元神之府”和“心主神明”，二者属于不同理论表述层次，不宜简单互相取消。髓有脑髓、脊髓和骨髓等含义，能充养脑和骨；骨的生长坚固依赖肾精生髓。脉既是血液运行通道，也归心所主，血脉充盈又依赖气血生成与推动。","女子胞主持月经和孕育，与肾精、天癸、冲任、心肝脾及全身气血密切相关。肾精充盛、天癸至、任通冲盛，是教材概括生殖成熟的重要链条；肝藏血、脾统血生血、心主血脉又从不同方面参与。胆兼属六腑与奇恒之腑，前者强调排泄胆汁和通降，后者强调贮藏精汁。奇恒之腑综合题应先写共同特点，再分别定位物质来源、主导功能和相关五脏，避免把所有功能都归肾。"],example:{title:"心主神明与脑为髓海",explanation:"答题可写：脑为髓海并与肾精充养有关；心藏神统摄精神意识活动。二者是藏象体系中不同的功能联系，不应硬套现代神经解剖作一一取代。"},relationships:[{from:"肾精",relation:"生髓并充养",to:"脑与骨"},{from:"心气心血",relation:"推动并充养",to:"脉与神"},{from:"肾精、天癸与冲任",relation:"共同支持",to:"女子胞月经孕育功能"}],pitfalls:["把脑为髓海和心藏神视为只能二选一。","把天癸等同生殖之精或某一现代激素。","遗漏胆的双重归类。"],selfChecks:["为什么说脑、髓、骨都与肾精有关？","女子胞的功能涉及哪些主要理论环节？"]},{id:"zangfu-10-correspondence",title:"五脏与形窍志液华时",depth:"exam",estimatedMinutes:31,overview:"五脏通过形体、官窍、情志、体液、外华和季节等多维联系形成可记忆、可观察的网络。表格必须与五脏主功能一起理解，不能把任何一列变成单独诊断公式。",paragraphs:["常用对应为：心在体合脉、其华在面、开窍于舌、在志为喜、在液为汗、应夏；肺在体合皮、其华在毛、开窍于鼻、在志为忧、在液为涕、应秋；脾在体合肉、主四肢、其华在唇、开窍于口、在志为思、在液为涎、应长夏；肝在体合筋、其华在爪、开窍于目、在志为怒、在液为泪、应春；肾主骨生髓、其华在发、开窍于耳及二阴、在志为恐、在液为唾、应冬。背诵时按同一维度纵向比较，比逐脏背六张小卡更不易串位。","理解对应表要回到功能。例如肝血滋养筋目爪，肾精生髓充骨并濡养发耳，肺宣发卫气和津液至皮毛，脾运化精微以充养肌肉四肢，心血脉状态可反映于面。情志既可由脏腑气血状态影响，过度或持久情志又可反过来扰动气机。季节对应提示生理适应与理论类比，不表示某脏只在一个季节工作。考试看到对应项错误时，要用“功能—所养对象”解释，避免只说口诀。"],example:{title:"纵向比较官窍",explanation:"心—舌、肺—鼻、脾—口、肝—目、肾—耳及二阴。先按五脏顺序固定官窍，再补形体、情志和体液，能减少跨列串记。"},relationships:[{from:"五脏主功能",relation:"濡养或影响",to:"形体官窍与外华"},{from:"脏腑气血",relation:"影响并受其反作用",to:"情志活动"},{from:"季节环境",relation:"形成理论相应",to:"五脏功能节律"}],pitfalls:["把对应表任何一项当成单独诊断证据。","把“在志为”解释成某脏只产生一种情绪。","认为某脏只在其对应季节发挥作用。"],selfChecks:["按心肺脾肝肾顺序说出官窍与体液。","如何用功能联系解释肝合筋、肾主骨？"]},{id:"zangfu-11-heart-lung",title:"心肺协同",depth:"exam",estimatedMinutes:26,overview:"心主血脉，肺主气、司呼吸并朝百脉。心肺通过宗气、气血相互依存和呼吸血行节律共同维持气血运行，是“气为血之帅、血为气之母”在脏腑层面的重要体现。",paragraphs:["肺吸入清气，脾胃化生水谷精气，两者在胸中结合形成宗气。宗气贯心脉、行呼吸，既帮助肺司呼吸，又资助心推动血行。心气推动血液循脉，血载气运行并滋养肺；肺气宣肃和呼吸节律又协助血液运行、清浊交换。由此可见，心主血与肺主气不是两条平行而无关的功能，而是在胸中和脉道上交汇。","答心肺关系题可用三步：先写心主血脉、肺主气司呼吸；再写宗气贯心脉而司呼吸，气推动血、血载气；最后写肺朝百脉、呼吸与血行相互协调。若题目要求病理联系，只能在给定理论材料内说明一方失调可影响另一方，不应由胸闷、气短等真实症状自行诊断。心肺协同是功能模型，现代心肺循环知识可帮助理解但不能替换教材术语。"],example:{title:"宗气是心肺联系的桥梁",explanation:"宗气聚于胸中，贯心脉以助血行，又走息道以司呼吸。简答题写出这两个方向，心肺关系才完整。"},relationships:[{from:"宗气",relation:"贯注",to:"心脉"},{from:"宗气",relation:"支持",to:"肺司呼吸"},{from:"肺朝百脉",relation:"协助",to:"心主血脉"}],pitfalls:["只写气血关系而不点出宗气。","把肺朝百脉解释成肺取代心推动血液。","用现代循环术语完全替换藏象术语。"],selfChecks:["宗气怎样分别联系心与肺？","为什么心肺关系可概括为气与血的协同？"]},{id:"zangfu-12-liver-spleen",title:"肝脾协同",depth:"exam",estimatedMinutes:27,overview:"肝主疏泄、藏血，脾主运化、升清、统血。肝脾在气机升降、饮食精微化生和血液生成贮藏固摄方面相互协同，形成“木土相调”的重要关系。",paragraphs:["肝疏泄使气机条达，能够促进脾升胃降和胆汁排泄，有利于饮食受纳、腐熟、运化和转输；脾运化健旺，水谷精微充足，又能化生气血以濡养肝体，使肝气条达。因此肝脾关系不是单向“肝帮助脾”，而是肝调气机、脾供精微的双向支持。五行上肝木克脾土是制约关系，但正常生理还要结合脏腑具体功能，不能见肝脾题就一律写木乘土。","血液方面，脾为气血生化之源并统摄血液循脉，肝贮藏血液并调节血量。脾生血、统血与肝藏血共同维持血液数量和运行边界。综合题若强调食欲、运化、升降随情志气机变化，重点写肝疏泄与脾运化；若强调血量调节和血不逸脉，则写肝藏血与脾统血。题干未给病理性质时，只写协同关系，不越级确定证候。"],example:{title:"同属肝脾关系的两条主线",explanation:"消化主线是肝疏泄调气机、脾运化生精微；血液主线是脾生血统血、肝藏血调血量。先辨题干落在哪条线。"},relationships:[{from:"肝疏泄",relation:"促进",to:"脾升胃降与运化"},{from:"脾运化",relation:"化生气血濡养",to:"肝体与肝用"},{from:"脾统血",relation:"配合",to:"肝藏血"}],pitfalls:["把肝脾关系只写成五行相克。","混淆肝疏泄与脾运化的主导环节。","把脾统血和肝藏血写成完全相同。"],selfChecks:["肝脾在消化过程中怎样双向支持？","肝藏血与脾统血怎样共同维持血液正常？"]},{id:"zangfu-13-water",title:"脾肺肾与水液代谢",depth:"exam",estimatedMinutes:32,overview:"水液代谢以脾运化转输、肺宣发肃降通调、肾气化主水为核心，并借三焦为通道、膀胱贮排完成。上中下多层协同，不能把“主水”理解为肾独自处理全部水液。",paragraphs:["饮入于胃后，脾把可利用水液吸收并转输至肺；肺通过宣发把津液布散到体表和全身，通过肃降把水液向下输送，又以通调水道保持运行；肾气化统摄水液的升清、降浊与再利用，并把浊液下输膀胱形成尿液；膀胱在肾气化作用下贮尿和排尿。三焦疏通水道，使水液有运行空间。此链条是学习框架，各环节并非简单一次完成的直线工序。","教材常称肺为水之上源、脾为水液转输之枢、肾为主水之脏。肺强调布散与下输，脾强调吸收与转输，肾强调气化统摄，三者功能不同但相互影响。答题可按“来源—转输—布散—气化—排泄”组织，并补三焦与膀胱。若题干只问某一功能，不要把整条链都归给该脏；若问水液失常的脏腑相关性，应说明多个环节均可能参与而非直接给个人治疗意见。"],example:{title:"水液链的主导动词",explanation:"脾是运化转输，肺是宣发肃降、通调，肾是气化主水，三焦是通道，膀胱是贮排。用动词区分比只背“都管水”更准确。"},relationships:[{from:"脾运化",relation:"转输水液至",to:"肺"},{from:"肺宣肃通调",relation:"布散并下输",to:"全身与肾膀胱"},{from:"肾气化",relation:"统摄并调节",to:"水液升清降浊与膀胱开合"}],pitfalls:["把水液代谢归肾单独完成。","混淆肺通调、脾运化和肾主水的动词。","把学习链条当成没有反馈的严格单向流程。"],selfChecks:["用五个主导动词复述水液代谢链。","肺、脾、肾在水液代谢中的区别是什么？"]},{id:"zangfu-14-relations",title:"脏腑表里及多脏协同推理",depth:"exam",estimatedMinutes:36,overview:"脏与腑通过经脉络属形成表里配合：心与小肠、肺与大肠、脾与胃、肝与胆、肾与膀胱，心包与三焦。复杂生理过程还常跨越一对表里，需沿气、血、精、津液和气机升降建立多脏协同图。",paragraphs:["表里关系以经脉络属和功能配合为基础，不表示两者功能相同。脾胃共同完成纳运、升降，肝胆共同参与疏泄与胆汁排泄，肾与膀胱共同调节尿液生成贮排，心与小肠、肺与大肠等也有理论上的相互联系。回答表里题先写固定配对，再用各自主导功能说明配合点；不能把“相表里”泛化为现代解剖直接相连，也不能由一方的单个表现自动推断另一方。","多脏协同题宜采用流程法。气的生成看肺吸清气、脾化水谷精气、肾精化元气；血的运行看心推动、肺助行、肝调藏、脾统摄；水液代谢看脾转输、肺通调、肾气化、三焦通道、膀胱贮排；呼吸看肺司呼吸与肾纳气；饮食看胃受纳、小肠化物、大肠传导与脾运化。先定题干的“物质或过程”，再找起点、推动、通道、调节和归宿，最后写主次，能够避免罗列脏腑却没有关系。"],example:{title:"多脏协同答题模板",explanation:"先写“本题围绕水液代谢”，再依次写脾转输、肺布散下输、肾气化、三焦通道、膀胱贮排，最后总结各脏腑分工协同；不要只列名称。"},relationships:[{from:"五脏",relation:"经脉络属形成表里",to:"相应六腑"},{from:"气血精津液过程",relation:"串联",to:"多个脏腑主导功能"},{from:"主导脏腑",relation:"不排除",to:"其他脏腑协同"}],pitfalls:["把相表里理解为功能完全相同。","多脏题只罗列名称而不写箭头关系。","从一个症状跨越功能链直接作个人诊断。"],selfChecks:["写出五组脏腑表里配对及心包三焦。","多脏协同题为什么要先确定物质或过程？"]}].map(ge),y=(e,i,o,l,c,g,v,w,D,X,U)=>({id:e,unitId:n,title:i,items:[o,l],dimensions:[{label:"核心含义",values:{[o]:c,[l]:g}},{label:"主导抓手",values:{[o]:v,[l]:w}},{label:"答题定位",values:{[o]:`题干主要落在“${o}”的功能方向`,[l]:`题干主要落在“${l}”的功能方向`}},{label:"不可混同",values:{[o]:`不能用${l}的主导动词替代`,[l]:`不能用${o}的主导动词替代`}}],decisionRule:D,commonTrap:X,example:U,sourceIds:F,verifiedAt:u}),Q=(e,i,o,l,c,g)=>{const v=Object.keys(o);return{id:e,unitId:n,title:i,items:v,dimensions:[{label:"核心含义",values:Object.fromEntries(v.map(w=>[w,o[w].core]))},{label:"主导抓手",values:Object.fromEntries(v.map(w=>[w,o[w].focus]))},{label:"作答动词",values:Object.fromEntries(v.map(w=>[w,`先写${o[w].focus}，再联系协同对象`]))}],decisionRule:l,commonTrap:c,example:g,sourceIds:F,verifiedAt:u}},he=[y("zangfu-c01-model-organ","藏象之象与现代解剖器官","藏象之象","现代解剖器官","内在功能活动及外在征象组成的传统功能系统","有明确形态位置、组织结构与生理机制的实体","功能—物质—征象关系","结构、组织与可测机制","题目问教材功能归属用藏象，问结构定位用现代解剖；二者可对照但不可互换。","把中医同名脏腑机械缩成一个现代器官。","“脾主运化”是传统功能概括，不等同现代脾脏承担消化吸收。"),Q("zangfu-c02-groups","五脏、六腑与奇恒之腑",{五脏:{core:"化生和贮藏精气",focus:"藏而不泻、满而不实"},六腑:{core:"受盛与传化水谷",focus:"泻而不藏、实而不满、以通为用"},奇恒之腑:{core:"形多中空而功能偏贮藏精气",focus:"形似腑、用似脏"}},"先看题目比较的是共同功能还是形态，再按主导特点分类。","认为中空者必属六腑，因而漏掉奇恒之腑。","胆属六腑又属奇恒之腑，正说明分类角度不同。"),y("zangfu-c03-heart","心主血脉与心藏神","心主血脉","心藏神","推动血液循脉运行并主持脉道","统摄生命活动与精神意识思维","心气、心血与脉道","神以精气血津液为基础","血行、脉象、面色多指主血脉；意识、思维、睡眠、情志统摄多指藏神。","把心藏神只写成喜悦，或把主血脉写成神志功能。","心血可滋养心神，说明两功能联系但并不相同。"),y("zangfu-c04-lung-kidney-qi","肺主气与肾纳气","肺主气","肾纳气","司呼吸并调节一身之气","摄纳肺吸入的清气使吸气有根","呼吸出入、宗气与气机","吸气深度与摄纳","题干问司呼吸、呼出浊气选肺；问摄纳清气、呼吸有根选肾。","因为都与呼吸有关就把二者答案互换。","肺为气之主，肾为气之根。"),y("zangfu-c05-lung-directions","肺宣发与肺肃降","肺宣发","肺肃降","向上向外布散精微津液卫气并呼出浊气","向下向内输送清气津液并保持清肃","布散、卫外、腠理","吸清、下输、清肃","先看方向：向上向外为宣发，向下向内为肃降；完整肺气机必须二者协调。","只用呼气与吸气区分，漏掉精微津液输布。","宣发把津液布散体表，肃降把水液下输肾膀胱。"),Q("zangfu-c06-water","肺通调水道、脾运化水液与肾主水",{肺通调水道:{core:"以宣发肃降布散并下输水液",focus:"上源、布散、下输"},脾运化水液:{core:"吸收、转输和利用水液",focus:"中焦转输之枢"},肾主水:{core:"以肾气气化统摄水液升清降浊",focus:"气化、主水、膀胱开合"}},"用主导动词区分：肺通调、脾运化、肾气化主水，再说明三者协同。","把三个功能都写成“排水”。","饮水入胃后，脾转输、肺布散下输、肾气化并调节膀胱。"),y("zangfu-c07-spleen-stomach","脾主运化与胃主受纳","脾主运化","胃主受纳","化生并转输水谷精微和水液","接受并初步腐熟饮食物","化、运、输","纳、腐熟","题干问摄入容纳选胃，问精微化生转输选脾。","笼统写成脾胃都消化而不分环节。","胃为脾提供水谷原料，脾把水谷精微转输全身。"),y("zangfu-c08-rise-descend","脾升清与胃降浊","脾升清","胃降浊","把水谷精微上输心肺头目","使胃中食糜和浊物向下传导","清阳上升、精微上输","以降为和、浊物下行","先辨清浊，再看升降：清者由脾升，浊者由胃降。","把“清”理解成清除废物而将方向写反。","脾升胃降共同维持中焦气机枢纽。"),y("zangfu-c09-blood-control","脾统血与肝藏血","脾统血","肝藏血","脾气固摄血液使其循脉","贮藏血液并调节血量分配","固摄、防止逸出","贮藏、调节、供给活动","题干问血不逸脉偏统血，问活动休息间血量调节偏藏血。","看到出血两字就不分机制。","脾统血守住运行边界，肝藏血调节血量。"),y("zangfu-c10-liver-spleen","肝疏泄与脾运化","肝疏泄","脾运化","调畅气机并促进脾胃升降","化生和转输水谷精微","气机条达、促运","精微生成、转输","情志与气机影响饮食多从肝疏泄切入，饮食精微化生不足从脾运化切入。","把肝疏泄直接等同消化，或把脾运化等同调情志。","肝以气机助脾，脾以精微养肝。"),y("zangfu-c11-liver-heart-blood","肝藏血与心主血脉","肝藏血","心主血脉","贮藏并调节血量","推动血液循脉运行","调节供血与防止出血","推动、脉道与节律","问血量贮藏调节选肝，问血行推动和脉道选心。","把“都与血有关”当作同一功能。","活动时肝调出血量，心推动血液运行至全身。"),y("zangfu-c12-kidney-essence-water","肾藏精与肾主水","肾藏精","肾主水","贮藏先后天之精，关系生长发育生殖","以肾气气化统摄水液代谢","精、髓、天癸、生殖","气化、升清降浊、尿液","题干围绕生命阶段和生殖选藏精，围绕水液气化和尿液选主水。","把“精”和“水”都理解成一般体液。","肾精化生肾气，肾气又是主水气化的动力基础。"),y("zangfu-c13-essence-qi","肾精与肾气","肾精","肾气","构成和维持生命活动的精微物质基础","由肾精化生并表现为推动、温煦、固摄和气化功能","物质基础、充养髓骨生殖","功能动力、生长与水液气化","问物质贮藏、生髓化血偏肾精；问推动气化和功能强弱偏肾气。","把肾精与肾气当作两个毫无联系的实体。","肾精充足可化生肾气，肾气又保护和固摄肾精。"),y("zangfu-c14-small-intestine","小肠受盛化物与泌别清浊","受盛化物","泌别清浊","承受胃中食糜并进一步消化变化","把精微与糟粕、水液进行分判","承接与化物","分清别浊并输送","题干问承受和继续消化选受盛化物，问清浊分判选泌别清浊。","把两个功能合成一句“吸收”而失去区分。","小肠先受盛化物，再从中泌别清浊并分别转输。"),y("zangfu-c15-large-bladder","大肠传化糟粕与膀胱贮尿排尿","大肠传化糟粕","膀胱贮尿排尿","形成、传送和排出大便并吸收部分水液","贮存和排泄尿液，开合依赖肾气化","糟粕、大便、传导","尿液、开合、气化","按排泄物区分：糟粕大便归大肠，尿液贮排归膀胱。","因为都属排泄就忽略物质来源与气化条件。","小肠浊中之浊下传大肠，水液代谢之浊下输膀胱。"),y("zangfu-c16-triple","三焦部位概念与三焦功能概念","三焦部位概念","三焦功能概念","以上中下焦划分躯干并概括相关脏腑","主持诸气、疏通水道并运行水谷精微","部位层次与所属脏腑","气化通道和水液运行","题目问上中下范围用部位概念，问诸气水道用功能概念。","执着寻找一个与全部三焦含义完全对应的现代器官。","“上焦如雾”是部位功能比喻，“通调三焦水道”强调运行功能。"),y("zangfu-c17-gallbladder","胆作为六腑与胆作为奇恒之腑的特点","胆属六腑","胆属奇恒之腑","参与胆汁排泄和通降并与肝相表里","贮藏清净精汁而不直接传化水谷","通降、排泄、表里","贮藏精汁、形中空","题目从通降传化角度看六腑，从贮藏精汁角度看奇恒之腑。","认为双重分类互相矛盾。","胆的同一功能系统可在不同分类标准下呈现双重特点。"),y("zangfu-c18-brain-marrow","脑与髓","脑","髓","髓汇聚形成的髓海，关系精神与感觉运动的传统表述","由肾精化生，充养脑、骨和脊柱","髓海与神明联系","精生髓、髓养脑骨","问髓海及高级活动联系看脑，问来源和充养看髓与肾精。","把脑髓关系只理解成现代组织结构。","肾精生髓，髓聚成脑，故脑的充养与肾精有关。"),y("zangfu-c19-tiankui","天癸与生殖之精","天癸","生殖之精","肾精充盛到一定阶段产生的促进生殖成熟的精微物质","直接参与生殖和胚胎形成的精微物质","生命阶段、成熟节律","生殖物质与孕育","题干问随肾气盛衰出现和衰竭的成熟条件选天癸，问直接参与孕育选生殖之精。","把天癸机械等同某一种现代激素或生殖细胞。","肾精充盛—天癸至—冲任通盛—具备生殖能力，是教材关系链。"),y("zangfu-c20-single-system","单脏功能与脏腑协同","单脏功能","脏腑协同","用于定位某一环节的主导责任","用于说明完整生命过程中的分工和相互支持","主要、核心、直接","共同、相互、全过程","题目问“主要功能”先定单脏，问“过程与关系”必须画协同箭头。","用一个脏包办全过程，或只罗列多个脏而不写关系。","血行以心推动为主，同时有肺助行、肝调藏和脾统摄。")],we=[{id:"zangfu-m01",unitId:n,priority:"must-recite",prompt:"藏象的基本含义是什么？",answer:"研究藏于体内的脏腑功能活动及其显现于外的生理病理征象与相互关系。",relatedSectionId:"zangfu-01-frame"},{id:"zangfu-m02",unitId:n,priority:"must-recite",prompt:"五脏的共同功能特点是什么？",answer:"化生和贮藏精气，藏而不泻，满而不能实。",relatedSectionId:"zangfu-02-classification"},{id:"zangfu-m03",unitId:n,priority:"must-recite",prompt:"六腑的共同功能特点是什么？",answer:"受盛和传化水谷，泻而不藏，实而不能满，以通为用、以降为顺。",relatedSectionId:"zangfu-02-classification"},{id:"zangfu-m04",unitId:n,priority:"must-recite",prompt:"奇恒之腑包括哪些？",answer:"脑、髓、骨、脉、胆、女子胞。",mnemonic:"脑髓骨脉胆胞",relatedSectionId:"zangfu-09-extraordinary"},{id:"zangfu-m05",unitId:n,priority:"must-recite",prompt:"心的两大主要功能是什么？",answer:"心主血脉，心藏神。",relatedSectionId:"zangfu-03-heart"},{id:"zangfu-m06",unitId:n,priority:"must-recite",prompt:"肺的主要功能怎样概括？",answer:"肺主气、司呼吸，主宣发肃降，通调水道，朝百脉而主治节。",relatedSectionId:"zangfu-04-lung"},{id:"zangfu-m07",unitId:n,priority:"must-recite",prompt:"脾的三项核心功能是什么？",answer:"脾主运化，主升清，主统血。",relatedSectionId:"zangfu-05-spleen"},{id:"zangfu-m08",unitId:n,priority:"must-recite",prompt:"肝的两大主要功能是什么？",answer:"肝主疏泄，肝藏血。",relatedSectionId:"zangfu-06-liver"},{id:"zangfu-m09",unitId:n,priority:"must-recite",prompt:"肾的三条核心功能主线是什么？",answer:"肾藏精，主水，主纳气。",relatedSectionId:"zangfu-07-kidney"},{id:"zangfu-m10",unitId:n,priority:"must-recite",prompt:"五组脏腑表里配对是什么？",answer:"心与小肠、肺与大肠、脾与胃、肝与胆、肾与膀胱；另有心包与三焦。",relatedSectionId:"zangfu-14-relations"},{id:"zangfu-m11",unitId:n,priority:"must-recite",prompt:"六腑按水谷传化主线怎样记？",answer:"胃受纳腐熟，小肠受盛化物并泌别清浊，大肠传化糟粕，膀胱贮尿排尿，胆贮排胆汁，三焦主持诸气、疏通水道。",relatedSectionId:"zangfu-08-six-fu"},{id:"zangfu-m12",unitId:n,priority:"must-recite",prompt:"五脏官窍如何对应？",answer:"心开窍于舌，肺开窍于鼻，脾开窍于口，肝开窍于目，肾开窍于耳及二阴。",relatedSectionId:"zangfu-10-correspondence"},{id:"zangfu-m13",unitId:n,priority:"must-recite",prompt:"五脏情志如何对应？",answer:"心在志为喜，肺在志为忧，脾在志为思，肝在志为怒，肾在志为恐。",relatedSectionId:"zangfu-10-correspondence"},{id:"zangfu-m14",unitId:n,priority:"must-recite",prompt:"五脏体液如何对应？",answer:"心在液为汗，肺在液为涕，脾在液为涎，肝在液为泪，肾在液为唾。",relatedSectionId:"zangfu-10-correspondence"},{id:"zangfu-m15",unitId:n,priority:"must-understand",prompt:"为什么不能把藏象等同现代器官？",answer:"藏象以功能活动、物质基础和外在征象组成系统，范围常超过同名解剖器官。",relatedSectionId:"zangfu-01-frame"},{id:"zangfu-m16",unitId:n,priority:"must-understand",prompt:"心主血脉需要哪三个基本条件？",answer:"心气推动有力、心血充盈、脉道通利。",relatedSectionId:"zangfu-03-heart"},{id:"zangfu-m17",unitId:n,priority:"must-understand",prompt:"心藏神的物质基础是什么？",answer:"神以精、气、血、津液为物质基础，心血充足是心神活动的重要条件。",relatedSectionId:"zangfu-03-heart"},{id:"zangfu-m18",unitId:n,priority:"must-understand",prompt:"肺宣发的三个重点是什么？",answer:"呼出浊气；布散水谷精微和津液；宣散卫气、调节腠理。",relatedSectionId:"zangfu-04-lung"},{id:"zangfu-m19",unitId:n,priority:"must-understand",prompt:"肺肃降的三个重点是什么？",answer:"吸入清气；向下输布津液精微；保持呼吸道清肃并使异物下行。",relatedSectionId:"zangfu-04-lung"},{id:"zangfu-m20",unitId:n,priority:"must-understand",prompt:"脾运化水谷包含哪些环节？",answer:"把饮食物化为水谷精微，吸收精微，并向心肺及全身转输。",relatedSectionId:"zangfu-05-spleen"},{id:"zangfu-m21",unitId:n,priority:"must-understand",prompt:"脾升清与胃降浊怎样配合？",answer:"脾把精微上输，胃使食糜浊物下行，一升一降维持中焦气机。",relatedSectionId:"zangfu-05-spleen"},{id:"zangfu-m22",unitId:n,priority:"must-understand",prompt:"肝疏泄如何统摄多项功能？",answer:"以调畅气机为核心，进一步影响情志、脾胃升降、胆汁排泄和生殖节律。",relatedSectionId:"zangfu-06-liver"},{id:"zangfu-m23",unitId:n,priority:"must-understand",prompt:"肝藏血与脾统血怎样区分？",answer:"肝藏血重在贮藏和调节血量，脾统血重在固摄血液不逸出脉外。",relatedSectionId:"zangfu-06-liver"},{id:"zangfu-m24",unitId:n,priority:"must-understand",prompt:"先天之精与后天之精怎样联系？",answer:"先天之精禀受父母，后天之精来自水谷精微；二者相互资助、共同充养肾精。",relatedSectionId:"zangfu-07-kidney"},{id:"zangfu-m25",unitId:n,priority:"must-understand",prompt:"肾纳气与肺司呼吸怎样分工？",answer:"肺主呼吸出入，肾摄纳清气使吸气深入而有根。",relatedSectionId:"zangfu-07-kidney"},{id:"zangfu-m26",unitId:n,priority:"must-understand",prompt:"小肠“泌别清浊”分出什么去向？",answer:"精微上输脾，糟粕下传大肠，部分水液经气化下输膀胱。",relatedSectionId:"zangfu-08-six-fu"},{id:"zangfu-m27",unitId:n,priority:"must-understand",prompt:"三焦的两种主要学习角度是什么？",answer:"上中下焦的部位层次，以及主持诸气、疏通水道的功能概念。",relatedSectionId:"zangfu-08-six-fu"},{id:"zangfu-m28",unitId:n,priority:"must-understand",prompt:"心肺关系的桥梁是什么？",answer:"宗气聚于胸中，贯心脉以助血行，又走息道以助呼吸。",relatedSectionId:"zangfu-11-heart-lung"},{id:"zangfu-m29",unitId:n,priority:"must-understand",prompt:"肝脾在消化方面怎样相互支持？",answer:"肝疏泄调畅气机以助脾胃升降，脾运化精微化生气血以濡养肝。",relatedSectionId:"zangfu-12-liver-spleen"},{id:"zangfu-m30",unitId:n,priority:"must-understand",prompt:"水液代谢的五个角色怎样分工？",answer:"脾转输、肺布散下输、肾气化、三焦通道、膀胱贮排。",relatedSectionId:"zangfu-13-water"},{id:"zangfu-m31",unitId:n,priority:"recognize",prompt:"“上焦如雾、中焦如沤、下焦如渎”各提示什么？",answer:"分别提示上焦布散、中焦腐熟运化、下焦分清泌浊和排泄的功能特点。",relatedSectionId:"zangfu-08-six-fu"},{id:"zangfu-m32",unitId:n,priority:"recognize",prompt:"为什么胆具有双重分类？",answer:"胆中空并参与通降似六腑，又贮藏精汁而不直接传化水谷似奇恒之腑。",relatedSectionId:"zangfu-09-extraordinary"},{id:"zangfu-m33",unitId:n,priority:"recognize",prompt:"脑、髓、骨之间的理论链条是什么？",answer:"肾精生髓，髓聚成脑并充养骨。",relatedSectionId:"zangfu-09-extraordinary"},{id:"zangfu-m34",unitId:n,priority:"recognize",prompt:"天癸的课程定义要点是什么？",answer:"肾精充盛到一定阶段产生、促进生殖器官成熟并维持生殖功能的精微物质。",relatedSectionId:"zangfu-09-extraordinary"},{id:"zangfu-m35",unitId:n,priority:"recognize",prompt:"五脏外华怎样对应？",answer:"心华在面，肺华在毛，脾华在唇，肝华在爪，肾华在发。",relatedSectionId:"zangfu-10-correspondence"},{id:"zangfu-m36",unitId:n,priority:"recognize",prompt:"多脏协同题的通用作答顺序是什么？",answer:"先定物质或过程，再找起点、推动、转化、通道、调节和归宿，最后说明主次。",relatedSectionId:"zangfu-14-relations"}],h=e=>({...e,unitId:n,sourceIds:F,verifiedAt:u}),Ie=[h({id:"zangfu-w01",type:"term-definition",prompt:"名词解释：藏象",answerOutline:["解释藏与象","写内在功能和外在征象","写脏腑相互关系","说明传统功能模型边界"],scoringPoints:["藏","象","功能征象联系","整体关系"]}),h({id:"zangfu-w02",type:"term-definition",prompt:"名词解释：肺主治节",answerOutline:["肺对呼吸的节律调节","调节一身之气","助心行血","通调水液"],scoringPoints:["呼吸","气机","血行","水液"]}),h({id:"zangfu-w03",type:"term-definition",prompt:"名词解释：奇恒之腑",answerOutline:["列脑髓骨脉胆女子胞","形多中空似腑","功能贮藏精气似脏","与一般六腑区别"],scoringPoints:["名单","形态","功能","分类逻辑"]}),h({id:"zangfu-w04",type:"short-answer",prompt:"简述心主血脉与心藏神的基本内容。",answerOutline:["心气推动血行","心主持脉道","神的广义狭义","精气血津液为神的基础","写二者联系"],scoringPoints:["主血","主脉","藏神","物质基础","联系"]}),h({id:"zangfu-w05",type:"short-answer",prompt:"简述肺宣发与肃降的内容。",answerOutline:["宣发呼浊、布散精微津液、宣卫气","肃降吸清、下输津液精微、保持清肃","二者方向相反相成"],scoringPoints:["宣发三点","肃降三点","协调"]}),h({id:"zangfu-w06",type:"short-answer",prompt:"简述脾主运化、升清与统血。",answerOutline:["运化水谷","运化水液","清阳上升与维持位置","脾气固摄血液"],scoringPoints:["水谷","水液","升清","统血"]}),h({id:"zangfu-w07",type:"short-answer",prompt:"简述肾藏精的主要内容。",answerOutline:["先天后天之精相互充养","主生长发育生殖","肾精生髓充骨脑","肾精化肾气与天癸"],scoringPoints:["精的来源","生命阶段","髓骨脑","天癸"]}),h({id:"zangfu-w08",type:"comparison",prompt:"比较五脏、六腑和奇恒之腑。",answerOutline:["分别写共同功能","分别写藏泻满实特点","说明奇恒形似腑用似脏","以胆说明分类角度"],scoringPoints:["五脏","六腑","奇恒","胆的双重性"]}),h({id:"zangfu-w09",type:"comparison",prompt:"比较肺主气与肾纳气。",answerOutline:["肺司呼吸和一身之气","肾摄纳清气","肺为气之主","肾为气之根","写肺肾协同"],scoringPoints:["肺","肾","主与根","协同"]}),h({id:"zangfu-w10",type:"comparison",prompt:"比较脾统血、肝藏血与心主血脉。",answerOutline:["脾气固摄","肝贮藏调节血量","心推动血行主持脉道","三者共同维持血液正常"],scoringPoints:["固摄","调节","推动","协同"]}),h({id:"zangfu-w11",type:"comparison",prompt:"比较脾升清与胃降浊。",answerOutline:["脾升清上输精微","胃降浊下传食糜","一升一降","纳运协调"],scoringPoints:["清","浊","升降","协同"]}),h({id:"zangfu-w12",type:"analysis",prompt:"分析饮食物由摄入到糟粕排出的脏腑协同。",answerOutline:["胃受纳腐熟","脾运化精微并升清","小肠受盛化物泌别清浊","大肠传化糟粕","肝疏泄助脾胃升降"],scoringPoints:["胃","脾","小肠","大肠","肝的协同"]}),h({id:"zangfu-w13",type:"analysis",prompt:"分析水液代谢中的脏腑协同。",answerOutline:["脾运化转输","肺宣肃通调","肾气化主水","三焦疏通水道","膀胱贮排"],scoringPoints:["脾","肺","肾","三焦","膀胱"]}),h({id:"zangfu-w14",type:"analysis",prompt:"用功能链方法分析心、肺、肝、脾在血液运行中的分工。",answerOutline:["心主血脉推动","肺朝百脉助行","肝藏血调节血量","脾统血固摄","气血相互依存"],scoringPoints:["心","肺","肝","脾","关系而非罗列"]})],be=[r({id:"q-tcm-zangfu-13",unitId:n,conceptId:"tcm-zang-fu-distinction",type:"single-choice",prompt:"最能体现五脏共同功能特点的是？",options:["受盛传化水谷","化生和贮藏精气","以通降为唯一功能","只负责排泄浊物"],answer:1,explanation:"五脏以化生和贮藏精气为共同特点；六腑偏于受盛传化。",misconceptionFeedback:{0:"受盛传化是六腑共同特点。",2:"通降主要概括六腑，且“唯一”表述过度。",3:"五脏不是排泄浊物的通道分类。"}}),r({id:"q-tcm-zangfu-14",unitId:n,conceptId:"tcm-five-zang",type:"single-choice",prompt:"题干强调“调畅气机，并由此影响情志、脾胃升降和胆汁排泄”，主要指哪项功能？",options:["心主血脉","肺肃降","肝疏泄","脾统血"],answer:2,explanation:"肝疏泄以调畅气机为核心，进一步影响情志、消化和胆汁排泄。",misconceptionFeedback:{0:"心主血脉重在推动血液和主持脉道。",1:"肺肃降重在向下向内输送清气津液。",3:"脾统血重在固摄血液循脉。"}}),r({id:"q-tcm-zangfu-15",unitId:n,conceptId:"tcm-five-zang",type:"single-choice",prompt:"“把水谷精微上输心肺头目”最直接对应哪项功能？",options:["脾升清","胃降浊","肺宣发","肾纳气"],answer:0,explanation:"脾升清使水谷精微等清阳物质向上输布；胃降浊使食糜浊物下行。",misconceptionFeedback:{1:"胃降浊方向向下，且对象偏食糜浊物。",2:"肺宣发负责接收精微后向上向外布散，不是中焦升清的起点。",3:"肾纳气围绕摄纳肺吸入的清气。"}}),r({id:"q-tcm-zangfu-16",unitId:n,conceptId:"tcm-zangfu-fu-extraordinary",type:"single-choice",prompt:"下列哪一项同时属于六腑和奇恒之腑？",options:["胃","胆","三焦","女子胞"],answer:1,explanation:"胆参与通降、排泄胆汁而属六腑，又贮藏精汁而具有奇恒之腑特点。",misconceptionFeedback:{0:"胃只列六腑，主受纳腐熟。",2:"三焦属六腑，不列奇恒之腑。",3:"女子胞属奇恒之腑，不列六腑。"}}),r({id:"q-tcm-zangfu-17",unitId:n,conceptId:"tcm-zang-fu-distinction",type:"true-false",prompt:"藏象中的“脾”可以与现代解剖学的脾脏作完全一一对应。",answer:!1,explanation:"藏象之脾是涵盖运化、升清、统血及相关征象的传统功能系统，不能机械缩成现代脾脏。",misconceptionFeedback:{true:"同名不等于理论范围相同；应区分功能模型与解剖实体。"}}),r({id:"q-tcm-zangfu-18",unitId:n,conceptId:"tcm-five-zang",type:"true-false",prompt:"肺宣发和肺肃降方向相反，因此两者不能同时存在。",answer:!1,explanation:"宣发向上向外，肃降向下向内，方向相反却相互制约、共同维持肺气出入升降。",misconceptionFeedback:{true:"方向相反不等于互相排斥；藏象强调相反相成。"}}),r({id:"q-tcm-zangfu-19",unitId:n,conceptId:"tcm-zangfu-fu-extraordinary",type:"true-false",prompt:"奇恒之腑形态多中空似腑，但功能特点偏于贮藏精气。",answer:!0,explanation:"这正是奇恒之腑“形似腑、用似脏”的分类要点。",misconceptionFeedback:{false:"不要只凭中空形态归入六腑；奇恒之腑分类重在兼看贮藏功能。"}}),r({id:"q-tcm-zangfu-20",unitId:n,conceptId:"tcm-five-zang",type:"matching",prompt:"将五脏与核心功能配对。",pairs:[{left:"心",right:"主血脉、藏神"},{left:"肺",right:"主气、宣发肃降"},{left:"脾",right:"运化、升清、统血"},{left:"肝",right:"疏泄、藏血"},{left:"肾",right:"藏精、主水、纳气"}],answer:["心=>主血脉、藏神","肺=>主气、宣发肃降","脾=>运化、升清、统血","肝=>疏泄、藏血","肾=>藏精、主水、纳气"],explanation:"先固定五脏各自的两到三条主线，再进入形窍志液和脏腑关系。",misconceptionFeedback:{"":"按“心血神、肺气宣肃、脾运升统、肝疏藏、肾精水气”逐项核对。"}}),r({id:"q-tcm-zangfu-21",unitId:n,conceptId:"tcm-zang-fu-distinction",type:"matching",prompt:"将脏与其表里之腑配对。",pairs:[{left:"心",right:"小肠"},{left:"肺",right:"大肠"},{left:"脾",right:"胃"},{left:"肝",right:"胆"},{left:"肾",right:"膀胱"}],answer:["心=>小肠","肺=>大肠","脾=>胃","肝=>胆","肾=>膀胱"],explanation:"五组基本表里配对固定；另有心包与三焦相表里。",misconceptionFeedback:{"":"按心小肠、肺大肠、脾胃、肝胆、肾膀胱的顺序重新配对。"}}),r({id:"q-tcm-zangfu-22",unitId:n,conceptId:"tcm-five-zang",type:"matching",prompt:"将功能与主导脏配对。",pairs:[{left:"推动血液循脉",right:"心"},{left:"固摄血液不逸脉外",right:"脾"},{left:"贮藏并调节血量",right:"肝"},{left:"朝百脉并助气行血",right:"肺"}],answer:["推动血液循脉=>心","固摄血液不逸脉外=>脾","贮藏并调节血量=>肝","朝百脉并助气行血=>肺"],explanation:"血液正常涉及心推动、脾统摄、肝调藏、肺助行，主导动词各不相同。",misconceptionFeedback:{"":"先圈动词：推动—心，固摄—脾，贮藏调节—肝，朝百脉助行—肺。"}}),r({id:"q-tcm-zangfu-23",unitId:n,conceptId:"tcm-zangfu-coordination",type:"ordering",prompt:"按饮食物传化学习链排列三个腑的主导环节。",items:["胃受纳腐熟","小肠受盛化物、泌别清浊","大肠传化糟粕"],answer:["胃受纳腐熟","小肠受盛化物、泌别清浊","大肠传化糟粕"],explanation:"饮食物先由胃受纳腐熟，下传小肠进一步化物并分清别浊，糟粕再入大肠传化。",misconceptionFeedback:{"":"抓住腑间下传方向：胃→小肠→大肠；脾运化贯穿协同但不改变这三个主导环节。"}}),r({id:"q-tcm-zangfu-24",unitId:n,conceptId:"tcm-organ-relationships",type:"ordering",prompt:"按课程记忆链排列水液代谢的主要环节。",items:["脾运化转输水液","肺宣肃通调、布散下输","肾气化主水","膀胱贮尿排尿"],answer:["脾运化转输水液","肺宣肃通调、布散下输","肾气化主水","膀胱贮尿排尿"],explanation:"记忆链为脾转输—肺布散下输—肾气化—膀胱贮排；实际生理是多向协同，不是僵硬单线。",misconceptionFeedback:{"":"先用四个动词定位：转输、通调、气化、贮排，再按中焦至上焦、下焦的学习框架排列。"}}),r({id:"q-tcm-zangfu-25",unitId:n,conceptId:"tcm-organ-relationships",type:"ordering",prompt:"按“肾精—生殖成熟”理论链排列。",items:["肾精充盛","天癸至","任通冲盛","具备生殖能力"],answer:["肾精充盛","天癸至","任通冲盛","具备生殖能力"],explanation:"教材以肾精充盛为基础，天癸产生，冲任通盛，生殖功能逐渐成熟。",misconceptionFeedback:{"":"先找物质基础肾精，再到成熟条件天癸和冲任，最后才是生殖功能结果。"}}),r({id:"q-tcm-zangfu-26",unitId:n,conceptId:"tcm-organ-relationships",type:"scenario",prompt:"一道理论题强调“呼吸节律由肺主持，但吸入清气还要被摄纳，使呼吸有根”。后半句主要说明什么？",options:["脾升清","肾纳气","肝疏泄","心藏神"],answer:1,explanation:"肺司呼吸，肾纳气；“摄纳清气、呼吸有根”是肾纳气的判别词。",misconceptionFeedback:{0:"脾升清上输水谷精微，不负责摄纳清气。",2:"肝疏泄调畅气机，但不是此题摄纳环节。",3:"心藏神统摄精神意识活动。"}}),r({id:"q-tcm-zangfu-27",unitId:n,conceptId:"tcm-organ-relationships",type:"scenario",prompt:"题干要求解释“血液为什么既能运行又不逸出脉外”，最完整的藏象组合是？",options:["心主血脉与脾统血","肝疏泄与肺宣发","肾纳气与胃受纳","胆主决断与小肠化物"],answer:0,explanation:"心气推动血液循脉运行，脾气固摄血液不逸出脉外；若再展开可补肝藏血和肺助行。",misconceptionFeedback:{1:"肝疏泄与肺宣发可影响气机，但没有直接回答推动血行与固摄边界。",2:"肾纳气和胃受纳不属于血液运行固摄主线。",3:"胆与小肠的功能不解释血行和统摄。"}}),r({id:"q-tcm-zangfu-28",unitId:n,conceptId:"tcm-zangfu-coordination",type:"scenario",prompt:"分析饮食精微从摄入、化生到输布全身，哪种答题方式最好？",options:["只写胃能消化全部食物","写胃受纳、脾运化升清，并联系小肠化物和肝疏泄助升降","只背脾开窍于口","把脾等同现代脾脏"],answer:1,explanation:"完整功能链需写胃受纳腐熟、脾化生转输和升清，并按题干补小肠及肝的协同。",misconceptionFeedback:{0:"胃主受纳腐熟，但不能独自完成精微化生和全身输布。",2:"官窍对应不是这道过程题的主线。",3:"藏象功能系统不能机械等同现代器官。"}}),r({id:"q-tcm-zangfu-29",unitId:n,conceptId:"tcm-organ-relationships",type:"scenario",prompt:"理论材料先写“脾转输水液不足”，又要求解释为何肺的布散与肾的气化会受到影响。应采用哪种分析框架？",options:["单脏孤立框架","脾肺肾水液协同框架","只用五色情志对应","直接给个人利水方案"],answer:1,explanation:"水液代谢由脾转输、肺通调、肾气化并借三焦膀胱共同完成，适合用协同链解释。",misconceptionFeedback:{0:"题干已明确跨脏影响，孤立分析会漏掉功能链。",2:"五色或情志对应不能解释水液转输与气化。",3:"课程题只分析理论关系，不提供个人治疗或处方。"}}),r({id:"q-tcm-zangfu-30",unitId:n,conceptId:"tcm-zangfu-fu-extraordinary",type:"scenario",prompt:"题目同时问“胆为何属六腑，又为何列奇恒之腑”，正确回答是？",options:["分类错误，胆只能属于一类","中空且参与通降似腑，贮藏精汁又似脏","胆只因位置特殊而双重归类","胆能传化所有水谷所以属奇恒"],answer:1,explanation:"胆在通降、排泄胆汁和表里关系上具六腑特点，在贮藏清净精汁上具奇恒之腑特点。",misconceptionFeedback:{0:"双重归类来自比较角度不同，并不矛盾。",2:"关键是功能与形态结合，不是单纯位置。",3:"奇恒之腑偏贮藏精气，且胆不传化全部水谷。"}})],xe={chapter:{unitId:n,title:"藏象学说与脏腑关系",introduction:"本章先建立藏象的功能模型和三类脏腑分类，再逐一掌握心、肺、脾、肝、肾与六腑、奇恒之腑，随后用形窍志液华时整理外在联系，最后沿气血、水液、饮食和呼吸过程训练多脏协同推理。",sections:ve,confusions:he,memoryItems:we,writtenPrompts:Ie,summary:["藏象连接内在脏腑功能与外在征象，是传统功能系统，不与现代器官机械等同。","五脏偏贮藏精气，六腑偏受盛传化，奇恒之腑形似腑而功能似脏。","心主血脉藏神；肺主气宣肃；脾运化升清统血；肝疏泄藏血；肾藏精主水纳气。","胃、小肠、大肠组成饮食物传化主链，胆、膀胱和三焦分别承担精汁、尿液与诸气水道功能。","脑髓骨脉胆女子胞以贮藏精气为共同特点，并与肾精、心神、肝血和冲任等相联系。","外在对应必须回到主功能解释，不能由单一形窍志液或季节线索直接诊断。","心肺围绕宗气和气血协同，肝脾围绕气机、运化和血液协同。","水液代谢抓住脾转输、肺通调、肾气化、三焦通道和膀胱贮排。","复杂题先定物质或过程，再用箭头写主导、推动、转化、通道、调节和归宿。"]},questions:be},K=[...P],a={qiBlood:["tcm-qi-functions","tcm-blood-fluid","tcm-qi-blood-relations","tcm-qi-categories","tcm-fluid-metabolism"],meridians:["tcm-meridian-system","tcm-twelve-meridians","tcm-meridian-functions","tcm-meridian-branches","tcm-extraordinary-vessels"],constitution:["tcm-constitution-concept","tcm-constitution-factors","tcm-constitution-application","tcm-constitution-adjustability","tcm-constitution-pattern-impact"],etiology:["tcm-six-excesses","tcm-emotions-diet","tcm-constitution-pathogen","tcm-pathogen-characteristics","tcm-onset-factors"],pathogenesis:["tcm-healthy-pathogenic","tcm-yin-yang-disorder","tcm-prevention-treatment","tcm-pathogenesis-levels","tcm-principle-method-levels"]},s=(e,i,o)=>({title:e,focus:i,conceptId:o}),t=(e,i,o,l)=>({left:e,right:i,leftKey:o,rightKey:l}),ze=[{unitId:"tcmf-qi-blood",slug:"qi-blood",questionSlug:"qiblood",title:"气血津液：生成、运行、功能与关系",introduction:"本章以“来源—生成—运行—功能—关系—失常”为主线，把气、血、津液由孤立名词重组为可以解释生命活动的动态网络。学习时先抓动词，再辨物质基础和脏腑协同。",topics:[s("气的概念、来源与生成","人体之气由先天之精所化之气、水谷精气和自然界清气共同构成；肾为生气之根，脾胃为生气之源，肺为生气之主。三者不是并列口号，而是原料、加工与会合的协同关系。",a.qiBlood[0]),s("气的运动与气化","升、降、出、入是气的基本运动形式，气机是运动状态，气化是运动引起的精微化生、形态转化和代谢变化。辨题时应判断题干问的是方向是否协调，还是变化过程能否完成。",a.qiBlood[0]),s("气的五大作用","推动、温煦、防御、固摄、气化彼此联系但判别动词不同：促进行动属推动，维持温度属温煦，护表抗邪属防御，控制不外泄属固摄，完成物质转化属气化。",a.qiBlood[0]),s("元气","元气根于肾中精气，赖脾胃水谷精气不断培育，经三焦通达全身，推动和调节生长发育、生殖及脏腑功能。元气并非只在下焦，也不能等同于宗气或肾气。",a.qiBlood[3]),s("宗气","宗气由水谷精气与自然界清气在胸中结合而成，积于胸中，走息道以司呼吸，贯心脉以行气血，并与语言、声音和视听活动相关。胸中、肺呼吸、心血脉是识别宗气的关键词。",a.qiBlood[3]),s("营气与卫气","营气行于脉中、化生血液并营养全身，性质精纯；卫气行于脉外、温养肌肤腠理、护卫肌表并调节汗孔，性质慓疾滑利。二者同源于水谷精微，运行部位和功能侧重不同。",a.qiBlood[3]),s("血的生成、运行与功能","血以水谷精微为主要物质基础，营气和津液参与化生，肾精亦可化血；心主血脉、肺助心行血、脾统血、肝藏血并调节血量。血的核心功能是濡养和化神。",a.qiBlood[1]),s("津液的生成、输布与排泄","津液源于饮食水谷，经脾胃运化而生成；脾转输、肺宣发肃降和通调水道、肾蒸腾气化、肝疏泄、三焦通行共同完成输布，汗、尿、呼气和粪便携水是主要排泄途径。",a.qiBlood[4]),s("津与液的区别联系","津较清稀、流动性大，布散于皮肤肌肉孔窍并渗入血脉；液较稠厚、流动性小，灌注骨节、脏腑、脑髓。二者同源于水谷、可以转化，常合称津液但考试需要辨别侧重。",a.qiBlood[1]),s("气与血的关系","气能生血、行血、摄血，血能载气、养气。气为血之帅强调气对血生成、运行和固摄的作用；血为气之母强调血为气提供依附和濡养，严重失血可见气随血脱。",a.qiBlood[2]),s("气与津液的关系","气能生津、行津、摄津，津能载气并为气的功能活动提供物质条件。气虚可致生化不足、输布无力或固摄失常；大量津液丢失又可导致气随津脱。",a.qiBlood[2]),s("血与津液及三者综合","血与津液同源于水谷精微并可相互渗化，称为津血同源；夺血者无汗、夺汗者无血提示治疗时要顾护共同物质基础。综合题应依次判断何者先伤、关系方向和最终病理结果。",a.qiBlood[2])],contrasts:[t("气机","气化","气的升降出入及协调状态","气的运动所引起的物质与功能变化"),t("推动","气化","使活动发生和前进","使精微、津液等发生转化"),t("固摄","防御","控制血津精等不无故外泄","护卫肌表、抵御外邪"),t("元气","宗气","根于肾、通行三焦、推动全身","聚于胸中、关联呼吸与心脉"),t("营气","卫气","行脉中、营养化血","行脉外、护表温养司汗孔"),t("宗气","卫气","胸中会合并贯心肺","肌表护卫并调节腠理"),t("血","津液","循脉运行、濡养化神","布散灌注、滋润濡养"),t("津","液","清稀、流动大、布散肌表孔窍","稠厚、流动小、灌注骨节脑髓"),t("气生血","血载气","气参与血液化生","血是气运行依附与濡养基础"),t("气行血","气摄血","推动血液循脉运行","控制血液不逸出脉外"),t("气虚","气滞","功能不足、推动固摄无力","运行不畅、局部胀闷疼痛"),t("气不摄血","气随血脱","气虚不能固摄而出血","大量失血后气失所依而暴脱"),t("津伤","脱液","津液不足相对较轻","液耗严重并影响脏腑骨髓"),t("气随津脱","津停气阻","大量亡津导致气脱","津停为湿痰饮并阻碍气机"),t("脾运化水液","肺通调水道","生成转输水液精微","宣发肃降并调节水液通路"),t("肾主水","三焦通行水液","蒸腾气化并主宰开合","作为水液升降出入的通道"),t("营气","血","水谷精微所化之气、行脉中","红色液态物质、循脉濡养"),t("津血同源","气血同源","同源水谷并相互渗化","精气可互化但论述重点不同")],memoryCount:30,newQuestionCount:16,writtenCount:12},{unitId:"tcmf-meridians",slug:"meridians",questionSlug:"meridians",title:"经络：系统构成、循行规律与应用",introduction:"本章不要求死背一张孤立路线图，而是用层级、方向、交接、属络、流注五个坐标掌握经络系统，再理解经络沟通、运输、感应传导和调节功能。",topics:[s("经络系统的组成","经络系统由经脉和络脉为主体，并联系十二经筋、十二皮部；经脉包括十二经脉、奇经八脉及十二经别，络脉包括十五络脉及孙络浮络。先分主干与分支，再定位附属结构。",a.meridians[0]),s("十二经脉的命名","十二经脉名称由手足、阴阳、脏腑三部分组成。手足指循行分布，阴阳含太阴少阴厥阴与阳明太阳少阳，末尾脏腑提示属络核心；名称本身已压缩多层信息。",a.meridians[1]),s("十二经脉走向与交接","手三阴从胸走手，手三阳从手走头，足三阳从头走足，足三阴从足走腹胸；阴阳相表里的经脉在四肢末端交接，同名阳经在头面交接，手足阴经在胸中交接。",a.meridians[1]),s("十二经脉表里与属络","阴经属脏络腑，阳经属腑络脏；肺大肠、脾胃、心小肠、肾膀胱、心包三焦、肝胆构成表里对。属是直接隶属，络是联络相表里的另一脏腑。",a.meridians[1]),s("十二经脉流注次序","流注从手太阴肺经起，依次为大肠、胃、脾、心、小肠、膀胱、肾、心包、三焦、胆、肝，再复注于肺。应把脏腑次序与手足阴阳交替规律一起记忆。",a.meridians[1]),s("奇经八脉","督、任、冲、带、阴跷、阳跷、阴维、阳维不直接隶属于脏腑且无固定表里配合，具有统率、联络和调节十二经气血作用。督主一身之阳，任主一身之阴，冲为十二经脉之海，带脉横行约束纵行诸经。",a.meridians[4]),s("经别、络脉、经筋与皮部","十二经别从十二经脉别出、深入体腔并加强表里联系；十五络脉加强表里和躯干部联络；经筋约束骨骼、主司关节运动；皮部是经络功能在体表的反映区域。",a.meridians[3]),s("经络的生理功能","经络沟通表里上下、联系脏腑器官，运行气血和濡养全身，感应传导信息，并调节功能平衡。功能题应从“联系—运输—传导—调节”四类动词作答。",a.meridians[2]),s("经络与病理诊断治疗","病邪可沿经络传变，脏腑病变也可在相应循行部位出现反应；循经取穴和药物归经属于理论应用。经络辨证须结合症状、部位和脏腑功能，不可只凭一个疼痛点下结论。",a.meridians[2]),s("经络学习的空间整合","把每条经脉放进正面、背面、侧面和内外侧的三维人体框架，先掌握起止与关键转折，再补局部细节。路线、交接和属络是三个不同问题，答题时不可混写。",a.meridians[0])],contrasts:[t("经脉","络脉","主干、较深、纵行为主","分支、较浅、网络联络"),t("经络","血管","功能联系网络的理论概念","现代解剖可见的管道结构"),t("十二经脉","奇经八脉","有脏腑属络和表里配对","调节统率、无固定表里配对"),t("十二经别","十五络脉","深入体腔并加强表里联系","较浅分支并加强局部联络"),t("十二经筋","十二经脉","联缀百骸、主关节运动","运行气血并联系脏腑"),t("十二皮部","浮络","经脉功能在体表的区域","络脉中浮行浅表者"),t("手三阴","手三阳","从胸走手","从手走头"),t("足三阴","足三阳","从足走腹胸","从头走足"),t("表里配属","脏腑属络","两条经脉成对关系","一条经脉与脏腑的直接或间接联系"),t("流注次序","循行方向","十二经气血衔接顺序","单条经脉总体走向"),t("督脉","任脉","总督诸阳经","总任诸阴经"),t("冲脉","带脉","十二经脉之海并冲要上下","横行束带并约束纵经"),t("跷脉","维脉","主肢体运动与目睑开合侧重","维系阴经或阳经网络"),t("属","络","直接隶属本脏腑","联络相表里的脏腑")],memoryCount:26,newQuestionCount:12,writtenCount:10},{unitId:"tcmf-constitution",slug:"constitution",questionSlug:"constitution",title:"体质：形成、分类与辨证应用边界",introduction:"体质是相对稳定而又可调的个体生命特征。本章把形成因素、基本特征、发病倾向、证候转归和调养边界连成一条因果链，避免把体质当成固定标签。",topics:[s("体质概念与基本特征","体质是在先天禀赋和后天获得基础上形成的形态结构、生理功能和心理状态方面综合且相对稳定的固有特质，具有个体差异、群类趋同、相对稳定和动态可变等特点。",a.constitution[0]),s("体质形成的先后天因素","先天禀赋决定体质基础，年龄、性别、饮食、劳逸、情志、疾病与治疗、地理气候及社会环境持续塑造后天状态。分析时要区分基础条件、长期影响和当前诱因。",a.constitution[1]),s("年龄性别地域与体质","生长壮老使精气盛衰改变，性别生理特点造成阶段差异，地域气候与生活方式形成适应倾向。这些是概率性影响而非决定论，不能据单一人口特征直接判断体质。",a.constitution[1]),s("饮食情志劳逸与体质","饮食偏嗜可影响脾胃运化和痰湿燥热倾向，长期情志失调影响气机，过劳过逸损伤或遏制功能。后天调护之所以有效，正因为这些因素可被持续调整。",a.constitution[3]),s("体质分类与识别方法","体质分类是将复杂个体特征归纳为便于观察和干预的模式，需要综合形体、面色、声音、性格、寒热喜恶、二便、舌脉和既往反应，不能凭网络问卷单项自诊。",a.constitution[0]),s("体质与发病、证候和转归","体质影响对某类病邪的易感性、发病后的证候性质及病程转归；同一病邪在不同体质可呈不同证候，同一体质也并非必然发生某病。体质提供背景，证候反映当下病机。",a.constitution[4]),s("体质可调性与应用边界","体质相对稳定但可通过饮食、运动、作息、情志和医疗干预渐进改善。调养应个体化、连续评估，并与疾病诊断治疗分开；体质理论不能替代必要的现代医学检查。",a.constitution[2])],contrasts:[t("体质","证候","长期相对稳定的个体背景","疾病某阶段的病理概括"),t("体质","疾病","易感与反应倾向","已有明确病理过程"),t("先天禀赋","后天调养","形成基础与潜在范围","持续塑造和可干预因素"),t("相对稳定","动态可变","短期不轻易改变","长期随环境和调护调整"),t("个体差异","群类趋同","每个人有独特组合","可归入若干相似类型"),t("体质分类","固定标签","帮助观察干预的模型","把复杂个体永久定型的误用"),t("偏颇体质","病理证候","未必已经患病","反映当前邪正与病机"),t("体质调养","疾病治疗","长期改善易感背景","针对当前疾病和证候"),t("地域影响","季节影响","长期生活环境塑形","短期时令变化触发"),t("心理特征","精神疾病","体质表现的一个维度","需专业诊断的疾病状态")],memoryCount:15,newQuestionCount:4,writtenCount:8},{unitId:"tcmf-etiology",slug:"etiology",questionSlug:"etiology",title:"病因：外感、内伤与发病条件",introduction:"病因学习不能停在名词罗列。本章用来源、性质、致病特点、易伤部位、常见表现和体质条件六个维度辨析病因，并训练由表现反推病因的辨证求因方法。",topics:[s("病因分类与辨证求因","病因可概括为外感、内伤和其他致病因素，痰饮瘀血等既是病理产物又能成为继发病因。辨证求因是根据症状体征和病机推求原因，不等于现代医学的单一病原学追踪。",a.etiology[4]),s("六淫的共同特点","六淫由风寒暑湿燥火六气异常转化，具有外感性、季节性、地域性、相兼性和转化性。六气本为正常气候，超过适应能力或人体正气不足时才成为致病之淫。",a.etiology[0]),s("风邪","风为阳邪、轻扬开泄、善行数变、主动，并为百病之长。其病位多在上部肌表，症状游走、变化快、可见动摇；风常兼寒热湿燥，辨题需同时识别复合病因。",a.etiology[3]),s("寒邪","寒为阴邪，易伤阳气，寒性凝滞、收引。寒邪可见恶寒、疼痛、气血运行不畅和筋脉拘急；外寒与内寒来源不同，二者可互相影响但不能简单等同。",a.etiology[3]),s("暑邪","暑为夏季火热之邪，属阳邪，炎热升散，易伤津耗气，多挟湿。高热、口渴、汗多与气短乏力可提示伤津耗气，身重困倦和胸闷则提示暑湿相合。",a.etiology[3]),s("湿邪","湿为阴邪，重浊、黏滞、趋下，易阻遏气机并损伤阳气，尤易困脾。病程缠绵、分泌物黏腻、头身困重、下部症状常见；外湿与内湿可相互影响。",a.etiology[3]),s("燥邪","燥性干涩，易伤津液，且肺为娇脏、喜润恶燥，故燥邪尤易伤肺。鼻咽口唇皮肤干燥、干咳少痰可作线索；初秋温燥与深秋凉燥还需结合寒热表现。",a.etiology[3]),s("火热邪","火热为阳邪，燔灼趋上，易扰心神、伤津耗气、生风动血、易致疮痈。火与热程度可有差异，温热病邪可由外入，五志过极和脏腑功能失调也可化火。",a.etiology[3]),s("疫疠","疫疠之气具有传染性强、易于流行、发病急骤和病情危重等特点，可经口鼻等途径侵入。是否发病与疫气性质、环境和人体正气相关，防控需重视公共卫生措施。",a.etiology[0]),s("七情内伤","喜怒忧思悲恐惊在正常范围是生理情志，突然、强烈或持久并超过调节能力才成为病因。七情直接影响脏腑和气机，怒则气上、喜则气缓、悲则气消、恐则气下、惊则气乱、思则气结。",a.etiology[1]),s("饮食劳逸与病理产物","饥饱无度、饮食不洁和偏嗜可伤脾胃或形成寒热痰湿；过劳耗气伤形，过逸使气血运行不畅。痰饮、瘀血、结石既由功能失常产生，又可阻滞脏腑经络成为新病因。",a.etiology[1]),s("正邪、体质与发病","邪气是发病重要条件，正气强弱是是否发病及病势转归的内在基础，体质决定易感和反应倾向。发病不是“有邪必病”，而是邪正相搏、环境暴露和调护共同作用的结果。",a.etiology[2])],contrasts:[t("六气","六淫","正常自然气候变化","异常气候或人体不能适应的致病因素"),t("外感病因","内伤病因","由外而入，多犯肌表口鼻","情志饮食劳逸从内损伤"),t("风邪","寒邪","轻扬开泄、善行数变","凝滞收引、易伤阳气"),t("风寒","风热","恶寒重、无汗、清稀倾向","发热重、口渴、红肿倾向"),t("寒邪","湿邪","凝滞收引、疼痛拘急","重浊黏滞、困重缠绵"),t("暑邪","火热邪","严格季节性且多挟湿","无严格季节限制并易动血生风"),t("湿邪","燥邪","黏滞重浊、阻遏气机","干涩伤津、易伤肺"),t("外湿","内湿","环境湿邪由外侵入","脾运失常水湿内生"),t("温燥","凉燥","偏热、口渴咽红","偏凉、恶寒无汗"),t("实火","虚火","邪盛火炽、症状强烈","阴虚失制、虚热内扰"),t("火邪","热邪","程度更甚且可内生","热象概念较广"),t("疫疠","一般六淫","传染流行和急重突出","季节地域相兼转化突出"),t("正常情志","七情内伤","有节有度且能恢复","过激持久并损伤脏腑气机"),t("怒则气上","恐则气下","气机上逆倾向","气机下陷或不固倾向"),t("饮食不节","饮食不洁","数量与时间失常","摄入污染变质之物"),t("过劳","过逸","耗气伤血或损形","气机不畅、脾胃呆滞"),t("痰饮","瘀血","水液代谢障碍的产物","血行不畅或离经之血停积"),t("病因","诱因","参与疾病发生的根本或主要因素","促使潜在病变发作加重的条件")],memoryCount:30,newQuestionCount:16,writtenCount:12},{unitId:"tcmf-pathogenesis",slug:"pathogenesis",questionSlug:"path",title:"病机与防治原则：从失衡到推理",introduction:"病机回答“疾病如何发生、发展和变化”。本章由邪正盛衰、阴阳失调、气血津液失常和内生五邪进入标本缓急与治则，使学生能从现象回到机制，再由机制推出治疗方向。",topics:[s("病机概念与分析层次","病机是疾病发生、发展和变化的机制，可从基本病机、系统病机、具体证候病机等层次分析。答题要包含病因作用、病位、邪正变化、功能物质失调和表现之间的因果链。",a.pathogenesis[3]),s("邪正盛衰","正气具有抗邪、调节和修复作用，邪气导致损伤和紊乱。邪正盛衰决定虚实及病势，但邪盛不必正气完全不虚，正虚也可兼有实邪，临床常见虚实夹杂。",a.pathogenesis[0]),s("虚实变化","实主要指邪气盛，虚主要指正气不足；真实假虚、真虚假实提示现象与本质可能不一致。虚实转化和夹杂需结合病程、体质、症状强弱、舌脉及治疗反应综合判断。",a.pathogenesis[0]),s("阴阳偏盛","阴或阳一方病理性亢盛，属于邪气有余的实证。阳盛则热并可耗伤阴液，阴盛则寒并可损伤阳气；偏盛日久造成对方受损，可由实转虚或虚实夹杂。",a.pathogenesis[1]),s("阴阳偏衰","阴或阳一方不足，属于正气亏虚。阳虚不能制阴而虚寒，阴虚不能制阳而虚热；“阳虚则寒”与“阴盛则寒”、“阴虚则热”与“阳盛则热”必须从盛衰和虚实辨别。",a.pathogenesis[1]),s("阴阳互损","阴阳互根互用，一方虚损到一定程度可累及另一方，形成阴损及阳或阳损及阴，最终可能阴阳两虚。判断顺序要先找原发亏损，再识别继发方向。",a.pathogenesis[1]),s("阴阳格拒与亡失","阴阳格拒是寒热本质与外在假象相反的复杂病机，包括阴盛格阳和阳盛格阴；亡阴亡阳是阴液或阳气突然大量脱失的危重状态，可相互影响并发展为阴阳离决。",a.pathogenesis[1]),s("气的失常","气虚是功能不足，气机失调包括气滞、气逆、气陷和气闭、气脱。气滞重在运行不畅，气逆重在升降反常向上，气陷是升举无力下陷，闭与脱分别是闭阻不通和外脱不固。",a.pathogenesis[3]),s("血的失常","血虚是濡养不足，血瘀是运行不畅或停积，血热使血行加速并易迫血妄行，出血是血离经脉。血瘀可由气滞、气虚、寒凝、热灼、外伤或出血后离经之血形成。",a.pathogenesis[3]),s("津液代谢失常","津液不足包括伤津和脱液；输布排泄障碍可形成湿、痰、饮、水等病理产物。分析时按生成不足、输布不利、排泄障碍和耗伤过多四个环节定位。",a.pathogenesis[3]),s("气血津液关系失常","气滞可致血瘀和水停，气虚可致血少、血行无力及津液输布固摄异常；血瘀可阻气，失血或亡津可使气失依附而脱。综合题要写清起点、作用方向与后果。",a.pathogenesis[3]),s("内生五邪","内风、内寒、内湿、内燥、内火是脏腑阴阳气血津液失调所生的病理状态，虽借用外邪名称，却不等于外感六淫。肝阳化风、脾虚生湿、津亏生燥等要落实到内在病机。",a.pathogenesis[3]),s("标本缓急与病势转归","本可指病因、基础病机或先病，标可指症状、继发病变或后病；急则治其标、缓则治其本、标本兼治需结合危急程度和因果主次。正复邪退则向愈，邪盛正衰则恶化。",a.pathogenesis[4]),s("预防、治则与治法层次","未病先防、既病防变和愈后防复构成预防体系。治则是治疗疾病的总原则，治法是在治则指导下针对具体证候的方法；正治反治、治标治本、扶正祛邪、调整阴阳和三因制宜属于高频框架。",a.pathogenesis[2])],contrasts:[t("病因","病机","导致疾病的原因条件","疾病发生发展变化的机制"),t("基本病机","具体证候病机","共性的失衡规律","特定证候的因果链"),t("邪盛","正虚","病邪亢盛偏实","抗病调节能力不足偏虚"),t("实证","虚证","邪气盛为主要矛盾","正气不足为主要矛盾"),t("真实假虚","真虚假实","本质实而外见不足假象","本质虚而外见壅盛假象"),t("阳盛则热","阴虚则热","阳邪偏盛的实热","阴液不足的虚热"),t("阴盛则寒","阳虚则寒","阴邪偏盛的实寒","阳气不足的虚寒"),t("阴损及阳","阳损及阴","先阴虚后累及阳","先阳虚后累及阴"),t("阴盛格阳","阳盛格阴","真寒假热","真热假寒"),t("亡阴","亡阳","阴液骤失、虚热躁扰倾向","阳气暴脱、虚寒衰微倾向"),t("气虚","气滞","气的功能不足","气的运行不畅"),t("气逆","气陷","当降不降或上升太过","升举无力而下陷"),t("气闭","气脱","闭阻不通的实性危候","外脱不固的虚性危候"),t("血虚","血瘀","血量或濡养不足","血行不畅或停积"),t("血热","出血","热入血分的病机","血离经脉的结果表现"),t("伤津","脱液","津液轻度耗损","津液严重亏耗"),t("痰","饮","较稠浊、病位广泛","较清稀、常停聚腔隙"),t("内生五邪","外感六淫","内部功能失调所生","自然邪气由外侵入"),t("治则","治法","治疗的总原则","原则指导下的具体方法"),t("正治","反治","逆其证候表象而治","顺从假象但针对本质而治")],memoryCount:36,newQuestionCount:18,writtenCount:15}],ke=(e,i,o)=>{const l=e.topics[(o+e.topics.length-1)%e.topics.length].title,c=e.topics[(o+1)%e.topics.length].title;return{id:`tcm-rem-${e.slug}-section-${o+1}`,unitId:e.unitId,title:i.title,order:o+1,depth:["foundation","understanding","exam"][o%3],estimatedMinutes:18+o%4*4,overview:`${i.title}是本单元第${o+1}个关键节点。${i.focus}本节不只要求背诵结论，还要能说出判断依据、关系方向和适用边界。`,paragraphs:[`学习“${i.title}”时，先建立六格框架：概念是什么、物质或功能基础来自哪里、由哪些脏腑经络共同参与、正常状态怎样运行、失常后出现什么结果、它与相邻概念怎样区分。${i.focus}把这段信息压缩成“主语—关键动词—对象—结果”，再反向展开成完整论述。例如遇到名词解释，先给定义和范围；遇到简答题，按生成、运行、功能、关系分层；遇到案例题，先从题干动词定位机制，不能仅凭一个症状机械套用。第${o+1}节尤其要注意，理论中的功能联系是对生命现象的系统概括，不应与某个现代解剖结构或单一实验指标直接画等号。`,`把“${i.title}”放进全章网络可以发现，它承接“${l}”，并为“${c}”提供推理条件。复习时用三遍法：第一遍闭卷写关键词，第二遍给每个关键词补一句因果解释，第三遍用一个正例和一个反例检查边界。若只能背出结论而说不出“为什么”，说明仍停留在识记层；若能比较相近概念却不能用于新题，说明还需练习从表现到病机的逆向推理。考试作答应先写教材化核心语句，再用箭头标明方向，最后补充协同条件和不能绝对化之处，这样既完整又不混乱。`,`本节的高分表达围绕“${i.focus}”展开。选择题常以偷换主语、颠倒方向、把主要功能改成唯一功能来设错项；判断题常在“都、必然、仅仅、完全”等绝对词上设陷阱；主观题则要求把散点组织成层级。建议把本节做成一张A5卡：正面写核心定义和三条主线，背面写两个易混点、一条关系链及一道自拟情境。当天完成闭卷复述，次日重画关系，三日后用题目检验，七日后只复习仍会卡住的环节。`],examples:[{title:`${i.title}的推理示例`,explanation:`题目出现与“${i.title}”相关的表现时，先提取关键动词，再依据“${i.focus}”确定主要机制；随后检查是否还存在体质、脏腑协同或邪正条件，最后排除只抓表面词语的选项。`}],relationships:[{from:l,relation:"提供前置理解",to:i.title},{from:i.title,relation:"支持后续推理",to:c}],pitfalls:[`不要把“${i.title}”背成孤立口号；必须同时记住对象、方向和条件。`,"不要把相关性写成唯一因果，也不要用现代结构名称直接替换中医理论概念。"],selfChecks:[`不用看资料，能否用六十秒说清“${i.title}”的定义、两条核心机制和一个边界？`,`能否说明“${i.title}”与“${c}”的联系，并举出一个容易误判的题干？`],sourceIds:K,verifiedAt:u}},Se=(e,i,o)=>({id:`tcm-rem-${e.slug}-confusion-${o+1}`,unitId:e.unitId,title:`${i.left}与${i.right}`,items:[i.left,i.right],dimensions:[{label:"核心定位",values:{[i.left]:i.leftKey,[i.right]:i.rightKey}},{label:"答题抓手",values:{[i.left]:`先找“${i.leftKey}”对应的主语和动词`,[i.right]:`先找“${i.rightKey}”对应的主语和动词`}},{label:"避免误判",values:{[i.left]:`不能仅因与${i.right}有关便将二者等同`,[i.right]:`需说明与${i.left}的联系及方向差异`}}],decisionRule:`先判断题干强调的是“${i.leftKey}”还是“${i.rightKey}”，再核对作用对象、方向和虚实条件。`,commonTrap:`只看到${i.left}与${i.right}经常同时出现，就忽略二者在层级、方向或作用对象上的差异。`,example:`若题干明确强调“${i.leftKey}”，首选${i.left}；若强调“${i.rightKey}”，则应选${i.right}，最后再检查是否为二者协同。`,sourceIds:K,verifiedAt:u}),$e=(e,i)=>Array.from({length:e.memoryCount},(o,l)=>{const c=e.topics[l%e.topics.length],g=Math.floor(l/e.topics.length),v=[`写出“${c.title}”的核心定位。`,`怎样用判断词识别“${c.title}”？`,`“${c.title}”最常见的失分点是什么？`],w=[c.focus,`抓住主语、作用动词、对象和结果，再与相邻概念比较；本节关键依据是：${c.focus}`,`只背名词而遗漏关系方向和适用条件。规范回答应先给核心结论，再写：${c.focus}`];return{id:`tcm-rem-${e.slug}-memory-${l+1}`,unitId:e.unitId,priority:["must-recite","must-understand","recognize"][l%3],prompt:v[g%v.length],answer:w[g%w.length],mnemonic:`先定${c.title.slice(0,4)}，再找动词、方向、条件。`,relatedSectionId:i[l%i.length].id}}),_=["term-definition","short-answer","comparison","analysis"],qe=e=>Array.from({length:e.writtenCount},(i,o)=>{const l=e.topics[o%e.topics.length],c=e.topics[(o+1)%e.topics.length],g=_[o%_.length],v=g==="term-definition"?`名词解释：${l.title}。`:g==="short-answer"?`简述${l.title}的核心内容及学习时必须掌握的关系。`:g==="comparison"?`比较${l.title}与${c.title}的定位、联系和区别。`:`某题同时出现${l.title}与${c.title}的线索，请写出从现象到机制的完整分析路径。`;return{id:`tcm-rem-${e.slug}-written-${o+1}`,unitId:e.unitId,type:g,prompt:v,answerOutline:[`先准确界定${l.title}，核心依据为：${l.focus}`,"再从来源或基础、运行或功能、关系方向三个层次展开。",`联系${c.title}，说明协同条件，同时指出二者不可简单等同。`],scoringPoints:["概念准确","层次完整","关系方向正确","有边界意识"],sourceIds:K,verifiedAt:u}}),E=["single-choice","true-false","matching","ordering","scenario"],Ce=(e,i)=>{const o=e.topics[i%e.topics.length],l=e.topics[(i+1)%e.topics.length],c=E[i%E.length],g={id:`q-tcm-${e.questionSlug}-${i+13}`,unitId:e.unitId,conceptId:o.conceptId,type:c,explanation:`本题核心是${o.title}：${o.focus}作答时还应排除把相关关系说成唯一关系、把方向颠倒或忽略条件的选项。`,misconceptionFeedback:{"":`回到“${o.title}”小节，先圈出主语、动词、对象与方向，再重新作答。`,1:`这个选项混入了${l.title}的表述，未能准确对应${o.title}。`}};if(c==="true-false")return r({...g,prompt:`判断：学习${o.title}时，应同时掌握其作用对象、关系方向和适用条件，不能把相关性绝对化。`,answer:!0});if(c==="matching")return r({...g,prompt:"将本章相邻知识点与核心定位配对。",pairs:[{left:o.title,right:o.focus},{left:l.title,right:l.focus}],answer:[`${o.title}>${o.focus}`,`${l.title}>${l.focus}`]});if(c==="ordering"){const v=["界定概念与范围","提取主语和关键动词","判断关系方向与条件","用相邻概念排除干扰"];return r({...g,prompt:`排列分析“${o.title}”题目的规范步骤。`,items:v,answer:v})}return r({...g,type:c,prompt:c==="scenario"?`案例题要求解释与“${o.title}”有关的机制。下列哪种作答方式最完整？`:`关于“${o.title}”，下列哪项最符合本章的规范理解？`,options:[o.focus,l.focus,`只需记住${o.title}名称，不必考虑方向和条件`,`${o.title}可以完全替代本章其他概念`],answer:0})},Me=e=>{const i=e.topics.map((o,l)=>ke(e,o,l));return{chapter:{unitId:e.unitId,title:e.title,introduction:e.introduction,sections:i,confusions:e.contrasts.map((o,l)=>Se(e,o,l)),memoryItems:$e(e,i),writtenPrompts:qe(e),summary:[`用“定义—来源—运动—功能—关系—失常”复述${e.title}。`,"选择题先抓主语与动词，主观题先列层级再补关系方向。","看到绝对词先核查适用条件，看到相似词先进入易混辨析。","完成当天、次日、三日、七日四轮主动回忆，不以阅读次数代替掌握。","能闭卷讲解、完成变式题并纠正错误，才算真正完成本章。"]},questions:Array.from({length:e.newQuestionCount},(o,l)=>Ce(e,l))}},Te=ze.map(Me),W=[pe,N,ye,ne,xe,...Te],Pe=W.map(({chapter:e})=>e),Oe=W.flatMap(({questions:e})=>e),Fe=e=>Pe.find(i=>i.unitId===e);export{Pe as a,Fe as g,Oe as t};
